CREATE OR REPLACE FUNCTION public.atomic_deduct_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text DEFAULT 'debit'::text, p_description text DEFAULT ''::text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_balance numeric;
  v_club_id uuid;
  v_context_club uuid;
  v_context_tournament uuid;
  v_declared_club uuid;
  v_declared_text text;
  v_has_club boolean;
BEGIN
  IF p_user_id IS NULL
     OR p_amount IS NULL
     OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount <= 0
     OR p_amount <> round(p_amount,2) THEN
    RAISE EXCEPTION 'wallet debit requires a positive two-decimal amount'
      USING ERRCODE='22023';
  END IF;

  v_declared_text:=NULLIF(current_setting('app.ledger_club_id',true),'');
  IF v_declared_text IS NOT NULL THEN
    BEGIN
      v_declared_club:=v_declared_text::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'wallet debit declared club is not a UUID'
        USING ERRCODE='22023';
    END;
    v_club_id:=v_declared_club;
  END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT t.club_id, t.tournament_id INTO v_context_club, v_context_tournament
      FROM public.tables t
     WHERE t.id=p_table_id;
    IF v_context_club IS NULL THEN
      RAISE EXCEPTION 'wallet debit table % has no club context',p_table_id
        USING ERRCODE='P0002';
    END IF;
    IF v_context_tournament IS NOT NULL THEN
      -- THE ENTRY IS CHARGED TO THE WALLET THE ENTRY IS STAMPED WITH
      -- (2026-09-10): a tournament table resolves the wallet the way the
      -- entry stamp does, so a rebuy at a union event comes from the same
      -- member-club wallet the buy-in came from.
      v_context_club:=public.fn_tournament_club_for_user(
        p_user_id,v_context_tournament,v_club_id);
      IF v_context_club IS NULL THEN
        RAISE EXCEPTION 'no club wallet in the union of tournament % resolves for player %',
          v_context_tournament,p_user_id USING ERRCODE='42501';
      END IF;
    END IF;
    IF v_club_id IS NOT NULL AND v_club_id<>v_context_club THEN
      RAISE EXCEPTION 'wallet debit declared club does not own table %',p_table_id
        USING ERRCODE='22023';
    END IF;
    v_club_id:=v_context_club;
  END IF;

  IF p_related_entity_id IS NOT NULL
     AND lower(COALESCE(p_category,'')) IN
       ('tournament_buyin','tournament_rebuy','rebuy','reentry','addon') THEN
    IF NOT EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id=p_related_entity_id
                     AND t.club_id IS NOT NULL) THEN
      RAISE EXCEPTION 'wallet debit tournament % has no club context',
        p_related_entity_id USING ERRCODE='P0002';
    END IF;
    -- THE ENTRY IS CHARGED TO THE WALLET THE ENTRY IS STAMPED WITH
    -- (2026-09-10). trg_tournament_players_stamp_club stamps the entry with
    -- fn_tournament_club_for_user; the debit reads the same function with the
    -- same preferred club, so the wallet a prize returns to is the wallet the
    -- buy-in left. Reading tournaments.club_id here charged the union's house
    -- club for every union-hosted entry (3,232 entries / 73,659.00 in 24h).
    v_context_club:=public.fn_tournament_club_for_user(
      p_user_id,p_related_entity_id,v_club_id);
    IF v_context_club IS NULL THEN
      RAISE EXCEPTION 'no club wallet in the union of tournament % resolves for player %',
        p_related_entity_id,p_user_id USING ERRCODE='42501';
    END IF;
    IF v_club_id IS NOT NULL AND v_club_id<>v_context_club THEN
      RAISE EXCEPTION 'wallet debit declared club does not own tournament %',
        p_related_entity_id USING ERRCODE='22023';
    END IF;
    v_club_id:=v_context_club;
  END IF;

  IF v_club_id IS NULL THEN
    v_club_id:=public.fn_player_home_club(p_user_id,NULL);
  END IF;

  IF v_club_id IS NOT NULL THEN
    IF public.fn_ensure_club_wallet(p_user_id,v_club_id) IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'player % has no active wallet at club %',p_user_id,v_club_id
        USING ERRCODE='42501';
    END IF;
    SELECT cm.chip_balance INTO v_balance
      FROM public.club_members cm
     WHERE cm.user_id=p_user_id AND cm.club_id=v_club_id
       AND cm.status IN ('active','approved')
     FOR UPDATE;
    IF v_balance IS NULL OR v_balance<p_amount THEN
      RETURN false;
    END IF;
    /* THE CALLER NAMES WHERE THE CHIPS GO (2026-10-02, 20261002140203). This
       primitive debits a wallet for a door it does not know. Without a
       declared counterparty the club_members journal books the leg against
       settlement_suspense and the commit check refuses the transaction; say
       so here, by name, before anything moves. */
    IF NULLIF(current_setting('app.ledger_counterparty', true), '') IS NULL
       AND COALESCE(current_setting('app.ledger_autoskip_club_members', true), '') <> '1' THEN
      RAISE EXCEPTION 'atomic_deduct_wallet_and_log_requires_a_declared_counterparty'
        USING ERRCODE = '23514',
              DETAIL  = 'a player wallet debit with no app.ledger_counterparty would be journalled against settlement_suspense',
              HINT    = 'The calling door declares where the chips go (fn_ca_declare_ledger) before it calls, or stands the club_members journal down and writes its own leg.';
    END IF;
    UPDATE public.club_members cm
       SET chip_balance=cm.chip_balance-p_amount,updated_at=now()
     WHERE cm.user_id=p_user_id AND cm.club_id=v_club_id
       AND cm.status IN ('active','approved')
       AND cm.chip_balance>=p_amount;
    IF NOT FOUND THEN
      RETURN false;
    END IF;
    INSERT INTO public.chip_transactions(
      club_id,from_user_id,amount,transaction_type,notes
    ) VALUES (
      v_club_id,p_user_id,p_amount,p_category,
      COALESCE(NULLIF(p_description,''),'Wallet debit')
    );
    RETURN true;
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.club_members cm WHERE cm.user_id=p_user_id
  ) INTO v_has_club;
  IF v_has_club THEN
    RAISE EXCEPTION 'No active club wallet resolves for Club Arena debit from player %',
      p_user_id USING ERRCODE='42501';
  END IF;

  UPDATE public.wallets w
     SET balance=w.balance-p_amount,updated_at=now()
   WHERE w.user_id=p_user_id AND w.wallet_type='PLAYER'
     AND w.balance>=p_amount;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_apply_prize_guarantee(p_tournament_id uuid, p_source text DEFAULT 'engine'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb;
  v_overlay numeric;
  v_ledger_count integer;
  v_escrow public.tournament_escrow%ROWTYPE;
  v_return jsonb := NULL;
  v_refusal jsonb;
BEGIN
  /* A GUARANTEE IS A FLOOR (2026-10-01). The start-time overlay part that
     money collected since has made unnecessary goes back to its bank before
     the pool is finalized, so the final pool is max(guarantee, collected).
     One subtransaction with the finalization: a refused finalization rolls
     the return back too, and the caller sees the refusal unchanged. */
  BEGIN
    v_return := public.fn_ca_return_excess_start_overlay_locked(p_tournament_id);
    v_result:=public.fn_ca_apply_prize_guarantee_core(
      p_tournament_id,p_source);
    IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE THEN
      v_refusal := v_result;
      RAISE EXCEPTION USING ERRCODE='P0405',
        MESSAGE='guarantee finalization refused; the excess return is rolled back with it';
    END IF;
  EXCEPTION WHEN SQLSTATE 'P0405' THEN
    RETURN v_refusal;
  END;
  v_overlay:=COALESCE((v_result->>'overlay')::numeric,0);
  IF v_overlay::text IN ('NaN','Infinity','-Infinity')
     OR v_overlay<0 OR v_overlay IS DISTINCT FROM round(v_overlay,2) THEN
    RAISE EXCEPTION 'guarantee core returned invalid overlay %',v_overlay
      USING ERRCODE='P0404';
  END IF;
  IF v_overlay>0 THEN
    SELECT count(*) INTO v_ledger_count
      FROM public.chip_ledger l
     WHERE l.idempotency_key=
             'tourney:'||p_tournament_id::text||':guarantee_overlay'
       AND l.tournament_id=p_tournament_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=p_tournament_id
       AND l.category='overlay'
       AND l.amount=v_overlay
       AND l.from_entity_id=(v_result->>'bank_entity_id')::uuid
       AND l.from_type=CASE WHEN v_result->>'bank_type'='union'
                            THEN 'union_bank' ELSE 'club_treasury' END;
    SELECT * INTO v_escrow
      FROM public.tournament_escrow e
     WHERE e.tournament_id=p_tournament_id
     FOR UPDATE;
    IF v_ledger_count<>1 OR NOT FOUND
       OR COALESCE(v_escrow.enforced,false) IS NOT TRUE
       OR v_result->>'escrow_after' IS NULL
       OR v_escrow.prize_balance IS DISTINCT FROM
            (v_result->>'escrow_after')::numeric THEN
      RAISE EXCEPTION
        'guarantee overlay is not one exact journaled escrow credit'
        USING ERRCODE='P0404';
    END IF;
  END IF;
  RETURN v_result||jsonb_build_object('overlay_journaled',true)
    ||CASE WHEN v_return IS NOT NULL
           THEN jsonb_build_object('excess_overlay_returned',v_return)
           ELSE '{}'::jsonb END;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_blind_contract_number(p_value jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v numeric; t text:=p_value #>> '{}';
BEGIN
  IF jsonb_typeof(p_value) NOT IN ('number','string') OR t !~ '^[0-9]+([.][0-9]+)?$' THEN RETURN NULL; END IF;
  v:=t::numeric;
  IF v>9007199254740991 THEN RETURN NULL; END IF;
  RETURN v;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_settlement_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_autoskip_tables text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t text;
BEGIN
  -- validate against the LIVE vocabulary so this can never lag a CHECK change
  IF p_category IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_category_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_category || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: category % is not in the ledger vocabulary - add it to chip_ledger_category_check FIRST, then declare it', p_category;
  END IF;
  IF p_counterparty IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_from_type_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_counterparty || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: counterparty % is not in the ledger vocabulary - add it to the from/to type CHECKs FIRST, then declare it', p_counterparty;
  END IF;

  PERFORM set_config('app.ledger_category', p_category, true);
  PERFORM set_config('app.ledger_counterparty', p_counterparty, true);
  PERFORM set_config('app.ledger_counterparty_entity',
                     COALESCE(p_counterparty_entity::text, ''), true);
  /* A COUNTERPARTY NAMES ITS COLUMN, AND A NEW DECLARATION FORGETS THE LAST
     ONE'S (2026-10-04). A union wallet holds six balances; the caller whose
     counterparty is one of them names it on app.ledger_counterparty_label
     after this call, and fn_ca_autoledger writes it on that side. */
  PERFORM set_config('app.ledger_counterparty_label', '', true);
  IF p_settlement_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_settlement', p_settlement_id::text, true);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM set_config('app.ledger_idempotency_key', p_idempotency_key, true);
  END IF;
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH v_t IN ARRAY p_autoskip_tables LOOP
      IF v_t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_declare_ledger: bad autoskip table name %', v_t;
      END IF;
      PERFORM set_config('app.ledger_autoskip_' || v_t, '1', true);
    END LOOP;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_diamond_journal_origin(p_type text, p_transaction_type text, p_source text, p_issuance_class text, p_amount numeric)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_kind  text := lower(COALESCE(NULLIF(btrim(p_transaction_type), ''), NULLIF(btrim(p_type), ''), ''));
  v_class text := lower(COALESCE(NULLIF(btrim(p_issuance_class), ''), ''));
  v_src   text := lower(COALESCE(NULLIF(btrim(p_source), ''), ''));
BEGIN
  IF p_amount IS NULL OR p_amount = 0 THEN RETURN NULL; END IF;
  -- The Mint's own doors register their own rows.
  IF v_src = 'the_mint' THEN RETURN NULL; END IF;
  -- SO DOES THE SEED DOOR. fn_ca_diamond_born_with_balance writes the
  -- 'seed:<id>' register row for the signup grant and then the journal row.
  -- Registering it here as well counts one movement twice (2026-09-05: 18
  -- duplicate pairs, 9,000 diamonds). Named writer, not a class: every OTHER
  -- promotional credit still registers here.
  IF v_kind = 'signup_bonus' OR v_src = 'handle_new_user' THEN RETURN NULL; END IF;
  -- ADDED 20260930055147. A JOURNAL ROW THAT ONLY WRITES DOWN SUPPLY THE
  -- REGISTER ALREADY COUNTED. The pre-2026-09-01 born-with-balance door moved
  -- profiles.diamonds and the register together and skipped the journal, so
  -- 220,985 diamonds sat in wallets that the journal could not explain while
  -- the register could. The backfill that writes those journal rows must not
  -- register them a second time: fn_ca_mint_supply('diamonds') already equals
  -- what players hold, and following these rows would break that identity by
  -- the exact amount of the backfill. Named source, not a class, for the same
  -- reason as the seed door above: every other admin credit still registers.
  IF v_src = 'journal_backfill' THEN RETURN NULL; END IF;
  -- Player to player: supply moves, none is created or retired.
  IF public.fn_ca_diamond_journal_is_transfer(p_type, p_transaction_type, p_source, p_issuance_class) THEN
    RETURN NULL;
  END IF;
  -- THE ARENA DOORS MOVE MONEY, THEY DO NOT ISSUE IT. A deposit takes diamonds out of
  -- profiles.diamonds and puts them in the platform club's member wallet; a withdrawal is the
  -- mirror. The player still owns them and the supply is unchanged, so the register must not
  -- follow either leg - the same treatment, for the same reason, as a player-to-player transfer
  -- above. Classified as 'spend' (deposit) and 'arena' (withdrawal), the register would have
  -- burned the float on the way in and minted it on the way out (2026-09-08).
  IF v_kind IN ('arena_deposit', 'arena_withdraw') THEN RETURN NULL; END IF;
  -- The deletion door writes its own register row.
  IF v_class = 'deletion' THEN RETURN NULL; END IF;
  -- A test fixture row is not supply the Mint issued.
  IF v_kind LIKE 'test%' THEN RETURN NULL; END IF;

  IF p_amount > 0 THEN
    IF v_class = 'purchased' OR v_kind IN ('purchase', 'stripe_purchase', 'diamond_purchase') THEN
      RETURN 'purchase';
    ELSIF v_class = 'refund' OR v_kind LIKE '%refund%' OR v_kind = 'diamond_refund' THEN
      RETURN 'refund';
    ELSIF v_class = 'promotional' OR v_kind IN ('union_grant', 'bonus', 'promo',
                                                 'promo_purchased', 'easter_egg', 'vip_daily',
                                                 'vip_stipend', 'vip_monthly') THEN
      RETURN 'promotion';
    ELSIF v_class = 'admin' OR v_kind IN ('adjustment', 'reconciliation', 'admin', 'admin_grant') THEN
      RETURN 'adjustment';
    -- 'arcade%' only. The 'arena' CLASS now belongs to the arena doors, which are handled
    -- as transfers above; leaving it here would have made a withdrawal mint.
    ELSIF v_kind LIKE 'arcade%' THEN
      RETURN 'arena';
    ELSE
      RETURN 'reward';
    END IF;
  ELSE
    IF v_kind IN ('chip_mint', 'chip_purchase', 'mint_chips', 'diamonds_to_chips') OR v_class = 'bridge' THEN
      RETURN 'bridge';
    ELSIF v_class = 'admin' OR v_kind IN ('adjustment', 'reconciliation', 'admin', 'chargeback', 'clawback') THEN
      RETURN 'adjustment';
    ELSE
      RETURN 'spend';
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_entry_paying_club(p_user_id uuid, p_tournament_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t record;
  v_charge numeric;
  v_default uuid;
  v_balance numeric;
BEGIN
  IF p_user_id IS NULL OR p_tournament_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT t.union_id, t.buy_in_amount, t.buy_in_fee, t.bounty_amount,
         (COALESCE(t.is_bounty, false) OR COALESCE(t.is_pko, false)
          OR COALESCE(t.is_mystery_bounty, false)) AS is_bounty
    INTO v_t
    FROM public.tournaments t WHERE t.id = p_tournament_id;
  IF NOT FOUND OR v_t.union_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF public.fn_ca_tournament_unit_cents(p_tournament_id) = 100 THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id AND tp.user_id = p_user_id) THEN
    RETURN NULL;
  END IF;

  SELECT s.charge INTO v_charge
    FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_t.is_bounty) s;
  IF v_charge IS NULL OR v_charge <= 0 THEN
    RETURN NULL;
  END IF;

  v_default := public.fn_tournament_club_for_user(p_user_id, p_tournament_id, NULL);
  IF v_default IS NOT NULL THEN
    SELECT m.chip_balance INTO v_balance
      FROM public.club_members m
     WHERE m.user_id = p_user_id AND m.club_id = v_default
       AND m.status IN ('active', 'approved');
    IF COALESCE(v_balance, 0) >= v_charge THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN public.fn_ca_union_wallet_that_can_pay(p_user_id, v_t.union_id, v_charge);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_escrow_apply(p_tournament_id uuid, p_what text, p_gross_in numeric DEFAULT 0, p_fee_entries_in numeric DEFAULT 0, p_satellite_fee_in numeric DEFAULT 0, p_bounty_in numeric DEFAULT 0, p_overlay_in numeric DEFAULT 0, p_satellite_in numeric DEFAULT 0, p_prize_out numeric DEFAULT 0, p_bounty_out numeric DEFAULT 0, p_fee_out numeric DEFAULT 0, p_refund numeric DEFAULT 0, p_reserve_out numeric DEFAULT 0, p_reserve_in numeric DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.tournament_escrow%ROWTYPE;
  v_spin boolean; e record; v_sat_fee numeric;
  v_prize_in numeric; v_tot numeric; r_p numeric := 0; r_b numeric := 0; r_f numeric := 0;
  v_outflow boolean := COALESCE(p_prize_out, 0) > 0 OR COALESCE(p_bounty_out, 0) > 0 OR COALESCE(p_fee_out, 0) > 0 OR COALESCE(p_refund, 0) > 0;
  r_out numeric := 0; r_in numeric := 0;
  v_sp_prize numeric; v_sp_bounty numeric;
BEGIN
  SELECT * INTO v FROM public.tournament_escrow WHERE tournament_id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    SELECT (COALESCE(t.variant, '') = 'spin' OR COALESCE(t.is_premium_spin, false)) INTO v_spin
      FROM public.tournaments t WHERE t.id = p_tournament_id;
    IF NOT FOUND THEN
      RETURN;
    END IF;
    SELECT * INTO e FROM public.fn_ca_tournament_escrow(p_tournament_id);
    SELECT COALESCE(sum(rr.rake_amount), 0) INTO v_sat_fee FROM public.rake_records rr
     WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament AND rr.source = 'fn_award_satellite_seat';
    v_prize_in := e.prize_in; v_tot := e.prize_in + e.satellite_in + e.bounty_in + e.fee_in;
    IF v_tot > 0 THEN
      r_p := round(e.refund_out * (e.prize_in + e.satellite_in) / v_tot, 2);
      r_b := round(e.refund_out * e.bounty_in / v_tot, 2);
    ELSE
      r_p := e.refund_out;
    END IF;
    r_f := round(e.refund_out - r_p - r_b, 2);
    /* PHASE 5.2: a spin's prize bank also moves through the reserve.
       2026-09-07: read from spin_reserve_ledger, not from the chip_ledger
       spin_entry / spin_prize legs it used to read. Those legs are the DERIVED
       record and one pair of them went missing: on 2026-09-06 at 12:50:38 both
       legs of tournament afa045db landed as `adjustment` rows into
       settlement_suspense with a NULL entity, their intended category
       surviving only inside the description text. The escrow therefore never
       learned that 60.00 had been drawn for a 60.00 prize, and
       fn_settle_tournament_obligation refused the winner's last 4.80 as
       escrow_short - for a day, with an open critical alert nobody could act
       on. spin_reserve_ledger is the record the pool balance itself moved by;
       it cannot be missing while the money has moved. Verified across 18,318
       escrow rows: 0 disagree with it, 1 was missing the legs entirely. */
    SELECT COALESCE(sum(l.amount) FILTER (WHERE l.kind = 'contribution'), 0),
           COALESCE(-sum(l.amount) FILTER (WHERE l.kind = 'jackpot_draw'), 0)
      INTO r_out, r_in
      FROM public.spin_reserve_ledger l
     WHERE l.tournament_id = p_tournament_id
       AND l.kind IN ('contribution', 'jackpot_draw');
    INSERT INTO public.tournament_escrow
      (tournament_id, enforced, gross_in, fee_entries_in, satellite_fee_in, bounty_in, overlay_in, satellite_in,
       prize_out, bounty_out, fee_out, refund_prize, refund_bounty, refund_fee, reserve_out, reserve_in,
       prize_balance, bounty_balance, fee_balance, opened_from)
    VALUES
      (p_tournament_id, true,
       round(e.prize_in + e.bounty_in + (e.fee_in - v_sat_fee), 2), round(e.fee_in - v_sat_fee, 2), round(v_sat_fee, 2),
       e.bounty_in, e.overlay_in, e.satellite_in, e.prize_out, e.bounty_out, e.fee_out, r_p, r_b, r_f, round(r_out, 2), round(r_in, 2),
       round(e.prize_balance - r_out + r_in, 2), e.bounty_balance, e.fee_balance,
       'shadow at first sight (' || p_what || ')')
    ON CONFLICT (tournament_id) DO NOTHING;
    RETURN;
  END IF;

  IF COALESCE(p_refund, 0) > 0 THEN
    v_prize_in := v.gross_in - v.fee_entries_in - v.bounty_in + v.satellite_in;
    v_tot := v.gross_in + v.satellite_in + v.satellite_fee_in;
    IF v_tot > 0 THEN
      r_p := round(p_refund * v_prize_in / v_tot, 2);
      r_b := round(p_refund * v.bounty_in / v_tot, 2);
    ELSE
      SELECT s.prize, s.bounty INTO v_sp_prize, v_sp_bounty
        FROM public.tournaments t2
        CROSS JOIN LATERAL public.fn_tournament_entry_split(t2.buy_in_amount, t2.buy_in_fee, t2.bounty_amount,
               COALESCE(t2.is_bounty, false) OR COALESCE(t2.is_pko, false) OR COALESCE(t2.is_mystery_bounty, false)) s
       WHERE t2.id = p_tournament_id;
      IF COALESCE(v_sp_prize, 0) + COALESCE(v_sp_bounty, 0) > 0 THEN
        r_p := round(p_refund * v_sp_prize / (v_sp_prize + v_sp_bounty + (SELECT COALESCE(t3.buy_in_fee, 0) FROM public.tournaments t3 WHERE t3.id = p_tournament_id)), 2);
        r_b := round(p_refund * v_sp_bounty / (v_sp_prize + v_sp_bounty + (SELECT COALESCE(t3.buy_in_fee, 0) FROM public.tournaments t3 WHERE t3.id = p_tournament_id)), 2);
      ELSE
        r_p := p_refund;
      END IF;
    END IF;
    r_f := round(p_refund - r_p - r_b, 2);
  END IF;

  UPDATE public.tournament_escrow
     SET gross_in = gross_in + COALESCE(p_gross_in, 0),
         fee_entries_in = fee_entries_in + COALESCE(p_fee_entries_in, 0),
         satellite_fee_in = satellite_fee_in + COALESCE(p_satellite_fee_in, 0),
         bounty_in = bounty_in + COALESCE(p_bounty_in, 0),
         overlay_in = overlay_in + COALESCE(p_overlay_in, 0),
         satellite_in = satellite_in + COALESCE(p_satellite_in, 0),
         prize_out = prize_out + COALESCE(p_prize_out, 0),
         bounty_out = bounty_out + COALESCE(p_bounty_out, 0),
         fee_out = fee_out + COALESCE(p_fee_out, 0),
         refund_prize = refund_prize + r_p, refund_bounty = refund_bounty + r_b, refund_fee = refund_fee + r_f,
         reserve_out = reserve_out + COALESCE(p_reserve_out, 0), reserve_in = reserve_in + COALESCE(p_reserve_in, 0),
         updated_at = now()
   WHERE tournament_id = p_tournament_id;
  UPDATE public.tournament_escrow
     SET prize_balance  = round((gross_in - fee_entries_in - bounty_in) + overlay_in + satellite_in - reserve_out + reserve_in - prize_out - refund_prize, 2),
         bounty_balance = round(bounty_in - bounty_out - refund_bounty, 2),
         fee_balance    = round(fee_entries_in + satellite_fee_in - fee_out - refund_fee, 2)
   WHERE tournament_id = p_tournament_id
   RETURNING * INTO v;

  IF v.enforced AND v_outflow
     AND (v.prize_balance < -0.005 OR v.bounty_balance < -0.005 OR v.fee_balance < -0.005) THEN
    RAISE EXCEPTION 'escrow_short: tournament % cannot pay this % - it would leave prize %, bounty %, fee % (chip standard Phase 5.1: an event pays only what it holds)',
      p_tournament_id, p_what, v.prize_balance, v.bounty_balance, v.fee_balance
      USING ERRCODE = 'P0403';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_escrow_can_pay(p_tournament_id uuid, p_kind text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.tournament_escrow%ROWTYPE; v_have numeric; d record;
BEGIN
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    SELECT * INTO d FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id);
    v_have := CASE WHEN p_kind IN ('bounty', 'mystery_bounty', 'bounty_residual') THEN d.bounty_balance
                   WHEN p_kind = 'refund' THEN d.prize_balance + d.bounty_balance + d.fee_balance
                   ELSE d.prize_balance END;
    RETURN jsonb_build_object('known', true, 'enforced', true, 'available', v_have,
                              'ok', p_amount <= v_have, 'asset', 'diamonds',
                              'prize_balance', d.prize_balance, 'bounty_balance', d.bounty_balance, 'fee_balance', d.fee_balance);
  END IF;
  SELECT * INTO v FROM public.tournament_escrow WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('known', false);
  END IF;
  v_have := CASE WHEN p_kind IN ('bounty', 'mystery_bounty', 'bounty_residual') THEN v.bounty_balance
                 WHEN p_kind = 'refund' THEN v.prize_balance + v.bounty_balance + v.fee_balance
                 ELSE v.prize_balance END;
  RETURN jsonb_build_object('known', true, 'enforced', v.enforced, 'available', v_have,
                            'ok', (NOT v.enforced) OR p_amount <= v_have + 0.005,
                            'prize_balance', v.prize_balance, 'bounty_balance', v.bounty_balance, 'fee_balance', v.fee_balance);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_guard_new_satellite_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_abi text; v_target uuid:=COALESCE(NEW.satellite_target_id,NEW.satellite_target);
 v_target_row public.tournaments%ROWTYPE; v_supported boolean;
 v_source_diamond boolean;  -- DIAMOND PHASE 9
BEGIN
 IF TG_OP='UPDATE' AND
   (NEW.satellite_target_id,NEW.satellite_target,NEW.is_bounty,NEW.is_pko,NEW.is_mystery_bounty,
    NEW.is_premium_spin,NEW.variant,NEW.tournament_type,NEW.club_id,NEW.union_id)
   IS NOT DISTINCT FROM
   (OLD.satellite_target_id,OLD.satellite_target,OLD.is_bounty,OLD.is_pko,OLD.is_mystery_bounty,
    OLD.is_premium_spin,OLD.variant,OLD.tournament_type,OLD.club_id,OLD.union_id) THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 -- DIAMOND PHASE 9: ASSETS NEVER CROSS, under every admission contract. A
 -- satellite and its target are the same asset or the row is refused by name.
 v_source_diamond:=EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=NEW.club_id AND c.asset='diamonds');
 IF v_target IS NOT NULL AND EXISTS(SELECT 1 FROM public.tournaments x WHERE x.id=v_target) THEN
  IF v_source_diamond AND NOT public.fn_poker_diamond_tournament(v_target) THEN
   RAISE EXCEPTION 'SATELLITE_DIAMOND_SOURCE_CANNOT_FEED_A_CHIP_TARGET' USING ERRCODE='22023';
  ELSIF NOT v_source_diamond AND public.fn_poker_diamond_tournament(v_target) THEN
   RAISE EXCEPTION 'SATELLITE_CHIP_SOURCE_CANNOT_FEED_A_DIAMOND_TARGET' USING ERRCODE='22023';
  END IF;
 END IF;
 IF v_abi='legacy-capacity-v1' THEN RETURN NEW;END IF;
 IF NEW.satellite_target_id IS NOT NULL AND NEW.satellite_target IS NOT NULL
    AND NEW.satellite_target_id<>NEW.satellite_target THEN
  RAISE EXCEPTION 'SATELLITE_TARGET_POINTER_CONTRADICTION' USING ERRCODE='22023';
 END IF;
 -- Under READ COMMITTED the post-lock query sees a just-committed feeder.
 -- A repeatable snapshot could otherwise permit an incompatible target edit.
 IF current_setting('transaction_isolation')<>'read committed'
    AND (TG_OP='UPDATE' OR v_target IS NOT NULL) THEN
  RAISE EXCEPTION 'SATELLITE_CONTRACT_REQUIRES_READ_COMMITTED' USING ERRCODE='0A000';
 END IF;
 v_supported:=NEW.is_bounty IS FALSE AND NEW.is_pko IS FALSE AND NEW.is_mystery_bounty IS FALSE
   AND NEW.is_premium_spin IS FALSE
   AND lower(btrim(COALESCE(NEW.variant,''))) NOT IN
    ('spin','bounty','progressive','progressive_bounty','pko','mystery','mystery_bounty')
   AND lower(btrim(COALESCE(NEW.tournament_type,''))) NOT IN
    ('spin','bounty','progressive','progressive_bounty','pko','mystery','mystery_bounty');
 -- DIAMOND PHASE 9: a Diamond row is supported like a chip row; the asset rule
 -- above decides which targets it may feed, and a target fed by a live
 -- satellite may not change its asset.
 IF TG_OP='UPDATE' AND (NOT v_supported OR v_target IS NOT NULL
      OR v_source_diamond IS DISTINCT FROM
         EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=OLD.club_id AND c.asset='diamonds')
      OR lower(COALESCE(NEW.variant,''))='satellite' OR upper(COALESCE(NEW.tournament_type,''))='SATELLITE')
   AND EXISTS(SELECT 1 FROM public.tournaments s WHERE s.format_contract='mtt-v2'
     AND (s.satellite_target_id=NEW.id OR s.satellite_target=NEW.id) AND s.id<>NEW.id
     AND upper(COALESCE(s.status,'')) NOT IN ('COMPLETED','CANCELLED','CANCELED')) THEN
  RAISE EXCEPTION 'SATELLITE_LIVE_TARGET_CANNOT_BECOME_UNSUPPORTED' USING ERRCODE='22023';
 END IF;
 IF v_target IS NULL AND (lower(COALESCE(NEW.variant,''))='satellite'
    OR upper(COALESCE(NEW.tournament_type,''))='SATELLITE') THEN
  RAISE EXCEPTION 'SATELLITE_NEW_TARGET_REQUIRED' USING ERRCODE='22023';
 END IF;
 IF v_target IS NOT NULL THEN
  IF NOT v_supported THEN RAISE EXCEPTION 'SATELLITE_NEW_SOURCE_UNSUPPORTED' USING ERRCODE='22023';END IF;
  SELECT * INTO v_target_row FROM public.tournaments WHERE id=v_target FOR UPDATE;
  IF NOT FOUND OR NOT (CASE WHEN v_source_diamond  -- DIAMOND PHASE 9
       THEN public.fn_ca_diamond_satellite_target_accepts_new_feeder(v_target)
       ELSE public.fn_ca_satellite_target_accepts_new_feeder(v_target) END)
     OR (NEW.union_id IS NOT NULL AND v_target_row.union_id IS DISTINCT FROM NEW.union_id)
     OR (NEW.union_id IS NULL AND (v_target_row.club_id IS DISTINCT FROM NEW.club_id OR v_target_row.union_id IS NOT NULL)) THEN
   RAISE EXCEPTION 'SATELLITE_NEW_TARGET_UNSUPPORTED' USING ERRCODE='22023';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_guard_tournament_format()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_format text; v_abi text;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.format_contract IS NOT NULL THEN
      RAISE EXCEPTION 'TOURNAMENT_FORMAT_IS_DATABASE_ASSIGNED' USING ERRCODE='22023';
    END IF;
    v_abi:=public.fn_ca_lock_mtt_admission_contract();
    IF v_abi='unlimited-mtt-v2' AND public.fn_ca_is_new_mtt(to_jsonb(NEW)) THEN
      IF NEW.max_players IS NOT NULL OR COALESCE(NEW.min_players,0)<3 THEN
        RAISE EXCEPTION 'MTT_V2_CAPACITY_NOT_NORMALIZED' USING ERRCODE='23514';
      END IF;
      v_format:='mtt-v2';
    ELSE
      v_format:=public.fn_ca_legacy_tournament_format(to_jsonb(NEW));
    END IF;
    IF v_format IS NULL THEN
      RAISE EXCEPTION 'TOURNAMENT_LEGACY_FORMAT_AMBIGUOUS' USING ERRCODE='23514';
    END IF;
    NEW.format_contract:=v_format;
    RETURN NEW;
  END IF;
  IF NEW.format_contract IS DISTINCT FROM OLD.format_contract THEN
    RAISE EXCEPTION 'TOURNAMENT_FORMAT_IMMUTABLE' USING ERRCODE='55000';
  END IF;
  IF OLD.format_contract='mtt-v2' THEN
    IF NOT public.fn_ca_is_new_mtt(to_jsonb(NEW)) OR NEW.max_players IS NOT NULL
       OR COALESCE(NEW.min_players,0)<3 THEN
      RAISE EXCEPTION 'TOURNAMENT_FORMAT_IDENTITY_CONFLICT' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
  END IF;
  IF public.fn_ca_tournament_format_identity(to_jsonb(NEW))
      IS DISTINCT FROM public.fn_ca_tournament_format_identity(to_jsonb(OLD))
     AND (OLD.format_contract IS NULL
          OR public.fn_ca_legacy_tournament_format(to_jsonb(NEW)) IS DISTINCT FROM OLD.format_contract) THEN
    RAISE EXCEPTION 'TOURNAMENT_FORMAT_IDENTITY_CONFLICT' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_guard_tournament_restart_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_source public.tournaments%ROWTYPE; v_target_row public.tournaments%ROWTYPE;
 v_abi text; v_target uuid; v_column text; v_total numeric; v_fee numeric; v_mtt boolean;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.restart_source_id IS NOT NULL THEN RAISE EXCEPTION 'TOURNAMENT_RESTART_HISTORY_IMMUTABLE' USING ERRCODE='22023';END IF;
  RETURN OLD;
 ELSIF TG_OP='UPDATE' THEN
  IF NEW.restart_source_id IS DISTINCT FROM OLD.restart_source_id THEN
   RAISE EXCEPTION 'TOURNAMENT_RESTART_SOURCE_IMMUTABLE' USING ERRCODE='22023';END IF;
  RETURN NEW;
 END IF;
 IF NEW.restart_source_id IS NULL THEN RETURN NEW;END IF;
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'service_role required for tournament restart' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 IF public.fn_entry_purchases_frozen() THEN RAISE EXCEPTION 'TOURNAMENT_RESTART_PLATFORM_FROZEN' USING ERRCODE='55000';END IF;
 SELECT * INTO v_source FROM public.tournaments WHERE id=NEW.restart_source_id FOR UPDATE;
 IF NOT FOUND OR upper(COALESCE(v_source.status,''))<>'COMPLETED' OR v_source.ended_at IS NULL
    OR v_source.schedule_id IS NOT NULL OR COALESCE(v_source.restart_every_minutes,0)<=0
    OR NEW.club_id IS DISTINCT FROM v_source.club_id OR NEW.union_id IS DISTINCT FROM v_source.union_id
    OR NEW.game_type IS DISTINCT FROM v_source.game_type OR NEW.status IS DISTINCT FROM 'REGISTERING'
    OR NEW.current_players IS DISTINCT FROM 0 OR NEW.schedule_id IS NOT NULL OR NEW.start_time IS NULL
    OR NOT isfinite(NEW.start_time) OR NEW.start_time<=clock_timestamp() THEN
  RAISE EXCEPTION 'TOURNAMENT_RESTART_INVALID_SOURCE' USING ERRCODE='22023';END IF;
 -- NULL terminal parents have no historical exemption. Seat-first/Spin games
 -- are replaced by their board, never cloned by the timed restart path.
 v_mtt:=v_source.format_contract IN ('mtt-v1','mtt-v2');
 IF v_source.format_contract IS NULL OR v_source.format_contract NOT IN ('mtt-v1','mtt-v2','sng-v1')
    OR NEW.format_contract IS NOT NULL
    OR (v_mtt AND NOT public.fn_ca_is_new_mtt(to_jsonb(NEW)))
    OR (v_source.format_contract='sng-v1' AND (COALESCE(v_source.max_players,0)<=2
      OR public.fn_ca_is_new_mtt(to_jsonb(NEW))
      OR v_source.satellite_target_id IS NOT NULL OR v_source.satellite_target IS NOT NULL)) THEN
  RAISE EXCEPTION 'TOURNAMENT_RESTART_FORMAT_MISMATCH' USING ERRCODE='22023';END IF;
 FOREACH v_column IN ARRAY ARRAY['club_id','union_id','is_xmtt','name','game_type','variant','tournament_type','starting_chips','blind_structure','payout_structure','payout_percent','guaranteed_prize','late_reg_levels','late_reg_mins','rebuy_levels','is_rebuy','is_reentry','rebuy_cost','rebuy_chips','add_on_available','addon_cost','addon_chips','addon_levels','is_bounty','bounty_amount','is_pko','is_mystery_bounty','mystery_bounty_min','mystery_bounty_max','mystery_bounty_profile','mystery_bounty_activation','mystery_bounty_activation_value','mystery_bounty_pool_percent','mystery_bounty_regular_pool_percent','mystery_bounty_top_percent','spin_type','satellite_seats','is_private','short_description','is_vip_only','ban_chat','all_in_or_fold','label_as_new','hide_club_name','action_time_seconds','table_size','accelerated_mtt','addon_break_minutes','big_blind_ante','authorized_to_register','early_bird_enabled','early_bird_chips','bubble_protection','final_table_deal_enabled','restart_every_minutes','synchronized_breaks','max_rebuys','max_reentries','is_multi_day','total_days','is_pinned'] LOOP
  IF to_jsonb(NEW)->v_column IS DISTINCT FROM to_jsonb(v_source)->v_column THEN
   RAISE EXCEPTION 'TOURNAMENT_RESTART_BUSINESS_MISMATCH: %',v_column USING ERRCODE='22023';END IF;
 END LOOP;
 IF ((v_abi='legacy-capacity-v1' OR NOT v_mtt) AND (NEW.max_players IS DISTINCT FROM v_source.max_players
      OR NEW.min_players IS DISTINCT FROM v_source.min_players))
    OR (v_abi='unlimited-mtt-v2' AND v_mtt AND (NEW.max_players IS NOT NULL
      OR NEW.min_players IS DISTINCT FROM GREATEST(3,COALESCE(v_source.min_players,3)))) THEN
  RAISE EXCEPTION 'TOURNAMENT_RESTART_CAPACITY_MISMATCH' USING ERRCODE='22023';END IF;
 -- The existing caller only repairs an out-of-policy legacy fee split. Its
 -- player-paid total is fixed, and compliant booked splits pass unchanged.
 v_total:=v_source.buy_in_amount+v_source.buy_in_fee;
 v_fee:=LEAST(v_source.buy_in_fee,trunc(v_total*0.1*100)/100);
 IF v_total IS NULL OR v_total::text IN ('NaN','Infinity','-Infinity')
    OR NEW.buy_in_fee IS DISTINCT FROM v_fee OR NEW.buy_in_amount IS DISTINCT FROM v_total-v_fee THEN
  RAISE EXCEPTION 'TOURNAMENT_RESTART_PRICE_MISMATCH' USING ERRCODE='22023';END IF;
 IF (v_source.satellite_target_id IS NOT NULL AND v_source.satellite_target IS NOT NULL
      AND v_source.satellite_target_id<>v_source.satellite_target)
    OR (NEW.satellite_target_id IS NOT NULL AND NEW.satellite_target IS NOT NULL
      AND NEW.satellite_target_id<>NEW.satellite_target) THEN
  RAISE EXCEPTION 'TOURNAMENT_RESTART_TARGET_MISMATCH' USING ERRCODE='22023';END IF;
 v_target:=COALESCE(v_source.satellite_target_id,v_source.satellite_target);
 IF COALESCE(NEW.satellite_target_id,NEW.satellite_target) IS DISTINCT FROM v_target
    OR (v_target IS NULL AND (upper(COALESCE(v_source.tournament_type,''))='SATELLITE'
      OR lower(COALESCE(v_source.variant,''))='satellite')) THEN
  RAISE EXCEPTION 'TOURNAMENT_RESTART_TARGET_MISMATCH' USING ERRCODE='22023';END IF;
 IF v_target IS NOT NULL THEN
  SELECT * INTO v_target_row FROM public.tournaments WHERE id=v_target FOR UPDATE;
  IF NOT FOUND OR upper(v_target_row.status) NOT IN ('ANNOUNCED','REGISTERING')
    OR v_target_row.start_time IS NULL OR NOT isfinite(v_target_row.start_time)
    OR v_target_row.start_time<=NEW.start_time OR v_target_row.prize_pool_finalized IS TRUE
    OR (NEW.union_id IS NOT NULL AND v_target_row.union_id IS DISTINCT FROM NEW.union_id)
    OR (NEW.union_id IS NULL AND (v_target_row.club_id IS DISTINCT FROM NEW.club_id OR v_target_row.union_id IS NOT NULL))
    OR NOT public.fn_ca_satellite_target_accepts_new_feeder(v_target) THEN
   RAISE EXCEPTION 'TOURNAMENT_RESTART_TARGET_UNAVAILABLE' USING ERRCODE='22023';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_lock_mtt_admission_contract()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
  SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton FOR SHARE;
  IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN
    RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';
  END IF;
  RETURN v_abi;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_lock_settlement_lane_for_finish(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_held text := COALESCE(current_setting('ca.finish_lane_tournament', true), '');
  v_held_scope text := COALESCE(current_setting('ca.finish_lane_scope', true), '');
  -- Unknown until the row proves it is a plain tournament: the whole lane.
  v_satellite boolean := true;
  v_scope text;
BEGIN
  -- Re-entry: this transaction already holds a finish lane. Every key below
  -- is already held by this backend, so nothing waits; a second tournament
  -- is refused, a transaction never holds two tournaments' lanes. (Inside a
  -- satellite finish or a sweep, F is held exclusively by this backend, so F
  -- shared is granted at once and no scope key is named.)
  IF v_held <> '' THEN
    IF p_tournament_id IS NOT NULL AND v_held <> p_tournament_id::text THEN
      RAISE EXCEPTION 'finish lane is held for tournament %, refused for %',
        v_held, p_tournament_id USING ERRCODE = '55000';
    END IF;
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-terminal-settlement:v1', 0));
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-finish-lane:v1', 0));
    IF v_held_scope <> '' THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('ca:tournament-finish-lane:v1:scope:' || v_held_scope, 0));
    END IF;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('ca:tournament-terminal-settlement:v1:' || v_held, 0));
    RETURN;
  END IF;

  -- Resolve the tournament before any lock. variant, tournament_type and the
  -- satellite target are fixed for the life of the row, so reading them
  -- unlocked gives the answer reading them under the lane would. The bank
  -- scope is the host club's union, else the host club; the finish itself
  -- refuses (40001) if the club changes union before it holds the banks.
  IF p_tournament_id IS NOT NULL THEN
    SELECT (lower(COALESCE(t.variant::text, '')) = 'satellite'
            OR upper(COALESCE(t.tournament_type::text, '')) = 'SATELLITE'
            OR t.satellite_target_id IS NOT NULL
            OR t.satellite_target IS NOT NULL),
           COALESCE(c.union_id::text, t.club_id::text, '')
      INTO v_satellite, v_scope
      FROM public.tournaments t
      LEFT JOIN public.clubs c ON c.id = t.club_id
     WHERE t.id = p_tournament_id;
    IF NOT FOUND THEN
      v_satellite := true;
    END IF;
  END IF;

  -- A satellite finish writes the target tournament's rows, and an unknown
  -- tournament cannot be scoped: the whole lane, as it always was.
  IF v_satellite OR COALESCE(v_scope, '') = '' THEN
    PERFORM public.fn_ca_lock_settlement_lane_global();
    RETURN;
  END IF;

  -- G SHARED: waits for, and excludes, the rare global authorities (G
  -- exclusive) and nothing else.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));
  -- F SHARED: satellite finishes and sweeps hold F exclusively and still
  -- exclude every ordinary finish; ordinary finishes no longer exclude
  -- each other platform-wide.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-finish-lane:v1', 0));
  -- F(scope) EXCLUSIVE: one finish at a time per bank scope, so finishes
  -- that share a club wallet, union bank, club treasury or the players'
  -- wallets in those clubs keep the order they had under F exclusive.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-finish-lane:v1:scope:' || v_scope, 0));
  -- T(id) EXCLUSIVE: this tournament's hands (T shared) and rolling
  -- authorities (T exclusive) wait for the finish, and the proof-of-
  -- authority guards read it as this backend's authority over the rows.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || p_tournament_id::text, 0));
  -- The rest of this transaction re-enters this lane through
  -- fn_ca_lock_settlement_lane_global; transaction-local, gone at commit.
  PERFORM set_config('ca.finish_lane_scope', v_scope, true);
  PERFORM set_config('ca.finish_lane_tournament', p_tournament_id::text, true);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_lock_tournament_seat_acquisition(p_tournament_id uuid, p_table_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tournament_id uuid:=p_tournament_id;
  v_table_tournament_id uuid;
  v_status text;
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id, p_table_id);
  PERFORM pg_advisory_xact_lock_shared(530093);
  IF EXISTS(SELECT 1 FROM public.ca_operator_floor_hold h JOIN public.ca_launch_operator_scopes m ON m.operation_id=h.operation_id JOIN public.tournaments t ON t.id=COALESCE(p_tournament_id,(SELECT tournament_id FROM public.tables WHERE id=p_table_id)) WHERE h.mode='park' AND (t.club_id=ANY(m.club_ids) OR t.union_id=ANY(m.club_ids)) AND NOT EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=t.id AND tp.user_id=p_user_id)) THEN
    RETURN jsonb_build_object('ok',false,'reason','operator_floor_parked');
  END IF;
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  PERFORM public.fn_ca_lock_mtt_admission_contract();

  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;

  -- DIAMOND PHASE 11: every seat's player takes the table-cap lock before the
  -- Daily Missions lock, which locks the player's profile row. Every cash seat
  -- door, chip and Diamond, takes table_cap first; for a Diamond player the
  -- profile row is the wallet, and one player's chip entry, Diamond entry and
  -- Diamond cash seat meet on these two locks, so the order is one for every
  -- event whatever its asset. The roster trigger's own table_cap is re-entrant.
  IF p_user_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || p_user_id::text, 0));
    PERFORM public.fn_lock_daily_mission_user(p_user_id);
  END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT tb.tournament_id INTO v_table_tournament_id
      FROM public.tables tb
     WHERE tb.id=p_table_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok',false,'reason','table_not_found');
    END IF;
    IF v_table_tournament_id IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','not_a_tournament_table');
    END IF;
    IF v_tournament_id IS NOT NULL
       AND v_tournament_id IS DISTINCT FROM v_table_tournament_id THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','table_tournament_mismatch');
    END IF;
    v_tournament_id:=v_table_tournament_id;
  END IF;

  IF v_tournament_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_or_table_required');
  END IF;

  -- Launch completion already owns receipt -> tournament. Re-entering these
  -- locks from every seat root makes the historical aa_ launch-proof trigger
  -- a no-op lock acquisition rather than a late inversion.
  PERFORM r.tournament_id
    FROM public.tournament_launch_receipts r
   WHERE r.tournament_id=v_tournament_id
   ORDER BY r.tournament_id
   FOR UPDATE;

  SELECT upper(COALESCE(t.status::text,'')) INTO v_status
    FROM public.tournaments t
   WHERE t.id=v_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  IF v_status NOT IN ('ANNOUNCED','REGISTERING','RUNNING') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_seatable','status',v_status);
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'tournament_id',v_tournament_id,
    'table_id',p_table_id,'status',v_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_mtt_blind_contract(p_structure text, p_starting_chips integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  levels jsonb; r jsonb; i integer:=0; played integer:=0;
  sb numeric; bb numeric; ante numeric; mins numeric; secs numeric; opening numeric;
  previous_sb numeric:=-1; previous_bb numeric:=-1; speed text;
BEGIN
  IF p_starting_chips IS NULL OR p_starting_chips<=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: starting stack must be a positive whole number' USING ERRCODE='22023';
  END IF;
  BEGIN levels:=p_structure::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: unreadable ladder' USING ERRCODE='22023';
  END;
  IF levels IS NULL OR jsonb_typeof(levels)<>'array' THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(levels)=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(levels) LOOP
    i:=i+1;
    IF jsonb_typeof(r)<>'object' THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % must be an object',i USING ERRCODE='22023';
    END IF;
    IF r ? 'isBreak' AND jsonb_typeof(r->'isBreak')<>'boolean' THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % has an invalid break flag',i USING ERRCODE='22023';
    END IF;
    mins:=public.fn_ca_blind_contract_number(COALESCE(NULLIF(r->'durationMinutes','null'::jsonb),r->'duration_minutes'));
    secs:=public.fn_ca_blind_contract_number(r->'duration');
    IF COALESCE(mins,0)<=0 AND COALESCE(secs,0)<=0 THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % needs a positive duration',i USING ERRCODE='22023';
    END IF;
    sb:=public.fn_ca_blind_contract_number(r->'smallBlind');
    bb:=public.fn_ca_blind_contract_number(r->'bigBlind');
    ante:=CASE WHEN r ? 'ante' THEN public.fn_ca_blind_contract_number(r->'ante') ELSE 0 END;
    IF sb IS NULL OR bb IS NULL OR ante IS NULL THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % has invalid blinds or ante',i USING ERRCODE='22023';
    END IF;
    IF r->'isBreak'='true'::jsonb THEN
      IF i=1 OR sb<>0 OR bb<>0 OR ante<>0 THEN
        RAISE EXCEPTION 'Invalid tournament blind structure: level % is not a valid break',i USING ERRCODE='22023';
      END IF;
      CONTINUE;
    END IF;
    IF bb<=0 OR sb>bb THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % needs a positive big blind at least as large as its small blind',i USING ERRCODE='22023';
    END IF;
    IF sb<previous_sb OR bb<previous_bb THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % decreases the blinds',i USING ERRCODE='22023';
    END IF;
    IF played=0 THEN opening:=CASE WHEN mins>0 THEN mins ELSE secs/60 END; END IF;
    previous_sb:=sb; previous_bb:=bb; played:=played+1;
  END LOOP;
  IF played=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  speed:=CASE WHEN opening<=2 THEN 'hyper_turbo' WHEN opening<=5 THEN 'turbo' WHEN opening>=12 THEN 'slow' ELSE 'standard' END;
  RETURN jsonb_build_object('blind_speed',speed,'is_turbo',speed IN ('turbo','hyper_turbo'));
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_new_tournament_is_unlimited(p_config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 RETURN v_abi='unlimited-mtt-v2' AND public.fn_ca_is_new_mtt(p_config);
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_normalize_new_mtt_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_unlimited boolean;
BEGIN
 v_unlimited:=public.fn_ca_new_tournament_is_unlimited(to_jsonb(NEW));
 IF TG_OP='INSERT' THEN
  IF v_unlimited THEN
   IF public.fn_entry_purchases_frozen() THEN
    RAISE EXCEPTION 'MTT_CREATION_PLATFORM_FROZEN' USING ERRCODE='55000';
   END IF;
   NEW.max_players:=NULL;
   NEW.min_players:=GREATEST(3,COALESCE(NEW.min_players,3));
   IF COALESCE(NEW.satellite_target_id,NEW.satellite_target) IS NOT NULL
      AND (upper(COALESCE(NEW.tournament_type,'')) IN ('SNG','SPIN')
           OR lower(COALESCE(NEW.variant,'')) IN ('sng','spin')) THEN
    RAISE EXCEPTION 'NEW_SATELLITE_REQUIRES_SCHEDULED_MTT_CONFIG' USING ERRCODE='55000';
   END IF;
  END IF;
 ELSIF OLD.format_contract='mtt-v2' THEN
  IF NOT v_unlimited THEN
   RAISE EXCEPTION 'MTT_V2_REQUIRES_ACTIVE_ADMISSION' USING ERRCODE='55000';
  END IF;
  NEW.max_players:=NULL;
 ELSIF v_unlimited AND OLD.format_contract='mtt-v1' THEN
  -- A now-irrelevant cap edit cannot rewrite an accepted version1 contract.
  NEW.max_players:=OLD.max_players;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_places int;
  v_pct    numeric;
  v_out    jsonb;
BEGIN
  v_pct := CASE WHEN p_percent IN (10,15,20) THEN p_percent ELSE 10 END;

  -- at least one place, never more places than players
  v_places := GREATEST(1, LEAST(COALESCE(p_entrants,0),
                                ceil(COALESCE(p_entrants,0) * v_pct / 100.0)::int));
  IF COALESCE(p_entrants,0) <= 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH w AS (
    SELECT i AS place, 1.0 / power(i, 0.8) AS weight
      FROM generate_series(1, v_places) i
  ), n AS (
    SELECT place, weight, 100.0 * weight / SUM(weight) OVER () AS exact
      FROM w
  ), f AS (
    SELECT place, exact,
           floor(exact * 100) / 100 AS floored,
           (exact * 100) - floor(exact * 100) AS frac
      FROM n
  ), r AS (
    -- largest remainder: hand the leftover cents to the biggest fractions, so
    -- the structure sums to exactly 100.00 for any field size
    SELECT place, floored,
           row_number() OVER (ORDER BY frac DESC, place ASC) AS rk,
           round((100.0 - SUM(floored) OVER ()) * 100)::int AS cents_left
      FROM f
  )
  SELECT jsonb_agg(
           jsonb_build_object('place', place,
                              'percentage', floored + CASE WHEN rk <= cents_left THEN 0.01 ELSE 0 END)
           ORDER BY place)
    INTO v_out
    FROM r;

  RETURN COALESCE(v_out, '[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_prize_ladder(p_pool_cents bigint, p_entries jsonb, p_unit_cents integer DEFAULT 1)
 RETURNS TABLE(place integer, cents bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_unit bigint;
  v_total_bp bigint;
  v_count integer;
  v_places integer[];
  v_bps bigint[];
  v_remaining bigint;
  v_share bigint;
  i integer;
BEGIN
  v_unit := CASE WHEN p_unit_cents IS NOT NULL AND p_unit_cents >= 1
                 THEN p_unit_cents::bigint ELSE 1 END;
  IF p_pool_cents IS NULL OR p_pool_cents <= 0
     OR p_entries IS NULL OR jsonb_typeof(p_entries) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_entries) = 0 THEN
    RETURN;
  END IF;

  SELECT array_agg((e->>'place')::integer ORDER BY (e->>'place')::integer),
         array_agg((e->>'bp')::bigint ORDER BY (e->>'place')::integer),
         COALESCE(sum((e->>'bp')::bigint), 0),
         count(*)
    INTO v_places, v_bps, v_total_bp, v_count
    FROM jsonb_array_elements(p_entries) e;
  IF v_total_bp <= 0 OR v_count = 0 THEN RETURN; END IF;

  -- THE SHORT FIELD. A pool holding fewer units than there are places pays the
  -- places it CAN, one unit each from the top. Left alone, every share below
  -- rounds to zero and the last place absorbs the pool as its "residual": the
  -- whole prize to the last finisher and nothing to the first. An indivisible
  -- unit cannot be split nine ways, and every other answer pays somebody more
  -- than the player who beat them.
  IF v_unit > 1 AND (p_pool_cents / v_unit) < v_count THEN
    FOR i IN 1..v_count LOOP
      place := v_places[i];
      cents := CASE WHEN i <= (p_pool_cents / v_unit) THEN v_unit ELSE 0 END;
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- Spend down in place order; the LAST paid place takes whatever remains, so
  -- the places sum to the pool exactly rather than by hoping the rounding
  -- cancels, and the adjustment lands on the smallest prize.
  v_remaining := p_pool_cents;
  FOR i IN 1..v_count LOOP
    IF i = v_count THEN
      v_share := v_remaining;
    ELSE
      v_share := LEAST(v_remaining,
        (round(round((p_pool_cents::numeric * v_bps[i]::numeric) / v_total_bp::numeric)
               / v_unit::numeric) * v_unit)::bigint);
    END IF;
    v_share := GREATEST(v_share, 0);
    v_remaining := v_remaining - v_share;
    place := v_places[i];
    cents := v_share;
    RETURN NEXT;
  END LOOP;

  IF v_remaining <> 0 THEN
    RAISE EXCEPTION 'prize ladder left % cents undistributed', v_remaining
      USING ERRCODE = '23514';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_prize_ladder_v2(p_pool_cents bigint, p_entries jsonb, p_unit_cents integer)
 RETURNS TABLE(place integer, cents bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_entry jsonb;
  v_place numeric;
  v_bp numeric;
  v_total numeric;
  v_units bigint;
BEGIN
  IF p_pool_cents IS NULL OR p_pool_cents<0
     OR p_unit_cents IS NULL OR p_unit_cents<1 THEN
    RAISE EXCEPTION 'Prize pool must contain whole payout units' USING ERRCODE='22023';
  END IF;
  IF p_pool_cents%p_unit_cents<>0 THEN
    RAISE EXCEPTION 'Prize pool must contain whole payout units' USING ERRCODE='22023';
  END IF;
  IF p_entries IS NULL OR jsonb_typeof(p_entries)<>'array'
     OR jsonb_array_length(p_entries)=0 THEN
    RAISE EXCEPTION 'Version 2 requires a canonical payout ladder' USING ERRCODE='22023';
  END IF;
  FOR v_entry IN SELECT value FROM jsonb_array_elements(p_entries) LOOP
    IF jsonb_typeof(v_entry)<>'object'
       OR jsonb_typeof(v_entry->'place') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_entry->'bp') IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION 'Canonical payout entries must contain numeric places and basis points'
        USING ERRCODE='22023';
    END IF;
    v_place:=(v_entry->>'place')::numeric;
    v_bp:=(v_entry->>'bp')::numeric;
    IF v_place<1 OR v_place>2147483647 OR v_place<>trunc(v_place)
       OR v_bp<=0 OR v_bp>10000 OR v_bp<>trunc(v_bp) THEN
      RAISE EXCEPTION 'Invalid canonical payout place or basis points' USING ERRCODE='22023';
    END IF;
  END LOOP;
  IF EXISTS (
    WITH entries AS (
      SELECT (e->>'place')::integer AS finish,(e->>'bp')::bigint AS bp
      FROM jsonb_array_elements(p_entries) e
    ), ranked AS (
      SELECT i.*,row_number() OVER(ORDER BY i.finish) AS ordinal,
        lag(i.bp) OVER(ORDER BY i.finish) AS prior_bp FROM entries i
    ) SELECT 1 FROM ranked r WHERE r.finish<>r.ordinal OR r.bp>r.prior_bp
  ) THEN
    RAISE EXCEPTION 'Version 2 requires contiguous places and nonincreasing percentages'
      USING ERRCODE='22023';
  END IF;
  IF p_pool_cents=0 THEN RETURN; END IF;
  SELECT sum((e->>'bp')::numeric) INTO v_total FROM jsonb_array_elements(p_entries) e;
  v_units:=p_pool_cents/p_unit_cents;
  RETURN QUERY
    WITH quotas AS (
      SELECT (e->>'place')::integer AS finish,
        floor(v_units::numeric*(e->>'bp')::numeric/v_total) AS units,
        mod(v_units::numeric*(e->>'bp')::numeric,v_total) AS remainder
      FROM jsonb_array_elements(p_entries) e
    ), ordered AS (
      SELECT q.*,row_number() OVER(ORDER BY q.remainder DESC,q.finish) AS priority
      FROM quotas q
    ), residual AS (SELECT v_units-sum(q.units) AS units FROM quotas q)
    SELECT q.finish,((q.units+CASE WHEN q.priority<=r.units THEN 1 ELSE 0 END)*p_unit_cents)::bigint
    FROM ordered q CROSS JOIN residual r ORDER BY q.finish;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_prize_ladder_versioned(p_pool_cents bigint, p_entries jsonb, p_unit_cents integer, p_version integer)
 RETURNS TABLE(place integer, cents bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_version=1 THEN
    RETURN QUERY SELECT l.place,l.cents FROM public.fn_ca_prize_ladder(p_pool_cents,p_entries,p_unit_cents) l;
  ELSIF p_version=2 THEN
    RETURN QUERY SELECT l.place,l.cents FROM public.fn_ca_prize_ladder_v2(p_pool_cents,p_entries,p_unit_cents) l;
  ELSE
    RAISE EXCEPTION 'Unsupported tournament payout math version' USING ERRCODE='22023';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_process_tournament_chip_purchase_money_v1(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_original_entitlement uuid; v_original_wallet uuid;
  v_t record;
  v_p record;
  v_unit integer := public.fn_ca_tournament_unit_cents(p_tournament_id);  -- DIAMOND PHASE 8
  v_dia jsonb;                                                              -- DIAMOND PHASE 8
  v_balance numeric;
  v_ratio numeric;
  v_is_bounty boolean;
  v_bounty_head numeric;
  v_base numeric;
  v_fee numeric;
  v_total numeric;
  v_add integer;
  v_new_chips integer;
  v_seat record;
  v_key text;
  v_inserted integer;
  v_cat text;
  v_club uuid;
  v_stack_after numeric;
  v_expected numeric;
  v_fee_ratio numeric;
  v_was_seated boolean:=false;
  v_rows integer;
  v_led_cat text;
  v_led_cp text;
  v_led_ent text;
  v_led_tid text;
BEGIN
  IF NOT (COALESCE(auth.role(),'service_role')='service_role')
     AND (auth.uid() IS NULL OR auth.uid()<>p_user_id) THEN
    RAISE EXCEPTION
      'process_tournament_rebuy: caller may only transact for themselves'
      USING ERRCODE='42501';
  END IF;
  IF p_rebuy_type NOT IN ('rebuy','reentry','addon') THEN
    RAISE EXCEPTION 'Invalid rebuy type: %',p_rebuy_type
      USING ERRCODE='22023';
  END IF;
  IF p_client_token IS NULL OR length(btrim(p_client_token))=0
     OR length(btrim(p_client_token))>128 THEN
    RAISE EXCEPTION 'exact tournament chip-purchase token is required'
      USING ERRCODE='22023';
  END IF;

  SELECT id,name,club_id,status,buy_in_amount,buy_in_fee,starting_chips,
         is_rebuy,is_reentry,add_on_available,addon_period_triggered,
         rebuy_cost,rebuy_chips,rebuy_levels,late_reg_levels,max_rebuys,
         max_reentries,addon_cost,addon_chips,addon_levels,current_level,
         prize_pool,is_bounty,is_pko,is_mystery_bounty,bounty_amount
    INTO v_t
    FROM public.tournaments
   WHERE id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
  END IF;
  IF v_t.status NOT IN ('RUNNING','REGISTERING','ANNOUNCED') THEN
    RAISE EXCEPTION 'Tournament is not accepting chip purchases (status %)',v_t.status;
  END IF;

  SELECT id,chips,status,prize,rebuys,add_on,table_id,club_id
    INTO v_p
    FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Player not registered in this tournament';
  END IF;
  IF v_p.status='eliminated' AND COALESCE(v_p.prize,0)>0 THEN
    RAISE EXCEPTION
      'Finishing Place Already Paid - A Rebuy Cannot Resurrect A Settled Result';
  END IF;
  v_club:=v_p.club_id;
  IF v_club IS NULL THEN
    RAISE EXCEPTION
      'Tournament entry funding club is missing; refusing a substituted wallet'
      USING ERRCODE='P0404';
  END IF;

  v_cat:=CASE WHEN p_rebuy_type='addon' THEN 'addon' ELSE 'rebuy' END;
  v_key:=CASE WHEN p_rebuy_type='addon'
    THEN 'tourney:'||p_tournament_id::text||':addon:'||p_user_id::text
    ELSE 'tourney:'||p_tournament_id::text||':'||p_rebuy_type||':'||
         p_user_id::text||':tok:'||btrim(p_client_token)
  END;

  IF p_rebuy_type='addon' THEN
    PERFORM 1
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE s.user_id=p_user_id AND s.left_at IS NULL
       AND tb.tournament_id=p_tournament_id
     LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'No Live Seat For This % - Aborting So No Charge Is Made',p_rebuy_type;
    END IF;
    IF NOT COALESCE(v_t.add_on_available,false) THEN
      RAISE EXCEPTION 'Add-ons are not offered in this tournament';
    END IF;
    IF COALESCE(v_p.add_on,false) THEN
      RAISE EXCEPTION 'Add-on already taken';
    END IF;
    v_base:=COALESCE(NULLIF(v_t.addon_cost,0),v_t.buy_in_amount,0);
    v_add:=COALESCE(NULLIF(v_t.addon_chips,0),v_t.starting_chips,0)::integer;
  ELSE
    IF p_rebuy_type='rebuy' AND NOT COALESCE(v_t.is_rebuy,false) THEN
      RAISE EXCEPTION 'Rebuys are not offered in this tournament';
    END IF;
    IF p_rebuy_type='reentry' AND NOT COALESCE(v_t.is_reentry,false) THEN
      RAISE EXCEPTION 'Re-entries are not offered in this tournament';
    END IF;
    IF p_rebuy_type='rebuy' AND v_t.max_rebuys IS NOT NULL
       AND COALESCE(v_p.rebuys,0)>=v_t.max_rebuys THEN
      RAISE EXCEPTION 'Rebuy limit reached (% of %)',v_p.rebuys,v_t.max_rebuys;
    END IF;
    IF p_rebuy_type='reentry' AND v_t.max_reentries IS NOT NULL
       AND COALESCE(v_p.rebuys,0)>=v_t.max_reentries THEN
      RAISE EXCEPTION
        'Re-entry limit reached (% of %)',v_p.rebuys,v_t.max_reentries;
    END IF;
    IF p_rebuy_type='rebuy'
       AND COALESCE(v_p.chips,0)>COALESCE(v_t.starting_chips,0) THEN
      RAISE EXCEPTION 'Stack too high for a rebuy';
    END IF;
    /* CONSERVATION (a) 2026-09-11. A re-entry REPLACES the seat stack below
       (stack = v_add) while the roster gains rebuys + 1, so the conservation
       check's expected side gains rebuy_chips at the same moment. Taken while
       the entry still holds chips, that destroys them AND inflates expected.
       A re-entry follows a bust, so the live population for this is zero; it
       is refused rather than left to silently unbalance the event. */
    IF p_rebuy_type='reentry' AND COALESCE(v_p.chips,0)>0 THEN
      RAISE EXCEPTION
        'A Re-Entry Starts A New Stack And This Entry Still Holds % Chips - Aborting So No Charge Is Made',
        v_p.chips
        USING ERRCODE='55000';
    END IF;
    v_base:=COALESCE(NULLIF(v_t.rebuy_cost,0),v_t.buy_in_amount,0);
    v_add:=COALESCE(NULLIF(v_t.rebuy_chips,0),v_t.starting_chips,0)::integer;
  END IF;

  v_fee_ratio:=public.fn_ca_tournament_fee_ratio(
    v_t.buy_in_amount,v_t.buy_in_fee);
  v_ratio:=CASE WHEN p_rebuy_type='addon' THEN 0 ELSE v_fee_ratio END;
  v_total:=round(v_base::numeric);
  v_fee:=CASE WHEN v_ratio>0 AND v_total>0
    THEN public.fn_ca_recovery_fee_cents(
           round(v_total*100)::bigint,v_ratio,
           public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric/100    ELSE 0
  END;
  v_base:=round(v_total-v_fee,2);
  v_is_bounty:=COALESCE(v_t.is_bounty,false)
    OR COALESCE(v_t.is_pko,false)
    OR COALESCE(v_t.is_mystery_bounty,false);
  IF v_is_bounty AND p_rebuy_type<>'addon' THEN
    v_bounty_head:=public.fn_ca_unit_floor_cents(
      round(LEAST(GREATEST(0,round(COALESCE(v_t.bounty_amount,0),2)),
                  v_base)*100)::bigint,
      public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric/100;
    v_base:=v_base-v_bounty_head;
  ELSE
    v_bounty_head:=0;
  END IF;
  IF p_cost IS NOT NULL AND abs(p_cost-v_total)>0.01 THEN
    RAISE EXCEPTION
      'Price mismatch: client quoted %, server computed %',p_cost,v_total
      USING ERRCODE='22023';
  END IF;
  IF v_add<=0 OR v_total<0 OR v_fee<0 OR v_base<0 OR v_bounty_head<0
     OR round(v_base+v_bounty_head+v_fee,2)<>round(v_total,2) THEN
    RAISE EXCEPTION 'Tournament chip-purchase quote does not conserve'
      USING ERRCODE='P0404';
  END IF;

  INSERT INTO public.wallet_credit_idempotency(key,user_id,amount)
  VALUES(v_key,p_user_id,v_total)
  ON CONFLICT(key) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  IF v_inserted=0 THEN
    RETURN jsonb_build_object(
      'success',true,'idempotent',true,'new_stack',v_p.chips,
      'rebuy_type',p_rebuy_type);
  END IF;

  IF v_unit = 100 THEN
    -- DIAMOND PHASE 8: the purchase reserves settled Diamonds into the entry's
    -- custody row. The chip-wallet debit below is the chip estate's.
    v_dia := public.fn_poker_diamond_tournament_charge(
      p_user_id, p_tournament_id, p_rebuy_type, v_total, v_base, v_bounty_head, v_fee, v_p.id, v_key);
    v_balance := 0;
  ELSE
  PERFORM public.fn_ensure_club_wallet(p_user_id,v_club);
  SELECT chip_balance INTO v_balance
    FROM public.club_members
   WHERE user_id=p_user_id AND club_id=v_club
   FOR UPDATE;
  IF v_balance IS NULL OR v_balance<v_total THEN
    RAISE EXCEPTION 'Insufficient club chips: need %, have %',
      v_total,COALESCE(v_balance,0);
  END IF;

  v_led_cat:=current_setting('app.ledger_category',true);
  v_led_cp:=current_setting('app.ledger_counterparty',true);
  v_led_ent:=current_setting('app.ledger_counterparty_entity',true);
  v_led_tid:=current_setting('app.ledger_tournament',true);
  PERFORM set_config('app.ledger_category',v_cat,true);
  PERFORM set_config('app.ledger_counterparty','prize_liability',true);
  PERFORM set_config(
    'app.ledger_counterparty_entity',p_tournament_id::text,true);
  PERFORM set_config('app.ledger_tournament',p_tournament_id::text,true);
  PERFORM set_config('app.pnl_tournament_entitlement','',true);
  UPDATE public.club_members
     SET chip_balance=chip_balance-v_total,updated_at=now()
   WHERE user_id=p_user_id AND club_id=v_club;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  v_original_entitlement:=NULLIF(current_setting('app.pnl_tournament_entitlement',true),'')::uuid;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'Exact tournament funding wallet changed during debit'
      USING ERRCODE='55000';
  END IF;
  END IF; -- DIAMOND PHASE 8: end of the chip-wallet branch
  PERFORM set_config('app.ledger_category',COALESCE(v_led_cat,''),true);
  PERFORM set_config('app.ledger_counterparty',COALESCE(v_led_cp,''),true);
  PERFORM set_config(
    'app.ledger_counterparty_entity',COALESCE(v_led_ent,''),true);
  PERFORM set_config('app.ledger_tournament',COALESCE(v_led_tid,''),true);

  IF p_rebuy_type='reentry' THEN
    UPDATE public.tournament_players
       SET chips=v_add,status='playing',eliminated_at=NULL,position=NULL,
           rebuys=COALESCE(rebuys,0)+1
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  ELSIF p_rebuy_type='addon' THEN
    UPDATE public.tournament_players
       SET chips=COALESCE(chips,0)+v_add,add_on=true
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  ELSE
    UPDATE public.tournament_players
       SET chips=COALESCE(chips,0)+v_add,status='playing',
           eliminated_at=NULL,position=NULL,
           rebuys=COALESCE(rebuys,0)+1
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  END IF;
  IF v_new_chips IS NULL THEN
    RAISE EXCEPTION 'Locked tournament roster changed during chip grant'
      USING ERRCODE='55000';
  END IF;

  IF v_bounty_head>0 THEN
    UPDATE public.tournament_players
       SET current_bounty=CASE WHEN p_rebuy_type='reentry'
         THEN v_bounty_head
         ELSE COALESCE(current_bounty,0)+v_bounty_head END
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id;
  END IF;

  SELECT s.id,s.stack INTO v_seat
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE s.user_id=p_user_id AND s.left_at IS NULL
     AND tb.tournament_id=p_tournament_id
   ORDER BY (tb.status IS DISTINCT FROM 'closed') DESC,
            s.joined_at DESC NULLS LAST,s.id DESC
   LIMIT 1;
  IF FOUND THEN
    v_was_seated:=true;
    v_expected:=CASE WHEN p_rebuy_type='reentry'
      THEN v_add ELSE COALESCE(v_seat.stack,0)+v_add END;
    /* CONSERVATION (b) 2026-09-11. The roster above has already booked this
       purchase, so the supply this is measured against already contains the
       chips being bought. The felt must land inside it. An event that is
       already over its cap keeps playing; it may not get further over.
       See ca_drift_incidents 8b8fe26c and this migration's header. */
    PERFORM public.fn_ca_assert_tournament_chip_grant(
      p_tournament_id,p_user_id,v_seat.id,v_expected,
      'tournament '||p_rebuy_type);
    UPDATE public.table_seats
       SET stack=CASE WHEN p_rebuy_type='reentry'
         THEN v_add ELSE COALESCE(stack,0)+v_add END
     WHERE id=v_seat.id
     RETURNING stack INTO v_stack_after;
    IF v_stack_after IS NULL OR v_stack_after<>v_expected THEN
      RAISE EXCEPTION
        'Chip Grant Did Not Land: % Expected Stack %, Seat % Holds % - Aborting So No Charge Is Made',
        p_rebuy_type,v_expected,v_seat.id,v_stack_after;
    END IF;
    UPDATE public.tournament_players
       SET chips=(SELECT stack FROM public.table_seats WHERE id=v_seat.id)::integer
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  ELSIF p_rebuy_type='addon' THEN
    RAISE EXCEPTION
      'Seat Disappeared During % - Aborting So No Charge Is Made',p_rebuy_type;
  END IF;

  UPDATE public.tournaments
     SET prize_pool=COALESCE(prize_pool,0)+v_base,
         bounty_pool=COALESCE(bounty_pool,0)+v_bounty_head
   WHERE id=p_tournament_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'Tournament vanished during chip-purchase pool booking'
      USING ERRCODE='55000';
  END IF;

  IF v_fee>0 AND v_t.club_id IS NOT NULL AND v_unit = 100 THEN
    -- DIAMOND PHASE 8: the fee stays in custody until the event settles.
    UPDATE public.tournaments
       SET total_rake=COALESCE(total_rake,0)+v_fee
     WHERE id=p_tournament_id;
  ELSIF v_fee>0 AND v_t.club_id IS NOT NULL THEN
    INSERT INTO public.rake_records(
      hand_id,table_id,club_id,rake_amount,pot_size,num_players,
      bbj_contribution,is_tournament,tournament_id,source,metadata)
    VALUES(
      NULL,NULL,v_t.club_id,v_fee,v_fee,1,0,true,p_tournament_id,
      'process_tournament_rebuy',jsonb_build_object(
        'kind','tournament_'||p_rebuy_type||'_fee','user_id',p_user_id,
        'entry_club_id',v_club));
    UPDATE public.tournaments
       SET total_rake=COALESCE(total_rake,0)+v_fee
     WHERE id=p_tournament_id;
  END IF;

  IF v_unit = 1 THEN -- DIAMOND PHASE 8: wallet_transactions is the chip receipt
  INSERT INTO public.wallet_transactions(
    user_id,wallet_type,type,amount,category,description,
    related_entity_id,balance_after)
  VALUES(
    p_user_id,'PLAYER','debit',v_total,v_cat,
    'Tournament '||p_rebuy_type||': '||COALESCE(v_t.name,'tournament')||
      ' ('||v_base||' prize + '||v_bounty_head||' bounty + '||v_fee||
      ' fee) [club wallet]',
    p_tournament_id,v_balance-v_total) RETURNING id INTO v_original_wallet;
  END IF; -- DIAMOND PHASE 8

  PERFORM public.fn_ca_record_tournament_participant_funding(v_p.id,p_rebuy_type,v_key,
    v_total,CASE WHEN v_unit=100 THEN 'diamonds' ELSE 'chips' END,
    v_original_entitlement,v_original_wallet,v_dia);

  RETURN jsonb_build_object(
    'success',true,'new_stack',v_new_chips,'rebuy_type',p_rebuy_type,
    'chips_added',v_add,'cost',v_total,'fee',v_fee,'seated',v_was_seated,
    'bounty_head_funded',v_bounty_head);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_register_diamond_journal_row(p_tx_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  t record; v_origin text; v_action text; v_label text; v_actorlb text;
  v_before numeric; v_after numeric; v_supply numeric; v_reason text; v_op text;
  v_actor uuid := auth.uid();
BEGIN
  SELECT * INTO t FROM public.diamond_transactions WHERE id = p_tx_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.ca_mint_ledger m WHERE m.diamond_tx_id = t.id) THEN
    RETURN false;
  END IF;
  v_origin := public.fn_ca_diamond_journal_origin(t.type, t.transaction_type, t.source, t.issuance_class, t.amount);
  IF v_origin IS NULL THEN RETURN false; END IF;

  v_action := CASE WHEN t.amount > 0 THEN 'mint' ELSE 'burn' END;
  v_after  := COALESCE(t.balance_after, 0);
  v_before := v_after - t.amount;
  SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text)
    INTO v_label FROM public.profiles p WHERE p.id = t.user_id;
  v_label := COALESCE(v_label, t.user_id::text);
  SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text)
    INTO v_actorlb FROM public.profiles p WHERE p.id = v_actor;
  v_op := 'diamond-journal:' || v_origin || ':' || t.id::text;
  v_reason := CASE v_action
                WHEN 'mint' THEN 'The Mint issued ' || abs(t.amount)::text || ' diamonds (' || v_origin || '): '
                ELSE 'The Mint retired ' || abs(t.amount)::text || ' diamonds (' || v_origin || '): '
              END
              || COALESCE(NULLIF(btrim(t.description), ''), COALESCE(t.transaction_type, t.type, 'diamond movement'));

  -- NO GLOBAL LOCK ON THIS PATH. It used to hold pg_advisory_xact_lock('ca_mint_ledger:diamonds')
  -- to make supply_after an exact running total. An xact-scoped lock is held until the CALLER
  -- commits, so every diamond movement serialised the whole economy behind whatever transaction
  -- happened to be moving diamonds - and on 2026-09-08, once one transaction could claim several
  -- challenges at once, twenty-four movements died on lock_timeout and went unrecorded.
  --
  -- supply_after is therefore the supply OBSERVED as this row was written, not a serialised
  -- running total: two simultaneous movements may each omit the other. Nothing reads it. The
  -- authority on supply is fn_ca_mint_supply(), which sums the movements, and the identity that
  -- matters - that sum equals what players hold - does not depend on this column at all.
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'diamonds';
  v_supply := v_supply + CASE WHEN v_action = 'mint' THEN abs(t.amount) ELSE -abs(t.amount) END;

  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id, diamond_tx_id, created_at)
  VALUES
    (v_op, v_action, 'diamonds', 'player', t.user_id, v_label, abs(t.amount),
     v_before, v_after, v_supply, v_reason,
     v_actor, v_actorlb, NULL, t.id, COALESCE(t.created_at, now()))
  ON CONFLICT (op_id) DO NOTHING;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_return_excess_start_overlay_locked(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_system_actor constant uuid := '2d1cd6c3-5700-4af9-a271-d4863fdab20d';
  v_t public.tournaments%ROWTYPE;
  v_key text;
  v_sources integer;
  v_from_type text;
  v_from_entity uuid;
  v_first_leg uuid;
  v_funded numeric;
  v_returned numeric;
  v_pool numeric;
  v_guarantee numeric;
  v_seat_guarantee numeric;
  v_target_id uuid;
  v_collected numeric;
  v_target numeric;
  v_excess numeric;
  v_before numeric;
  v_after numeric;
  v_ledger_id uuid;
BEGIN
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_t.prize_pool_finalized, false) THEN
    RETURN NULL;  -- a finalized pool is never repriced
  END IF;
  /* 2026-10-06 (20261007000010): A DIAMOND GUARANTEE IS A FLOOR TOO. When the
     prize pool closes, a Diamond event's pool is brought to exactly
     max(guarantee, collected): overlay the entries collected since lock made
     unnecessary returns from the custody to the house, and any guarantee
     still uncovered is paid from its earmark. One function, the same one the
     lock uses; the unused earmark is released. */
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    v_excess := public.fn_poker_diamond_tournament_settle_overlay(p_tournament_id, 'finalize',
                  public.fn_poker_diamond_tournament_effective_guarantee(p_tournament_id));
    PERFORM public.fn_poker_diamond_guarantee_release(p_tournament_id, 'finalize');
    IF v_excess = 0 THEN RETURN NULL; END IF;
    UPDATE public.tournaments SET prize_pool = round(COALESCE(prize_pool, 0) + v_excess, 2)
     WHERE id = p_tournament_id;
    RETURN jsonb_build_object('asset', 'diamonds', 'bank_type', 'diamond_house',
      'overlay_delta', v_excess, 'amount', GREATEST(-v_excess, 0),
      'pool_before', round(COALESCE(v_t.prize_pool, 0), 2),
      'pool_after', round(COALESCE(v_t.prize_pool, 0) + v_excess, 2));
  END IF;
  v_key := 'tourney:' || p_tournament_id::text || ':guarantee_overlay_excess_return';
  IF EXISTS (SELECT 1 FROM public.chip_ledger l WHERE l.idempotency_key = v_key) THEN
    RETURN NULL;
  END IF;

  -- The start-time legs fn_ca_fund_overlay_on_lock wrote (the finalization
  -- leg carries its own idempotency key and cannot exist before finalizing).
  SELECT count(DISTINCT (l.from_type, l.from_entity_id)), min(l.from_type),
         (array_agg(l.from_entity_id ORDER BY l.created_at, l.id))[1],
         (array_agg(l.id ORDER BY l.created_at, l.id))[1],
         round(COALESCE(sum(l.amount), 0), 2)
    INTO v_sources, v_from_type, v_from_entity, v_first_leg, v_funded
    FROM public.chip_ledger l
   WHERE l.tournament_id = p_tournament_id
     AND l.category = 'overlay'
     AND l.to_type = 'prize_liability'
     AND l.to_entity_id = p_tournament_id
     AND l.from_type IN ('union_bank', 'club_treasury')
     AND l.idempotency_key IS DISTINCT FROM 'tourney:' || p_tournament_id::text || ':guarantee_overlay'
     AND COALESCE(l.description, '') NOT LIKE 'auto-ledgered%';
  IF COALESCE(v_funded, 0) <= 0 OR v_sources <> 1 THEN
    RETURN NULL;
  END IF;
  SELECT round(COALESCE(sum(r.amount), 0), 2) INTO v_returned
    FROM public.chip_ledger r
   WHERE r.tournament_id = p_tournament_id AND r.category = 'reversal'
     AND r.from_type = 'prize_liability' AND r.from_entity_id = p_tournament_id
     AND r.metadata->>'kind' = 'reviewed_void_overlay_return';
  v_funded := round(v_funded - v_returned, 2);
  IF v_funded <= 0 THEN RETURN NULL; END IF;

  v_pool := round(COALESCE(v_t.prize_pool, 0), 2);
  v_guarantee := round(COALESCE(v_t.guaranteed_prize, 0), 2);
  -- The same effective guarantee the lock trigger funded: a satellite's
  -- guaranteed seats are worth target buy-in + fee each.
  IF COALESCE(v_t.satellite_seats, 0) > 0
     AND (v_t.variant = 'satellite'
          OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
          OR v_t.satellite_target_id IS NOT NULL) THEN
    v_target_id := COALESCE(v_t.satellite_target_id, v_t.satellite_target);
    IF v_target_id IS NOT NULL THEN
      SELECT round((COALESCE(t2.buy_in_amount, 0) + COALESCE(t2.buy_in_fee, 0)) * v_t.satellite_seats, 2)
        INTO v_seat_guarantee FROM public.tournaments t2 WHERE t2.id = v_target_id;
      v_guarantee := GREATEST(v_guarantee, COALESCE(v_seat_guarantee, 0));
    END IF;
  END IF;

  v_collected := round(v_pool - v_funded, 2);
  v_target := GREATEST(v_guarantee, v_collected);
  v_excess := round(LEAST(v_funded, GREATEST(0, v_pool - v_target)), 2);
  IF v_excess <= 0 THEN RETURN NULL; END IF;

  -- Lock order of the finalization core: tournament, escrow, then the bank.
  PERFORM 1 FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id FOR UPDATE;
  IF v_from_type = 'union_bank' THEN
    SELECT round(COALESCE(chip_balance, 0), 2) INTO v_before FROM public.union_wallets
     WHERE union_id = v_from_entity FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);
    UPDATE public.union_wallets SET chip_balance = chip_balance + v_excess, updated_at = now()
     WHERE union_id = v_from_entity RETURNING round(chip_balance, 2) INTO v_after;
    PERFORM set_config('app.ledger_autoskip_union_wallets', '0', true);
  ELSE
    SELECT round(COALESCE(chip_treasury, 0), 2) INTO v_before FROM public.clubs
     WHERE id = v_from_entity FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
    UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) + v_excess, updated_at = now()
     WHERE id = v_from_entity RETURNING round(chip_treasury, 2) INTO v_after;
    PERFORM set_config('app.ledger_autoskip_clubs', '0', true);
  END IF;
  IF v_after IS DISTINCT FROM round(v_before + v_excess, 2) THEN
    RAISE EXCEPTION 'excess overlay return did not credit its bank exactly'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.chip_ledger (
    performed_by, from_type, from_entity_id, to_type, to_entity_id,
    amount, category, club_id, tournament_id, description, idempotency_key, metadata)
  VALUES (
    c_system_actor, 'prize_liability', p_tournament_id, v_from_type, v_from_entity,
    v_excess, 'reversal', v_t.club_id, p_tournament_id,
    format('Guarantee overlay excess returned to its source: %s (%s) collected %s against its %s guarantee, so the %s start-time overlay needed only %s',
           COALESCE(v_t.name, 'tournament'), p_tournament_id, v_collected, v_guarantee,
           v_funded, round(v_funded - v_excess, 2)),
    v_key,
    jsonb_build_object('kind', 'reviewed_void_overlay_return',
      'reason', 'guarantee_overlay_excess_at_finalization',
      'original_overlay_ledger_id', v_first_leg, 'funded_overlay', v_funded,
      'collected', v_collected, 'guarantee', v_guarantee,
      'pool_before', v_pool, 'pool_after', round(v_pool - v_excess, 2),
      'source_balance_before', v_before, 'source_balance_after', v_after))
  RETURNING id INTO v_ledger_id;
  PERFORM public.fn_ca_escrow_apply(p_tournament_id, 'guarantee overlay excess return',
                                    p_overlay_in => -v_excess);

  UPDATE public.tournaments
     SET prize_pool = round(v_pool - v_excess, 2)
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object('amount', v_excess, 'bank_type', v_from_type,
    'bank_entity_id', v_from_entity, 'funded_overlay', v_funded,
    'collected', v_collected, 'guarantee', v_guarantee,
    'pool_before', v_pool, 'pool_after', round(v_pool - v_excess, 2),
    'ledger_id', v_ledger_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_tournament_charge_split(p_tournament_id uuid, p_charge_category text, p_gross numeric)
 RETURNS TABLE(refund_prize numeric, refund_bounty numeric, refund_fee numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t record;
  v_entry record;
  v_kind text := lower(btrim(COALESCE(p_charge_category,'')));
  v_gross numeric := round(COALESCE(p_gross,0),2);
  v_is_bounty boolean;
  v_ratio numeric;
  v_fee numeric;
  v_bounty numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_gross IS NULL
     OR p_gross::text IN ('NaN','Infinity','-Infinity')
     OR p_gross IS DISTINCT FROM v_gross OR v_gross <= 0
     OR v_kind NOT IN ('tournament_buyin','rebuy','addon') THEN
    RAISE EXCEPTION 'tournament charge split received an invalid contract'
      USING ERRCODE = '22003';
  END IF;
  SELECT t.buy_in_amount,t.buy_in_fee,t.bounty_amount,
         t.is_bounty,t.is_pko,t.is_mystery_bounty
    INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament charge split has no tournament %',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  v_is_bounty := COALESCE(v_t.is_bounty,false)
              OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  IF v_kind='tournament_buyin' THEN
    SELECT * INTO v_entry FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
    IF v_entry.charge IS DISTINCT FROM v_gross THEN
      RAISE EXCEPTION
        'tournament buy-in ledger amount % does not match its funded split %',
        v_gross,v_entry.charge USING ERRCODE = '23514';
    END IF;
    refund_prize := v_entry.prize;
    refund_bounty := v_entry.bounty;
    refund_fee := v_entry.rake;
  ELSIF v_kind='addon' THEN
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'add-on charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    refund_prize := v_gross;
    refund_bounty := 0;
    refund_fee := 0;
  ELSE
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'rebuy charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    v_ratio := public.fn_ca_tournament_fee_ratio(
      v_t.buy_in_amount, v_t.buy_in_fee);
    v_fee := public.fn_ca_recovery_fee_cents(
      round(v_gross*100)::bigint, v_ratio,
      public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric / 100;    v_bounty := CASE WHEN v_is_bounty THEN
      public.fn_ca_unit_floor_cents(
        round(LEAST(GREATEST(0,round(COALESCE(v_t.bounty_amount,0),2)),
                    v_gross-v_fee)*100)::bigint,
        public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric / 100
      ELSE 0 END;
    refund_fee := v_fee;
    refund_bounty := v_bounty;
    refund_prize := round(v_gross-v_fee-v_bounty,2);
  END IF;
  IF refund_prize IS NULL OR refund_bounty IS NULL OR refund_fee IS NULL
     OR refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR refund_prize < 0 OR refund_bounty < 0 OR refund_fee < 0
     OR v_gross IS DISTINCT FROM
          round(refund_prize+refund_bounty+refund_fee,2) THEN
    RAISE EXCEPTION 'tournament charge split produced invalid component rails'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_tournament_is_unlimited(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 IF v_abi='legacy-capacity-v1' THEN RETURN false; END IF;
 RETURN public.fn_ca_tournament_recorded_format(p_tournament_id) IN ('mtt-v1','mtt-v2');
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_tournament_recorded_format(p_tournament_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_format text;
BEGIN
  SELECT format_contract INTO v_format FROM public.tournaments WHERE id=p_tournament_id;
  IF NOT FOUND OR v_format IS NULL OR v_format NOT IN
     ('mtt-v1','mtt-v2','seat-first-satellite-v1','sng-v1','spin-v1') THEN
    RAISE EXCEPTION 'TOURNAMENT_FORMAT_NOT_PROVEN' USING ERRCODE='55000';
  END IF;
  RETURN v_format;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_tournament_recorded_seat_first(p_tournament_id uuid, p_terminal_cleanup boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_format text; v_cap integer; v_status text;
BEGIN
 SELECT t.format_contract,t.max_players,upper(COALESCE(t.status::text,''))
 INTO v_format,v_cap,v_status FROM public.tournaments t WHERE t.id=p_tournament_id;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
 END IF;
 IF p_terminal_cleanup IS TRUE AND v_format IS NULL
    AND v_status IN ('COMPLETING','COMPLETED','CANCELLED','CANCELED') THEN
  RETURN false;
 END IF;
 v_format:=public.fn_ca_tournament_recorded_format(p_tournament_id);
 RETURN v_format IN ('spin-v1','seat-first-satellite-v1')
     OR (v_format='sng-v1' AND v_cap BETWEEN 1 AND 2);
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_unregister_tournament_player_exact(p_tournament_id uuid, p_user_id uuid, p_expected_table_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_reg public.tournament_players%ROWTYPE;
  v_ent record;
  v_fee_group record;
  v_settle jsonb;
  v_receipt jsonb;
  v_escrow_before public.tournament_escrow%ROWTYPE;
  v_escrow_after public.tournament_escrow%ROWTYPE;
  v_players_before integer;
  v_rows integer;
  v_seat_number integer;
  v_seats_taken integer;
  v_non_cash_count integer;
  v_wallet_debits numeric:=0;
  v_wallet_refunds_before numeric:=0;
  v_wallet_refunds_after numeric:=0;
  v_entitled_wallet_total numeric:=0;
  v_tranche_total numeric:=0;
  v_refund_prize numeric:=0;
  v_refund_bounty numeric:=0;
  v_refund_fee numeric:=0;
  v_refund_total numeric:=0;
  v_wallet_amount numeric:=0;
  v_ticket_amount numeric:=0;
  v_running_owed numeric:=0;
  v_rake_before numeric:=0;
  v_rake_after numeric:=0;
  v_fees_reversed numeric:=0;
  v_entitlement_ids uuid[]:='{}'::uuid[];
  v_ticket_ids uuid[]:='{}'::uuid[];
  v_credit_ledger_ids uuid[]:='{}'::uuid[];
  v_wallet_transaction_ids uuid[]:='{}'::uuid[];
  v_source_wallet_club_ids uuid[]:='{}'::uuid[];
  v_fee_reversal_ids uuid[]:='{}'::uuid[];
  v_fee_source_rake_record_ids uuid[]:='{}'::uuid[];
  v_fee_entitlement_ids uuid[]:='{}'::uuid[];
  v_fee_reversal_id uuid;
  v_fee_source_count integer:=0;
  v_fee_source_entitlement_count integer:=0;
  v_fee_source_amount numeric:=0;
  v_request_id uuid:=COALESCE(p_request_id,gen_random_uuid());
  v_start_authority text:='scheduled_clock';
  v_launch_completed_at timestamptz;
  v_persisted_hand_exists boolean:=false;
  v_actual_status text;
  v_actual_started_at timestamptz;
  v_unregistered_at timestamptz;
  v_description text:=COALESCE(
    NULLIF(btrim(p_description),''),'Tournament unregistration refund');
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player ids are required'
      USING ERRCODE='22004';
  END IF;
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  -- DIAMOND PHASE 8: a Diamond entry never rode the chip rails. Every
  -- caller of this authority (the lobby, the seat, the administrator, the
  -- launch) sends it home through its own door before a chip rail is
  -- touched. A caller that named no request id is given one exactly as
  -- this authority mints its own. A seat exit naming a table the player
  -- does not sit at answers not_seated unless its request id is already
  -- settled, in which case the door replays that receipt.
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    IF p_expected_table_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.table_seats s
                        WHERE s.table_id=p_expected_table_id AND s.user_id=p_user_id AND s.left_at IS NULL)
       AND NOT (p_request_id IS NOT NULL AND EXISTS (
                  SELECT 1 FROM public.poker_diamond_tournament_ledger l
                   WHERE l.tournament_id=p_tournament_id AND l.user_id=p_user_id AND l.kind='refund'
                     AND l.request->>'request_id'=p_request_id::text)) THEN
      RETURN jsonb_build_object('ok',false,'reason','not_seated');
    END IF;
    RETURN public.fn_poker_diamond_tournament_unregister(
      p_tournament_id, p_user_id, COALESCE(p_request_id, gen_random_uuid()));
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  -- Spins and Heads-Up Sit & Gos are separate products, but both are
  -- seat-first: start_time is only their human fill-window deadline. Neither
  -- product has a scheduled start. Satellite feeders remain outside this
  -- change and retain the existing scheduled-clock contract.
  IF v_t.format_contract='spin-v1' THEN
    v_start_authority:='spin_actual_start';
  ELSIF v_t.format_contract='sng-v1'
     AND COALESCE(v_t.max_players,0)=2 THEN
    v_start_authority:='heads_up_sng_actual_start';
  END IF;
  /* A release performed by the launch that holds this event's INCOMPLETE
     launch receipt has its own start authority. The clock has passed
     start_time, but no hand has been dealt (checked below, fails closed)
     and the receipt has not been completed, so the seat-first proofs -
     started_at unset, launch not completed - are the right ones and the
     receipt records launch_release. The launch names its receipt through
     the transaction-local app.ca_launch_release_launch_id, set only by
     fn_ca_release_unseatable_registrant_at_launch. */
  IF v_start_authority='scheduled_clock' AND EXISTS (
       SELECT 1 FROM public.tournament_launch_receipts r
        WHERE r.tournament_id=p_tournament_id
          AND r.completed_at IS NULL
          AND r.launch_id::text=NULLIF(
            current_setting('app.ca_launch_release_launch_id',true),'')) THEN
    v_start_authority:='launch_release';
  END IF;

  -- A caller-supplied request id is a durable operation identity. It may only
  -- name this exact player/event/endpoint scope. If its pre-start outcome is
  -- already committed, replay that immutable outcome even when the wall clock
  -- is now past the start; this branch performs no new unregistration writes.
  IF p_request_id IS NOT NULL THEN
    IF EXISTS(
      SELECT 1 FROM public.tournament_unregistration_receipts r
       WHERE r.request_id=p_request_id
         AND (r.tournament_id IS DISTINCT FROM p_tournament_id
           OR r.user_id IS DISTINCT FROM p_user_id
           OR r.source_table_id IS DISTINCT FROM p_expected_table_id)) THEN
      RAISE EXCEPTION 'unregistration request id belongs to another intent'
        USING ERRCODE='22023';
    END IF;
    IF EXISTS(
      SELECT 1 FROM public.tournament_unregistration_receipts r
       WHERE r.request_id=p_request_id) THEN
      v_receipt:=public.fn_ca_tournament_unregistration_receipt(
        p_tournament_id,p_user_id,p_expected_table_id,p_request_id);
      IF v_receipt IS NOT NULL THEN
        RETURN v_receipt||jsonb_build_object('replayed',true);
      END IF;
      RAISE EXCEPTION
        'unregistration request id belongs to a prior registration lifecycle'
        USING ERRCODE='P0404';
    END IF;
  END IF;

  SELECT * INTO v_reg FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     AND tp.status::text IN ('registered','playing')
   ORDER BY tp.id LIMIT 1 FOR UPDATE;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('ANNOUNCED','REGISTERING') THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_closed');
  END IF;
  PERFORM public.fn_ca_tournament_recorded_format(p_tournament_id);

  -- A persisted hand is stronger actual-start evidence than either a mutable
  -- parent status or a launch receipt that an interrupted launcher failed to
  -- complete. Canonical accepted-hand commits carry tournament_id; the
  -- table-linked branch also fails closed for older rows that omitted it. The
  -- exclusive lifecycle advisory lock above serializes this read against the
  -- shared lock held by every canonical accepted-hand commit.
  SELECT EXISTS (
           SELECT 1
             FROM public.hand_history hh
            WHERE hh.tournament_id=p_tournament_id
         ) OR EXISTS (
           SELECT 1
             FROM public.tables hand_table
             JOIN public.hand_history hh ON hh.table_id=hand_table.id
            WHERE hand_table.tournament_id=p_tournament_id
         )
    INTO v_persisted_hand_exists;
  IF v_persisted_hand_exists THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;
  IF v_start_authority='scheduled_clock' THEN
    IF v_t.start_time IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','registration_schedule_unset');
    END IF;
    IF clock_timestamp()>=v_t.start_time THEN
      RETURN jsonb_build_object('ok',false,'reason','tournament_started');
    END IF;
  ELSE
    SELECT r.completed_at INTO v_launch_completed_at
      FROM public.tournament_launch_receipts r
     WHERE r.tournament_id=p_tournament_id;
    IF v_t.started_at IS NOT NULL OR v_launch_completed_at IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','tournament_started');
    END IF;
  END IF;
  IF v_reg.id IS NULL THEN
    -- Rolling clients without a request id may recover a just-lost response
    -- only while registration remains open. They can never turn an old receipt
    -- into a successful post-start response.
    IF p_request_id IS NULL THEN
      v_receipt:=public.fn_ca_tournament_unregistration_receipt(
        p_tournament_id,p_user_id,p_expected_table_id,NULL);
      IF v_receipt IS NOT NULL THEN
        RETURN v_receipt||jsonb_build_object('replayed',true);
      END IF;
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','not_registered');
  END IF;
  IF p_expected_table_id IS NOT NULL THEN
    SELECT s.seat_number INTO v_seat_number
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE s.table_id=p_expected_table_id AND s.user_id=p_user_id
       AND s.left_at IS NULL AND tb.tournament_id=p_tournament_id
     ORDER BY s.id LIMIT 1 FOR UPDATE OF s;
    IF v_seat_number IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','not_seated');
    END IF;
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.spin_reserve_ledger r
     WHERE r.tournament_id=p_tournament_id
       AND r.kind IN ('contribution','jackpot_draw')) THEN
    RETURN jsonb_build_object('ok',false,'reason','spin_entry_already_booked');
  END IF;

  PERFORM 1 FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
   ORDER BY e.entitlement_kind,e.id FOR UPDATE;
  SELECT count(*) INTO v_non_cash_count
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.registration_id=v_reg.id
     AND e.entitlement_kind IN ('satellite_seat','tournament_ticket')
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id);
  IF COALESCE(v_reg.is_satellite_qualifier,false)
     AND v_non_cash_count<>1 THEN
    RAISE EXCEPTION
      'satellite-funded registration % requires one unspent ticket entitlement',
      v_reg.id USING ERRCODE='P0404';
  END IF;
  IF NOT COALESCE(v_reg.is_satellite_qualifier,false)
     AND v_non_cash_count<>0 THEN
    RAISE EXCEPTION
      'cash registration % cannot own a satellite ticket entitlement',v_reg.id
      USING ERRCODE='P0404';
  END IF;

  SELECT round(COALESCE(sum(e.refund_prize),0),2),
         round(COALESCE(sum(e.refund_bounty),0),2),
         round(COALESCE(sum(e.refund_fee),0),2),
         round(COALESCE(sum(e.gross),0),2),
         round(COALESCE(sum(e.gross),0),2),
         0::numeric
    INTO v_refund_prize,v_refund_bounty,v_refund_fee,v_refund_total,
         v_wallet_amount,v_ticket_amount
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id);
  IF v_refund_total IS DISTINCT FROM
       round(v_refund_prize+v_refund_bounty+v_refund_fee,2)
     OR v_refund_total IS DISTINCT FROM
       round(v_wallet_amount+v_ticket_amount,2) THEN
    RAISE EXCEPTION 'registration % has invalid entitlement totals',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  -- A funded satellite entry does not invent a player-wallet debit.
  -- It returns the same escrow value in cash through its exact source proof.
  IF COALESCE(v_reg.is_satellite_qualifier,false)
     AND EXISTS (
       SELECT 1 FROM public.tournament_refund_entitlements e
        WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
          AND e.entitlement_kind='wallet_charge'
          AND NOT EXISTS (
            SELECT 1 FROM public.tournament_refund_tranches tr
             WHERE tr.entitlement_id=e.id)) THEN
    RAISE EXCEPTION
      'satellite-funded registration % has an unexpected wallet charge',
      v_reg.id USING ERRCODE='P0404';
  END IF;

  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_debits
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='debit'
     AND lower(w.category) IN ('tournament_buyin','rebuy','addon');
  SELECT round(COALESCE(sum(e.gross),0),2) INTO v_entitled_wallet_total
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.entitlement_kind='wallet_charge';
  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_refunds_before
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='credit'
     AND lower(w.category) IN ('refund','tournament_refund');
  SELECT round(COALESCE(sum(tr.amount_paid_now),0),2) INTO v_tranche_total
    FROM public.tournament_refund_tranches tr
   WHERE tr.tournament_id=p_tournament_id AND tr.user_id=p_user_id;
  IF v_wallet_debits IS DISTINCT FROM v_entitled_wallet_total
     OR v_wallet_refunds_before IS DISTINCT FROM v_tranche_total
     OR v_wallet_refunds_before>(
       SELECT COALESCE(sum(e.gross),0)
         FROM public.tournament_refund_entitlements e
        WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
          AND NOT EXISTS (
            SELECT 1 FROM public.tournament_tickets tk
             WHERE tk.source_refund_entitlement_id=e.id)) THEN
    RAISE EXCEPTION 'registration % wallet and entitlement journals disagree',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  v_running_owed:=v_tranche_total;

  SELECT round(COALESCE(sum(r.rake_amount),0),2) INTO v_rake_before
    FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  SELECT COALESCE(array_agg(e.id ORDER BY e.id),ARRAY[]::uuid[])
    INTO v_fee_entitlement_ids
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
     AND e.refund_fee>0
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id);

  -- Bind every fee-bearing entitlement to its actual same-transaction rake
  -- journal. The refund wallet club is deliberately absent from this match:
  -- it identifies the payer, while rake_records.club_id identifies the fee
  -- recipient and can be a different club.
  WITH fee_sources AS MATERIALIZED (
    SELECT e.id AS entitlement_id,r.id AS rake_record_id,
           r.club_id,r.rake_amount
      FROM public.tournament_refund_entitlements e
      JOIN public.chip_ledger l ON l.id=e.source_ledger_id
      JOIN public.rake_records r
        ON r.tournament_id=e.tournament_id
       AND r.is_tournament IS TRUE
       AND r.club_id IS NOT NULL
       AND r.rake_amount=e.refund_fee
       AND r.created_at=l.created_at
       AND r.metadata->>'user_id'=e.user_id::text
       AND (
         (e.entitlement_kind='wallet_charge'
          AND e.charge_category='tournament_buyin'
          AND r.source IN (
            'fn_register_for_tournament','fn_register_horse_for_tournament')
          AND r.metadata->>'kind'='tournament_entry_fee'
          AND r.metadata->>'registration_id'=v_reg.id::text)
         OR (e.entitlement_kind='wallet_charge'
          AND e.charge_category='rebuy'
          AND r.source='process_tournament_rebuy'
          AND r.metadata->>'kind' IN (
            'tournament_rebuy_fee','tournament_reentry_fee'))
         OR (e.entitlement_kind='satellite_seat'
          AND r.source='fn_award_satellite_seat'
          AND r.metadata->>'kind'='satellite_seat_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text)
         OR (e.entitlement_kind='tournament_ticket'
          AND r.source='fn_register_for_tournament_with_ticket'
          AND r.metadata->>'kind'='tournament_ticket_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text))
     WHERE e.id=ANY(v_fee_entitlement_ids)
  )
  SELECT count(*),count(DISTINCT entitlement_id),
         round(COALESCE(sum(rake_amount),0),2),
         COALESCE(array_agg(rake_record_id ORDER BY rake_record_id),
                  ARRAY[]::uuid[])
    INTO v_fee_source_count,v_fee_source_entitlement_count,
         v_fee_source_amount,v_fee_source_rake_record_ids
    FROM fee_sources;
  IF v_fee_source_count<>cardinality(v_fee_entitlement_ids)
     OR v_fee_source_entitlement_count<>cardinality(v_fee_entitlement_ids)
     OR v_fee_source_count<>(
       SELECT count(DISTINCT id)
         FROM unnest(v_fee_source_rake_record_ids) source(id))
     OR v_fee_source_amount IS DISTINCT FROM v_refund_fee THEN
    RAISE EXCEPTION
      'registration % fee entitlements do not map one-to-one to exact rake evidence',
      v_reg.id USING ERRCODE='P0404';
  END IF;
  PERFORM 1 FROM public.rake_records r
   WHERE r.id=ANY(v_fee_source_rake_record_ids)
   ORDER BY r.club_id,r.id FOR UPDATE;

  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id,'unregister entitlement escrow prelock');
  SELECT * INTO v_escrow_before FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR UPDATE;
  SELECT count(*) INTO v_players_before FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status::text IN ('registered','playing');
  IF v_escrow_before.tournament_id IS NULL
     OR v_escrow_before.enforced IS DISTINCT FROM true
     OR v_players_before<=0
     OR v_t.current_players IS DISTINCT FROM v_players_before
     OR v_t.prize_pool IS DISTINCT FROM v_escrow_before.prize_balance
     OR v_t.bounty_pool IS DISTINCT FROM v_escrow_before.bounty_balance
     OR v_t.total_rake IS DISTINCT FROM v_escrow_before.fee_balance
     OR v_t.total_rake IS DISTINCT FROM v_rake_before
     OR v_t.prize_pool<v_refund_prize
     OR v_t.bounty_pool<v_refund_bounty
     OR v_t.total_rake<v_refund_fee THEN
    RAISE EXCEPTION 'registration % cannot leave divergent tournament state',v_reg.id
      USING ERRCODE='P0404';
  END IF;

  FOR v_ent IN
    SELECT e.* FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
       AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_refund_tranches tr
          WHERE tr.entitlement_id=e.id)
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_refund_entitlement_id=e.id)
     ORDER BY e.entitlement_kind,e.id
  LOOP
    v_running_owed:=round(v_running_owed+v_ent.gross,2);
    v_settle:=public.fn_settle_tournament_refund_exact(
      p_tournament_id,p_user_id,v_ent.refund_wallet_club_id,v_running_owed,
      v_ent.refund_prize,v_ent.refund_bounty,v_ent.refund_fee,
      'fn_unregister_from_tournament',v_description);
    IF COALESCE((v_settle->>'ok')::boolean,false) IS NOT TRUE
       OR (v_settle->>'entitlement_id')::uuid IS DISTINCT FROM v_ent.id
       OR (v_settle->>'paid')::numeric IS DISTINCT FROM v_ent.gross
       OR (v_settle->>'amount_paid')::numeric IS DISTINCT FROM v_running_owed
       OR (v_settle->>'source_wallet_club_id')::uuid
            IS DISTINCT FROM v_ent.refund_wallet_club_id THEN
      RAISE EXCEPTION 'registration % exact wallet refund failed',v_reg.id
        USING ERRCODE='P0404';
    END IF;
    v_entitlement_ids:=array_append(v_entitlement_ids,v_ent.id);
    v_source_wallet_club_ids:=array_append(
      v_source_wallet_club_ids,v_ent.refund_wallet_club_id);
    v_credit_ledger_ids:=array_append(
      v_credit_ledger_ids,(v_settle->>'credit_ledger_id')::uuid);
    v_wallet_transaction_ids:=array_append(
      v_wallet_transaction_ids,(v_settle->>'wallet_transaction_id')::uuid);
  END LOOP;

  FOR v_fee_group IN
    SELECT r.club_id,round(sum(r.rake_amount),2) AS fee,
           array_agg(r.id ORDER BY r.id) AS source_rake_record_ids,
           array_agg(e.id ORDER BY e.id) AS entitlement_ids
      FROM public.rake_records r
      JOIN public.tournament_refund_entitlements e
        ON e.id=ANY(v_fee_entitlement_ids)
       AND e.refund_fee=r.rake_amount
       AND e.tournament_id=r.tournament_id
       AND e.user_id=p_user_id
       AND r.metadata->>'user_id'=e.user_id::text
       AND (
         (e.entitlement_kind='wallet_charge'
          AND e.charge_category='tournament_buyin'
          AND r.source IN (
            'fn_register_for_tournament','fn_register_horse_for_tournament')
          AND r.metadata->>'kind'='tournament_entry_fee'
          AND r.metadata->>'registration_id'=v_reg.id::text)
         OR (e.entitlement_kind='wallet_charge'
          AND e.charge_category='rebuy'
          AND r.source='process_tournament_rebuy'
          AND r.metadata->>'kind' IN (
            'tournament_rebuy_fee','tournament_reentry_fee'))
         OR (e.entitlement_kind='satellite_seat'
          AND r.source='fn_award_satellite_seat'
          AND r.metadata->>'kind'='satellite_seat_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text)
         OR (e.entitlement_kind='tournament_ticket'
          AND r.source='fn_register_for_tournament_with_ticket'
          AND r.metadata->>'kind'='tournament_ticket_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text))
      JOIN public.chip_ledger l
        ON l.id=e.source_ledger_id AND l.created_at=r.created_at
     WHERE r.id=ANY(v_fee_source_rake_record_ids)
     GROUP BY r.club_id ORDER BY r.club_id
  LOOP
    IF v_fee_group.fee>0 THEN
      INSERT INTO public.rake_records(
        hand_id,table_id,club_id,rake_amount,pot_size,num_players,
        bbj_contribution,is_tournament,tournament_id,source,metadata)
      VALUES(
        NULL,NULL,v_fee_group.club_id,-v_fee_group.fee,v_fee_group.fee,1,
        0,true,p_tournament_id,'fn_unregister_from_tournament',
        jsonb_build_object(
          'kind','tournament_fee_refund','user_id',p_user_id,
          'registration_id',v_reg.id,
          'fee_recipient_club_id',v_fee_group.club_id,
          'entitlement_ids',to_jsonb(v_fee_group.entitlement_ids),
          'original_rake_record_ids',
            to_jsonb(v_fee_group.source_rake_record_ids)))
      RETURNING id INTO v_fee_reversal_id;
      v_fee_reversal_ids:=array_append(
        v_fee_reversal_ids,v_fee_reversal_id);
      v_fees_reversed:=round(v_fees_reversed+v_fee_group.fee,2);
    END IF;
  END LOOP;
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[])
    INTO v_fee_reversal_ids
    FROM unnest(v_fee_reversal_ids) reversal(id);
  IF v_fees_reversed IS DISTINCT FROM v_refund_fee THEN
    RAISE EXCEPTION
      'registration % reversed % in exact fee rows but owes %',
      v_reg.id,v_fees_reversed,v_refund_fee USING ERRCODE='P0404';
  END IF;

  UPDATE public.tournaments
     SET current_players=v_players_before-1,
         prize_pool=round(v_t.prize_pool-v_refund_prize,2),
         bounty_pool=round(v_t.bounty_pool-v_refund_bounty,2),
         total_rake=round(v_t.total_rake-v_refund_fee,2),updated_at=now()
   WHERE id=p_tournament_id
     AND current_players IS NOT DISTINCT FROM v_players_before
     AND prize_pool IS NOT DISTINCT FROM v_t.prize_pool
     AND bounty_pool IS NOT DISTINCT FROM v_t.bounty_pool
     AND total_rake IS NOT DISTINCT FROM v_t.total_rake;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'registration % tournament cache changed',v_reg.id
      USING ERRCODE='55000';
  END IF;

  UPDATE public.table_seats s
     SET left_at=transaction_timestamp(),status='left',leave_pending=false,
         is_sitting_out=false,is_away=false,sit_out_at=NULL,
         scheduled_leave_hands=NULL
   WHERE s.user_id=p_user_id AND s.left_at IS NULL
     AND EXISTS(SELECT 1 FROM public.tables tb
                 WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id);
  UPDATE public.tables tb
     SET current_players=(SELECT count(*) FROM public.table_seats s
                           WHERE s.table_id=tb.id AND s.left_at IS NULL),
         updated_at=now()
   WHERE tb.tournament_id=p_tournament_id;
  DELETE FROM public.tournament_players tp WHERE tp.id=v_reg.id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'registration % was not deleted after settlement',v_reg.id
      USING ERRCODE='55000';
  END IF;

  SELECT * INTO v_escrow_after FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id;
  SELECT round(COALESCE(sum(r.rake_amount),0),2) INTO v_rake_after
    FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_refunds_after
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='credit'
     AND lower(w.category) IN ('refund','tournament_refund');
  IF (SELECT count(*) FROM public.tournament_players tp
       WHERE tp.tournament_id=p_tournament_id
         AND tp.status::text IN ('registered','playing'))<>v_players_before-1
     OR v_wallet_refunds_after IS DISTINCT FROM
          round(v_wallet_refunds_before+v_wallet_amount,2)
     OR v_escrow_after.prize_balance IS DISTINCT FROM
          round(v_escrow_before.prize_balance-v_refund_prize,2)
     OR v_escrow_after.bounty_balance IS DISTINCT FROM
          round(v_escrow_before.bounty_balance-v_refund_bounty,2)
     OR v_escrow_after.fee_balance IS DISTINCT FROM
          round(v_escrow_before.fee_balance-v_refund_fee,2)
     OR v_rake_after IS DISTINCT FROM round(v_rake_before-v_refund_fee,2)
     OR NOT EXISTS(
       SELECT 1 FROM public.tournaments t
        WHERE t.id=p_tournament_id
          AND t.current_players=v_players_before-1
          AND t.prize_pool=v_escrow_after.prize_balance
          AND t.bounty_pool=v_escrow_after.bounty_balance
          AND t.total_rake=v_rake_after) THEN
    RAISE EXCEPTION 'registration % did not leave exact final state',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  IF p_expected_table_id IS NOT NULL THEN
    SELECT count(*) INTO v_seats_taken FROM public.table_seats s
     WHERE s.table_id=p_expected_table_id AND s.left_at IS NULL;
  END IF;

  -- Re-prove the chosen start authority after all money and seat work. Timed
  -- events still use the locked schedule cutoff; every product also treats a
  -- persisted hand as irreversible start truth; seat-first products further
  -- use status, started_at and completed launch truth. Any loss of the race
  -- rolls every preceding write back atomically.
  v_unregistered_at:=clock_timestamp();
  SELECT EXISTS (
           SELECT 1
             FROM public.hand_history hh
            WHERE hh.tournament_id=p_tournament_id
         ) OR EXISTS (
           SELECT 1
             FROM public.tables hand_table
             JOIN public.hand_history hh ON hh.table_id=hand_table.id
            WHERE hand_table.tournament_id=p_tournament_id
         )
    INTO v_persisted_hand_exists;
  IF v_persisted_hand_exists THEN
    RAISE EXCEPTION
      'tournament hand persisted before unregistration could commit'
      USING ERRCODE='55000';
  END IF;
  IF v_start_authority='scheduled_clock' THEN
    IF v_unregistered_at>=v_t.start_time THEN
      RAISE EXCEPTION 'tournament started before unregistration could commit'
        USING ERRCODE='55000';
    END IF;
  ELSE
    SELECT t.status::text,t.started_at,launch.completed_at
      INTO v_actual_status,v_actual_started_at,v_launch_completed_at
      FROM public.tournaments t
      LEFT JOIN public.tournament_launch_receipts launch
        ON launch.tournament_id=t.id
     WHERE t.id=p_tournament_id;
    IF upper(COALESCE(v_actual_status,'')) NOT IN ('ANNOUNCED','REGISTERING')
       OR v_actual_started_at IS NOT NULL
       OR v_launch_completed_at IS NOT NULL THEN
      RAISE EXCEPTION
        'seat-first tournament started before unregistration could commit'
        USING ERRCODE='55000';
    END IF;
  END IF;

  INSERT INTO public.tournament_unregistration_receipts(
    registration_id,request_id,tournament_id,user_id,source_table_id,
    refunded_chips,returned_ticket_value,entitlement_ids,ticket_ids,
    source_wallet_club_ids,credit_ledger_ids,wallet_transaction_ids,
    fees_reversed,fee_reversal_ids,fee_source_rake_record_ids,
    seat_number,seats_taken,scheduled_start_at,start_authority,settled_at)
  VALUES(
    v_reg.id,v_request_id,p_tournament_id,p_user_id,p_expected_table_id,
    v_wallet_amount,v_ticket_amount,v_entitlement_ids,v_ticket_ids,
    v_source_wallet_club_ids,v_credit_ledger_ids,v_wallet_transaction_ids,
    v_fees_reversed,v_fee_reversal_ids,v_fee_source_rake_record_ids,
    v_seat_number,v_seats_taken,v_t.start_time,v_start_authority,v_unregistered_at);
  v_receipt:=public.fn_ca_tournament_unregistration_receipt(
    p_tournament_id,p_user_id,p_expected_table_id,v_request_id);
  IF v_receipt IS NULL
     OR (v_receipt->>'registration_id')::uuid IS DISTINCT FROM v_reg.id THEN
    RAISE EXCEPTION 'registration % has no exact unregistration receipt',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  RETURN v_receipt||jsonb_build_object('replayed',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_use_cashier_entry_ticket(p_tournament_id uuid, p_ticket_id uuid, p_beneficiary_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := p_beneficiary_id;
  v_t public.tournaments%ROWTYPE;
  v_tk public.tournament_tickets%ROWTYPE;
  v_bind public.tournament_ticket_entry_targets%ROWTYPE;
  v_split record;
  v_is_bounty boolean;
  v_is_horse boolean;
  v_before numeric;
  v_after_credit numeric;
  v_after numeric;
  v_context jsonb;
  v_setting text;
  v_prev_paying text := current_setting('app.ca_entry_paying_club', true);
  v_result jsonb;
  v_reason text;
  v_registration uuid;
  v_receipt uuid;
BEGIN
  IF p_tournament_id IS NULL OR p_ticket_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'tournament, ticket and beneficiary ids are required'
      USING ERRCODE = '22004';
  END IF;

  -- The satellite ticket door's lock order: settlement lane, the shared
  -- admission lock, the admission contract, the tournament, then the ticket.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id = p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_tk FROM public.tournament_tickets tk WHERE tk.id = p_ticket_id FOR UPDATE;
  IF v_tk.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_found');
  END IF;
  SELECT * INTO v_bind FROM public.tournament_ticket_entry_targets b
   WHERE b.ticket_id = v_tk.id;
  IF v_bind.ticket_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','not_a_cashier_entry_ticket');
  END IF;
  IF v_tk.holder_id IS DISTINCT FROM v_uid OR v_bind.holder_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_owned');
  END IF;
  IF v_bind.tournament_id IS DISTINCT FROM p_tournament_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_for_another_tournament');
  END IF;
  IF v_tk.redemption_mode IS DISTINCT FROM 'wallet_chips'
     OR v_tk.club_id IS DISTINCT FROM v_bind.club_id
     OR v_tk.issued_by IS DISTINCT FROM v_bind.issued_by
     OR v_tk.value IS DISTINCT FROM v_bind.value THEN
    RAISE EXCEPTION 'cashier entry ticket % does not match its binding', v_tk.id
      USING ERRCODE = 'P0404';
  END IF;

  IF v_tk.status = 'redeemed' THEN
    -- An ambiguous-response retry: the entry already happened.
    SELECT ct.id INTO v_receipt FROM public.chip_transactions ct
     WHERE ct.transaction_type = 'tournament_ticket_redeem'
       AND ct.metadata->>'ticket_id' = v_tk.id::text
       AND ct.metadata->>'reason' = 'tournament_entry'
     LIMIT 1;
    SELECT tp.id INTO v_registration FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.user_id = v_uid
     ORDER BY tp.registered_at DESC NULLS LAST LIMIT 1;
    IF v_receipt IS NOT NULL AND v_registration IS NOT NULL THEN
      RETURN jsonb_build_object('ok',true,'replayed',true,'ticket_id',v_tk.id,
        'registration_id',v_registration,'ticket_value',v_tk.value,
        'wallet_chips_credited',0);
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','ticket_already_used');
  END IF;
  IF v_tk.status <> 'issued' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_available');
  END IF;

  v_is_bounty := COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_is_bounty);
  IF v_split.charge IS DISTINCT FROM v_bind.value
     OR v_split.prize IS DISTINCT FROM v_bind.entry_prize
     OR v_split.bounty IS DISTINCT FROM v_bind.entry_bounty
     OR v_split.rake IS DISTINCT FROM v_bind.entry_fee THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_entry_contract_mismatch');
  END IF;
  IF public.fn_tournament_club_for_user(v_uid, p_tournament_id, v_tk.club_id)
       IS DISTINCT FROM v_tk.club_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_source_club_unavailable');
  END IF;

  SELECT COALESCE(p.is_horse,false) INTO v_is_horse FROM public.profiles p WHERE p.id = v_uid;
  v_is_horse := COALESCE(v_is_horse,false);
  IF NOT v_is_horse AND auth.uid() IS DISTINCT FROM v_uid THEN
    -- A person is entered only by their own session; a horse has no browser
    -- and is entered by the engine (CLAUDE.md 10.5, the input device).
    RAISE EXCEPTION 'a cashier entry ticket is used by its own holder'
      USING ERRCODE = '42501';
  END IF;

  SELECT m.chip_balance INTO v_before FROM public.club_members m
   WHERE m.club_id = v_tk.club_id AND m.user_id = v_uid
     AND COALESCE(m.status,'active') IN ('active','approved')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_club_membership_inactive');
  END IF;
  v_before := COALESCE(v_before,0);

  BEGIN
    -- (a) Escrow -> the holder's wallet in the ticket's club, journaled and
    --     receipted exactly as fn_redeem_tournament_ticket does it.
    SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),'')) INTO v_context
      FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty',
                        'app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
    PERFORM set_config('app.ledger_tournament','',true);
    PERFORM set_config('app.ledger_category','ticket_redeem',true);
    PERFORM set_config('app.ledger_counterparty','escrow',true);
    PERFORM set_config('app.ledger_counterparty_entity',v_tk.id::text,true);
    UPDATE public.club_members
       SET chip_balance = COALESCE(chip_balance,0) + v_tk.value, updated_at = now()
     WHERE club_id = v_tk.club_id AND user_id = v_uid
       AND COALESCE(status,'active') IN ('active','approved')
     RETURNING chip_balance INTO v_after_credit;
    FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
      PERFORM set_config(v_setting,v_context->>v_setting,true);
    END LOOP;
    IF v_after_credit IS DISTINCT FROM round(v_before + v_tk.value,2) THEN
      RAISE EXCEPTION 'cashier entry ticket % credit did not land exactly', v_tk.id
        USING ERRCODE = 'P0404';
    END IF;
    UPDATE public.tournament_tickets
       SET status = 'redeemed', redeemed_at = now()
     WHERE id = v_tk.id AND status = 'issued';
    INSERT INTO public.chip_transactions(
      club_id,from_user_id,to_user_id,amount,transaction_type,notes,
      balance_after,metadata)
    VALUES(
      v_tk.club_id,NULL,v_uid,v_tk.value,'tournament_ticket_redeem',
      'Tournament Ticket Used For Entry',v_after_credit,
      jsonb_build_object(
        'ticket_id',v_tk.id,'issuer_id',v_tk.issued_by,'holder_id',v_uid,
        'escrow_action','release_to_holder','reason','tournament_entry',
        'target_tournament_id',p_tournament_id,
        'holder_balance_after',v_after_credit))
    RETURNING id INTO v_receipt;
    INSERT INTO public.wallet_transactions(
      user_id,wallet_type,type,amount,category,description,balance_after)
    VALUES(
      v_uid,'PLAYER','credit',v_tk.value,'transfer',
      'Tournament Ticket Used For Entry',v_after_credit);

    -- (b) The ordinary entry door, paid from that same wallet.
    PERFORM set_config('app.ca_entry_paying_club',
      p_tournament_id::text||':'||v_uid::text||':'||v_tk.club_id::text, true);
    IF v_is_horse THEN
      v_result := public.fn_register_horse_for_tournament_before_atomic_lifecycle_gate(
        p_tournament_id, v_uid);
    ELSE
      v_result := public.fn_register_for_tournament_before_terminal_seat_gate(
        p_tournament_id, false);
    END IF;
    PERFORM set_config('app.ca_entry_paying_club', COALESCE(v_prev_paying,''), true);
    IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN
      RAISE EXCEPTION USING ERRCODE = 'CT001',
        MESSAGE = COALESCE(NULLIF(v_result->>'reason',''),'registration_refused');
    END IF;

    -- (c) The wallet nets to zero exactly, in the ticket's club, or nothing
    --     happened.
    SELECT m.chip_balance INTO v_after FROM public.club_members m
     WHERE m.club_id = v_tk.club_id AND m.user_id = v_uid;
    SELECT tp.id INTO v_registration FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.user_id = v_uid
       AND tp.id = (v_result->>'registration_id')::uuid;
    IF v_after IS DISTINCT FROM v_before OR v_registration IS NULL
       OR (v_result->>'cost')::numeric IS DISTINCT FROM v_tk.value THEN
      RAISE EXCEPTION 'cashier entry ticket % entry was not paid exactly from its own credit (% -> %)',
        v_tk.id, v_before, v_after USING ERRCODE = 'P0404';
    END IF;
  EXCEPTION WHEN SQLSTATE 'CT001' THEN
    v_reason := SQLERRM;
    PERFORM set_config('app.ca_entry_paying_club', COALESCE(v_prev_paying,''), true);
    RETURN jsonb_build_object('ok',false,'reason',v_reason,'ticket_id',v_tk.id);
  END;

  RETURN v_result || jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_tk.id,
    'registration_id',v_registration,'ticket_value',v_tk.value,
    'ticket_kind','cashier_entry_ticket','redeem_transaction_id',v_receipt,
    'wallet_chips_credited',0);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_caller_session_is_live()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_claims jsonb;
  v_sid    uuid;
BEGIN
  IF public.fn_caller_is_engine() THEN
    RETURN true;
  END IF;

  -- Malformed or absent claims are not a crash, they are a refusal.
  BEGIN
    v_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN others THEN
    RETURN false;
  END;

  IF v_claims IS NULL THEN
    RETURN false;
  END IF;

  BEGIN
    v_sid := (v_claims ->> 'session_id')::uuid;
  EXCEPTION WHEN others THEN
    RETURN false;
  END;

  IF v_sid IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
      FROM auth.sessions s
     WHERE s.id = v_sid
       AND (s.not_after IS NULL OR s.not_after > now())
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cashout_seats_for_closing_table(p_table_id uuid, p_reason text DEFAULT 'table closed'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tournament uuid;
BEGIN
  SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CASHOUT_TABLE_NOT_FOUND' USING ERRCODE='22023';
  END IF;
  IF v_tournament IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'skipped','tournament_table');
  END IF;
  -- This read-only assertion is also reached from authorized administrator
  -- close RPCs. It must not require an engine JWT when it moves no money.
  IF EXISTS (SELECT 1 FROM public.table_seats WHERE table_id=p_table_id AND left_at IS NULL) THEN
    RAISE EXCEPTION 'CASH_TABLE_CLOSE_REQUIRES_ENGINE_DEPARTURES' USING ERRCODE='55000';
  END IF;
  RETURN jsonb_build_object('ok',true,'players_paid',0,
    'chips_returned',0,'reason_text',coalesce(p_reason,'table closed'));
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_emit_managed_game_row_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_document jsonb := to_jsonb(NEW);
  v_old_document jsonb := to_jsonb(OLD);
  v_club  uuid := COALESCE(v_new_document ->> 'club_id', v_old_document ->> 'club_id')::uuid;
  v_id    uuid := COALESCE(v_new_document ->> 'id',      v_old_document ->> 'id')::uuid;
  v_watch text[];
BEGIN
  -- Tournament backing tables are represented by the tournament event itself.
  IF TG_TABLE_NAME = 'tables' THEN
    IF COALESCE(v_new_document ->> 'tournament_id',
                v_old_document ->> 'tournament_id') IS NOT NULL THEN
      RETURN NULL;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Exactly the columns fn_list_managed_games projects for this kind. Keep
    -- these two lists in step with that function: a column the board reads and
    -- this does not watch is a row that silently stops refreshing.
    v_watch := CASE TG_TABLE_NAME
      WHEN 'tables' THEN ARRAY[
        'club_id', 'union_id', 'tournament_id', 'is_deleted', 'name', 'status',
        'game_variant', 'current_players', 'max_players', 'small_blind',
        'big_blind', 'min_buy_in', 'max_buy_in', 'created_at']
      ELSE ARRAY[
        'club_id', 'union_id', 'name', 'status', 'game_type', 'variant',
        'current_players', 'max_players', 'start_time', 'created_at',
        'buy_in_amount', 'guaranteed_prize', 'prize_pool']
    END;

    IF (SELECT jsonb_object_agg(k, COALESCE(v_old_document -> k, 'null'::jsonb))
          FROM unnest(v_watch) AS k)
       IS NOT DISTINCT FROM
       (SELECT jsonb_object_agg(k, COALESCE(v_new_document -> k, 'null'::jsonb))
          FROM unnest(v_watch) AS k)
    THEN
      RETURN NULL;
    END IF;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    'game_changed', v_club, NULL, NULL,
    CASE WHEN TG_TABLE_NAME = 'tables' THEN 'table' ELSE 'tournament' END,
    v_id, NULL, jsonb_build_object('operation', lower(TG_OP)));
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_emit_tournament_manager_wake(p_tournament_id uuid, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id bigint;
  v_status text;
BEGIN
  IF p_reason NOT IN (
    'rebuy','reentry','addon','late_registration','deal_vote','bounty_settled'
  ) THEN
    RAISE EXCEPTION 'invalid tournament manager wake reason';
  END IF;

  -- Serialize every emitter with the tournament lifecycle transition. UPDATE
  -- takes a NO KEY UPDATE lock, which conflicts with FOR SHARE: an emitter that
  -- commits first is consumed by the terminal AFTER trigger, while an emitter
  -- that arrives second observes the terminal state and cannot strand work for
  -- a manager that has already stopped. Terminal recovery can still settle a
  -- legacy financial obligation; it simply has no live manager to wake.
  SELECT upper(COALESCE(t.status,''))
    INTO v_status
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE='foreign_key_violation';
  END IF;
  IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.tournament_manager_wakes AS pending(tournament_id,reason,generation)
  VALUES (p_tournament_id,p_reason,1)
  ON CONFLICT (tournament_id,reason) WHERE consumed_at IS NULL
  DO UPDATE SET
    generation=pending.generation+1,
    created_at=clock_timestamp()
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_freerolls_are_free_buy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_changed jsonb := '{}'::jsonb;
  v_stack   integer;
  v_op      text;
  v_price   numeric;
BEGIN
  IF NOT public.fn_is_free_buy_event(
       NEW.buy_in_amount, NEW.buy_in_fee, NEW.tournament_type, NEW.variant
     ) THEN
    RETURN NEW;
  END IF;

  -- A live or finished event keeps the contract its players entered under.
  -- Inserts are always pre-start.
  IF TG_OP = 'UPDATE'
     AND upper(COALESCE(NEW.status, '')) NOT IN ('ANNOUNCED', 'REGISTERING') THEN
    RETURN NEW;
  END IF;

  v_stack := COALESCE(NULLIF(NEW.starting_chips, 0), 10000);

  /* EVERY FREEROLL REBUY AND ADD-ON HAS ONE PRICE (Dan 2026-10-16): "ALL REBUY
     ADD ON'S FOR MIDWAY UNION ARE 1 CHIP REBUY ADD ON NOT 2, DIAMOND REBUYS
     ARE 100 DIAMONDS (ONE DOLLAR)". 1 in a chip club, 100 in a Diamond club.
     The 2026-09-04 exception that let a scheduled Free Buy charge 2 is gone. */
  v_price := CASE
    WHEN EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = NEW.club_id AND c.asset = 'diamonds')
      THEN 100.00
    ELSE 1.00
  END;

  IF NEW.buy_in_fee IS DISTINCT FROM 0 THEN
    v_changed := v_changed || jsonb_build_object('buy_in_fee',
      jsonb_build_object('from', NEW.buy_in_fee, 'to', 0));
    NEW.buy_in_fee := 0;
  END IF;

  IF NOT COALESCE(NEW.is_rebuy, false) THEN
    v_changed := v_changed || jsonb_build_object('is_rebuy',
      jsonb_build_object('from', NEW.is_rebuy, 'to', true));
    NEW.is_rebuy := true;
  END IF;

  IF NOT COALESCE(NEW.add_on_available, false) THEN
    v_changed := v_changed || jsonb_build_object('add_on_available',
      jsonb_build_object('from', NEW.add_on_available, 'to', true));
    NEW.add_on_available := true;
  END IF;

  IF NEW.rebuy_cost IS DISTINCT FROM v_price THEN
    v_changed := v_changed || jsonb_build_object('rebuy_cost',
      jsonb_build_object('from', NEW.rebuy_cost, 'to', v_price));
    NEW.rebuy_cost := v_price;
  END IF;

  IF NEW.addon_cost IS DISTINCT FROM v_price THEN
    v_changed := v_changed || jsonb_build_object('addon_cost',
      jsonb_build_object('from', NEW.addon_cost, 'to', v_price));
    NEW.addon_cost := v_price;
  END IF;

  IF COALESCE(NEW.rebuy_chips, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('rebuy_chips',
      jsonb_build_object('from', NEW.rebuy_chips, 'to', v_stack));
    NEW.rebuy_chips := v_stack;
  END IF;

  IF COALESCE(NEW.addon_chips, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('addon_chips',
      jsonb_build_object('from', NEW.addon_chips, 'to', v_stack));
    NEW.addon_chips := v_stack;
  END IF;

  IF COALESCE(NEW.rebuy_levels, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('rebuy_levels',
      jsonb_build_object('from', NEW.rebuy_levels, 'to', 4));
    NEW.rebuy_levels := 4;
  END IF;

  IF COALESCE(NEW.addon_levels, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('addon_levels',
      jsonb_build_object('from', NEW.addon_levels, 'to', 1));
    NEW.addon_levels := 1;
  END IF;

  IF NEW.max_rebuys IS NOT NULL AND NEW.max_rebuys <= 0 THEN
    v_changed := v_changed || jsonb_build_object('max_rebuys',
      jsonb_build_object('from', NEW.max_rebuys, 'to', NULL));
    NEW.max_rebuys := NULL;
  END IF;

  IF v_changed <> '{}'::jsonb THEN
    v_op := CASE
      WHEN COALESCE(current_setting('app.freeroll_free_buy_backfill', true), '') = 'on'
        THEN 'BACKFILL'
      ELSE TG_OP
    END;
    BEGIN
      INSERT INTO public.ca_freeroll_free_buy_log
        (tournament_id, tournament_name, op, status, changed)
      VALUES
        (NEW.id, NEW.name, v_op, NEW.status, v_changed);
    EXCEPTION WHEN OTHERS THEN
      -- The log is evidence, not a gate. Never let it block the row.
      RAISE WARNING 'fn_freerolls_are_free_buy: could not log % for %: %',
        v_op, NEW.id, SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_new_mtt_blind_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE contract jsonb;
BEGIN
  IF (TG_OP='INSERT' OR OLD.format_contract IN ('mtt-v1','mtt-v2'))
     AND public.fn_ca_new_tournament_is_unlimited(to_jsonb(NEW)) THEN
    IF TG_OP='UPDATE' AND OLD.format_contract IN ('mtt-v1','mtt-v2')
       AND NEW.blind_structure IS NOT DISTINCT FROM OLD.blind_structure
       AND NEW.starting_chips IS NOT DISTINCT FROM OLD.starting_chips THEN RETURN NEW; END IF;
    contract:=public.fn_ca_mtt_blind_contract(NEW.blind_structure,NEW.starting_chips);
    NEW.blind_speed:=contract->>'blind_speed';
    NEW.is_turbo:=(contract->>'is_turbo')::boolean;
    RETURN NEW;
  END IF;
  IF upper(COALESCE(NEW.tournament_type,''))<>'MTT'
     OR lower(COALESCE(NEW.variant,'')) IN ('spin','sng')
     OR COALESCE(NEW.max_players,0)<=2 THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.blind_structure IS NOT DISTINCT FROM OLD.blind_structure
     AND NEW.starting_chips IS NOT DISTINCT FROM OLD.starting_chips
     AND upper(COALESCE(OLD.tournament_type,''))='MTT'
     AND lower(COALESCE(OLD.variant,'')) NOT IN ('spin','sng')
     AND COALESCE(OLD.max_players,0)>2 THEN RETURN NEW; END IF;
  contract:=public.fn_ca_mtt_blind_contract(NEW.blind_structure,NEW.starting_chips);
  NEW.blind_speed:=contract->>'blind_speed';
  NEW.is_turbo:=(contract->>'is_turbo')::boolean;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_tournament_mystery_creation_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_expected jsonb; v_actual jsonb;
BEGIN
  IF TG_OP='UPDATE' AND coalesce(OLD.is_mystery_bounty,false)
     AND OLD.mystery_bounty_stage IS DISTINCT FROM 'pending'
     AND ROW(NEW.is_mystery_bounty,NEW.mystery_bounty_profile,NEW.mystery_bounty_activation,NEW.mystery_bounty_activation_value,
       NEW.mystery_bounty_pool_percent,NEW.mystery_bounty_regular_pool_percent,NEW.mystery_bounty_top_percent)
     IS DISTINCT FROM ROW(OLD.is_mystery_bounty,OLD.mystery_bounty_profile,OLD.mystery_bounty_activation,OLD.mystery_bounty_activation_value,
       OLD.mystery_bounty_pool_percent,OLD.mystery_bounty_regular_pool_percent,OLD.mystery_bounty_top_percent) THEN
    RAISE EXCEPTION 'Mystery bounty terms cannot change after activation' USING ERRCODE='55000';
  END IF;
  IF NOT coalesce(NEW.is_mystery_bounty,false) THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND coalesce(OLD.is_mystery_bounty,false)
     AND ROW(NEW.mystery_bounty_profile,NEW.mystery_bounty_activation,NEW.mystery_bounty_activation_value,
       NEW.mystery_bounty_pool_percent,NEW.mystery_bounty_regular_pool_percent,NEW.mystery_bounty_top_percent)
     IS NOT DISTINCT FROM ROW(OLD.mystery_bounty_profile,OLD.mystery_bounty_activation,OLD.mystery_bounty_activation_value,
       OLD.mystery_bounty_pool_percent,OLD.mystery_bounty_regular_pool_percent,OLD.mystery_bounty_top_percent)
    THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.mystery_bounty_stage IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'Mystery bounty terms cannot change after activation' USING ERRCODE='55000';
  END IF;
  v_expected:=public.fn_mystery_bounty_creation_document(jsonb_build_object(
    'mysteryBountyProfile',NEW.mystery_bounty_profile,'mysteryBountyActivation',NEW.mystery_bounty_activation,
    'mysteryBountyActivationValue',NEW.mystery_bounty_activation_value,
    'mysteryBountyPoolPercent',NEW.mystery_bounty_pool_percent,'mysteryBountyTopPercent',NEW.mystery_bounty_top_percent));
  IF NEW.mystery_bounty_regular_pool_percent IS DISTINCT FROM
     (v_expected->>'mystery_bounty_regular_pool_percent')::numeric THEN
    RAISE EXCEPTION 'Mystery bounty pool percentages must total 100' USING ERRCODE='22023';
  END IF;
  v_actual:=jsonb_build_object('mystery_bounty_profile',NEW.mystery_bounty_profile,
    'mystery_bounty_activation',NEW.mystery_bounty_activation,
    'mystery_bounty_activation_value',NEW.mystery_bounty_activation_value,
    'mystery_bounty_pool_percent',NEW.mystery_bounty_pool_percent,
    'mystery_bounty_regular_pool_percent',NEW.mystery_bounty_regular_pool_percent,
    'mystery_bounty_top_percent',NEW.mystery_bounty_top_percent);
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Invalid canonical mystery bounty configuration' USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_tournament_prize_math_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_unit integer;
BEGIN
  IF TG_OP='UPDATE' THEN
    -- Legacy club routing remains governed by its existing contract guards.
    -- This trigger freezes denomination only for an explicitly versioned ladder.
    IF OLD.payout_math_version=1 AND NEW.payout_math_version=1
       AND OLD.payout_unit_cents=1 AND NEW.payout_unit_cents=1 THEN RETURN NEW; END IF;
    IF ROW(NEW.payout_math_version,NEW.payout_unit_cents,NEW.club_id) IS NOT DISTINCT FROM
       ROW(OLD.payout_math_version,OLD.payout_unit_cents,OLD.club_id) THEN RETURN NEW; END IF;
    IF COALESCE(OLD.entry_contract_locked,false) OR COALESCE(OLD.prize_pool_finalized,false)
       OR OLD.started_at IS NOT NULL
       OR upper(COALESCE(OLD.status,'')) NOT IN('ANNOUNCED','REGISTERING','SCHEDULED')
       OR upper(COALESCE(NEW.status,'')) NOT IN('ANNOUNCED','REGISTERING','SCHEDULED')
       OR EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=OLD.id)
       OR EXISTS(SELECT 1 FROM public.tournament_payouts tp WHERE tp.tournament_id=OLD.id)
       OR EXISTS(SELECT 1 FROM public.tournament_launch_receipts lr WHERE lr.tournament_id=OLD.id) THEN
      RAISE EXCEPTION 'Tournament prize arithmetic is frozen after entry or launch'
        USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.payout_math_version=2 THEN
    SELECT CASE WHEN c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL
                THEN 100 ELSE 1 END INTO v_unit FROM public.clubs c WHERE c.id=NEW.club_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Prize contract requires an existing club' USING ERRCODE='23503'; END IF;
    -- The club determines denomination; a caller cannot request fractional Diamonds.
    NEW.payout_unit_cents:=v_unit;
  ELSE
    NEW.payout_unit_cents:=1;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_is_platform_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();
  RETURN v_role IN ('admin', 'superadmin', 'god');
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_lock_daily_mission_user(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A Daily Missions player is required';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('daily-missions-user:' || p_user_id::text, 0)
  );

  PERFORM 1
  FROM public.profiles
  WHERE id = p_user_id
  FOR NO KEY UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Daily Missions profile not found for player %', p_user_id;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_mystery_bounty_creation_document(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_profile text:=coalesce(p_config->>'mysteryBountyProfile','classic');
  v_activation text:=coalesce(p_config->>'mysteryBountyActivation','at_the_money');
  v_value jsonb:=coalesce(p_config->'mysteryBountyActivationValue','null'::jsonb);
  v_pool jsonb:=coalesce(nullif(p_config->'mysteryBountyPoolPercent','null'::jsonb),'50'::jsonb);
  v_top jsonb:=coalesce(nullif(p_config->'mysteryBountyTopPercent','null'::jsonb),'20'::jsonb);
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object' THEN
    RAISE EXCEPTION 'Invalid mystery bounty configuration' USING ERRCODE='22023';
  END IF;
  IF v_profile NOT IN ('balanced','classic','jackpot') THEN
    RAISE EXCEPTION 'Invalid mystery bounty profile' USING ERRCODE='22023';
  END IF;
  IF v_activation NOT IN ('at_the_money','percent_field','player_count') THEN
    RAISE EXCEPTION 'Invalid mystery bounty activation' USING ERRCODE='22023';
  END IF;
  IF v_activation<>'at_the_money' THEN
    IF jsonb_typeof(v_value)<>'number' THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation value' USING ERRCODE='22023';
    END IF;
    IF v_activation='percent_field' AND ((v_value#>>'{}')::numeric<=0 OR (v_value#>>'{}')::numeric>100) THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation percentage' USING ERRCODE='22023';
    END IF;
    IF v_activation='player_count' AND ((v_value#>>'{}')::numeric<2
       OR (v_value#>>'{}')::numeric>9007199254740991
       OR trunc((v_value#>>'{}')::numeric)<>(v_value#>>'{}')::numeric) THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation player count' USING ERRCODE='22023';
    END IF;
  ELSE
    v_value:='null'::jsonb;
  END IF;
  IF jsonb_typeof(v_pool)<>'number' OR jsonb_typeof(v_top)<>'number' THEN
    RAISE EXCEPTION 'Invalid mystery bounty percentage type' USING ERRCODE='22023';
  END IF;
  IF (v_pool#>>'{}')::numeric<0 OR (v_pool#>>'{}')::numeric>100
     OR trunc((v_pool#>>'{}')::numeric*100)<>(v_pool#>>'{}')::numeric*100
     OR (v_top#>>'{}')::numeric<=0 OR (v_top#>>'{}')::numeric>100 THEN
    RAISE EXCEPTION 'Invalid mystery bounty percentage range' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('mystery_bounty_profile',v_profile,
    'mystery_bounty_activation',v_activation,'mystery_bounty_activation_value',v_value,
    'mystery_bounty_pool_percent',v_pool,'mystery_bounty_regular_pool_percent',100-(v_pool#>>'{}')::numeric,
    'mystery_bounty_top_percent',v_top);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_player_home_club(p_user_id uuid, p_club_hint uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_club uuid;
BEGIN
  IF p_user_id IS NULL THEN RETURN NULL; END IF;
  IF p_club_hint IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.user_id = p_user_id AND cm.club_id = p_club_hint
       AND cm.status IN ('active','approved')
  ) THEN RETURN p_club_hint; END IF;
  SELECT cm.club_id INTO v_club
    FROM public.club_members cm
   WHERE cm.user_id = p_user_id AND cm.status IN ('active','approved')
   ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
   LIMIT 1;
  RETURN v_club;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_poker_arena_context(p_club_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_club public.clubs%ROWTYPE; v_role text; v_member boolean;
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_uid) THEN
    RAISE EXCEPTION 'Authentication Required' USING ERRCODE = '28000';
  END IF;
  SELECT c.* INTO v_club FROM public.clubs c
  WHERE c.id::text = btrim(p_club_key) OR c.club_id::text = btrim(p_club_key)
     OR lower(c.slug) = lower(btrim(p_club_key))
  ORDER BY (c.id::text = btrim(p_club_key)) DESC LIMIT 1;
  IF NOT FOUND OR v_club.lifecycle_status = 'retired' THEN RETURN NULL; END IF;
  IF v_club.asset = 'diamonds' THEN
    IF v_club.is_platform IS DISTINCT FROM true OR v_club.union_id IS NOT NULL
       OR NOT EXISTS (SELECT 1 FROM public.ca_arena_settings WHERE club_id = v_club.id) THEN
      RAISE EXCEPTION 'Invalid Diamond Arena Identity' USING ERRCODE = '23514';
    END IF;
    v_member := true; v_role := 'player';
  ELSIF v_club.asset = 'chips' AND v_club.is_platform = false THEN
    SELECT m.role INTO v_role FROM public.club_members m
      WHERE m.club_id = v_club.id AND m.user_id = v_uid AND m.status IN ('active','approved');
    v_member := FOUND;
  ELSE RAISE EXCEPTION 'Invalid Arena Asset' USING ERRCODE = '23514';
  END IF;
  RETURN jsonb_build_object('arena',jsonb_build_object('id',v_club.id,'asset',v_club.asset,
    'is_platform',v_club.is_platform,'union_id',v_club.union_id), 'member',v_member,'role',v_role,
    'cashGamesEnabled',v_club.asset='diamonds' AND COALESCE(
      (SELECT s.cash_games_enabled FROM public.ca_arena_settings s WHERE s.club_id=v_club.id),false),
    -- DIAMOND PHASE 8: the tournament switch, read the same way.
    'tournamentsEnabled',v_club.asset='diamonds' AND COALESCE(
      (SELECT s.tournaments_enabled FROM public.ca_arena_settings s WHERE s.club_id=v_club.id),false));
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_bind_diamond_seat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_count integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
     WHERE t.id=NEW.table_id AND c.asset='diamonds') THEN RETURN NULL; END IF;
 /* A TOURNAMENT ENTRY BINDS ITS CUSTODY TO THE ENTRY, NEVER TO A SEAT. That
    is what lets one entry survive a table move, a balance and a re-seat: there
    is nothing seat-shaped on the row to re-point. Seating asserts the entry and
    touches no custody at all. */
 IF (SELECT t.tournament_id FROM public.tables t WHERE t.id=NEW.table_id) IS NOT NULL THEN
   IF NOT EXISTS (
     SELECT 1 FROM public.tables t
       JOIN public.poker_diamond_custody c ON c.target_id=t.tournament_id
        AND c.user_id=NEW.user_id AND c.arena_id=t.club_id
        AND c.purpose='tournament_entry' AND c.state='active' AND c.seat_id IS NULL
     WHERE t.id=NEW.table_id
   ) THEN
     RAISE EXCEPTION 'Diamond Tournament Seat Requires A Funded Entry' USING ERRCODE='P0810';
   END IF;
   RETURN NULL;
 END IF;
 UPDATE public.poker_diamond_custody
   SET seat_id=NEW.id,seat_joined_at=NEW.joined_at,occupancy_id=NEW.occupancy_id,state='active'
   WHERE user_id=NEW.user_id AND target_id=NEW.table_id AND purpose='cash_seat'
     AND entry_key='seat:'||NEW.id AND state='reserved' AND balance=NEW.stack AND seat_id IS NULL;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 IF v_count<>1 THEN
   RAISE EXCEPTION 'diamond_seat_custody_binding_failed' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_audit_tournament_created(p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  v_id := NULLIF(p_result ->> 'tournamentId', '')::uuid;
  IF v_id IS NULL OR NOT public.fn_poker_diamond_tournament(v_id) THEN
    RAISE EXCEPTION 'diamond_tournament_would_not_be_recognised' USING ERRCODE='23514';
  END IF;
  PERFORM public.fn_poker_diamond_staff_audit('diamond.tournament_create', 'diamond_tournament', v_id, NULL,
    (SELECT to_jsonb(t) FROM public.tournaments t WHERE t.id = v_id),
    jsonb_build_object('door', 'fn_poker_diamond_create_tournament', 'table_id', p_result -> 'table_id'));
  RETURN p_result;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_create_spin(p_config jsonb, p_arena uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_key text; v_total numeric; v_buy_in bigint; v_chips numeric; v_game text; v_name text; v_start timestamptz;
  v_blinds jsonb; v_tiers jsonb; v_contract jsonb; v_manifest jsonb; v_sha text;
  v_source public.poker_diamond_spin_reserve_source%ROWTYPE; v_held numeric;
  v_worst bigint; v_cover bigint; v_id uuid; v_table uuid; v_sb numeric; v_bb numeric;
BEGIN
  -- Only the creation door reaches this, after it proved a signed-in platform
  -- operator and found the arena; both are proved again here.
  IF v_actor IS NULL OR NOT public.fn_is_platform_admin() THEN
    RAISE EXCEPTION 'diamond_tournament_staff_only' USING ERRCODE='42501';
  END IF;
  IF p_arena IS NULL OR NOT EXISTS (SELECT 1 FROM public.clubs c WHERE c.id=p_arena
       AND c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL) THEN
    RAISE EXCEPTION 'diamond_arena_not_found' USING ERRCODE='P0002';
  END IF;
  IF p_config IS NULL OR jsonb_typeof(p_config) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_configuration' USING ERRCODE='22023';
  END IF;

  -- The chip seat-first door refuses a configured multiplier: it is drawn.
  IF p_config ?| ARRAY['spinMultiplier','spinLockedTiers','spin_multiplier','spin_locked_tiers'] THEN
    RAISE EXCEPTION 'diamond_spin_multiplier_is_drawn_not_configured' USING ERRCODE='22023';
  END IF;
  -- And it refuses a key it would not keep. A Spin is priced by its buy-in,
  -- fielded by three seats and paid by its drawn ladder: a fee, a bounty, a
  -- rebuy, a guarantee or a ladder of its own means nothing here.
  FOR v_key IN SELECT jsonb_object_keys(p_config) LOOP
    IF v_key NOT IN ('type','name','gameVariant','buyIn','startingStack','blindStructure','spinTiers',
                     'startTime','maxPlayers','minPlayers','tableSize') THEN
      RAISE EXCEPTION 'diamond_spin_rejects_a_non_spin_configuration: %', v_key USING ERRCODE='22023';
    END IF;
  END LOOP;
  IF (p_config ? 'maxPlayers' AND (p_config->>'maxPlayers') IS DISTINCT FROM '3')
     OR (p_config ? 'minPlayers' AND (p_config->>'minPlayers') IS DISTINCT FROM '3')
     OR (p_config ? 'tableSize' AND (p_config->>'tableSize') IS DISTINCT FROM '3') THEN
    RAISE EXCEPTION 'diamond_spin_is_three_handed' USING ERRCODE='22023';
  END IF;
  -- A Spin runs only on NLH, PLO4, PLO5 or PLO6: the chip creation door's rule
  -- (unsupported_spin_variant) and the creation forms' (tournamentCreationRules).
  v_game := upper(btrim(COALESCE(p_config->>'gameVariant','NLH')));
  IF v_game NOT IN ('NLH','PLO4','PLO5','PLO6') THEN
    RAISE EXCEPTION 'diamond_spin_unsupported_variant' USING ERRCODE='22023';
  END IF;
  -- The buy-in is the whole charge; no fee rides on top. The table's
  -- expectation is where the edge lives (E[m] = 3 x (1 - rake)).
  BEGIN
    v_total := (p_config->>'buyIn')::numeric;
  EXCEPTION WHEN OTHERS THEN
    v_total := NULL;
  END;
  IF v_total IS NULL OR v_total <> trunc(v_total) OR v_total < 1 OR v_total > 2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_positive_buy_in' USING ERRCODE='22023';
  END IF;
  v_buy_in := v_total::bigint;
  -- The stack is part of the contract the draw receipt carries; the chip
  -- seat-first door requires it, and so does this one.
  BEGIN
    v_chips := (p_config->>'startingStack')::numeric;
  EXCEPTION WHEN OTHERS THEN
    v_chips := NULL;
  END;
  IF v_chips IS NULL OR v_chips <> trunc(v_chips) OR v_chips < 1 OR v_chips > 2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_starting_stack' USING ERRCODE='22023';
  END IF;
  v_blinds := p_config->'blindStructure';
  -- The multiplier table staff configured, or the published one (spin_tier_spec
  -- with the estate ladders), which is the approved chip table. Either is held
  -- to the same rule at this buy-in; none is invented here.
  v_tiers := p_config->'spinTiers';
  IF v_tiers IS NULL OR jsonb_typeof(v_tiers) = 'null' THEN
    SELECT jsonb_agg(jsonb_build_object('multiplier', s.multiplier, 'freq', s.freq,
                                        'reserveThresholdX', s.reserve_threshold_x) ORDER BY s.multiplier)
      INTO v_tiers FROM public.spin_tier_spec s;
  END IF;
  v_contract := public.fn_poker_diamond_spin_contract(v_buy_in, v_chips::integer, v_tiers, v_blinds);
  v_manifest := v_contract->'manifest';
  v_worst := (v_contract->>'worst_excess')::bigint;
  v_cover := (v_contract->>'required_cover')::bigint;

  -- The reserve: an authorized source, the cap it was authorized with, and a
  -- balance that covers the whole table now (the draw proves the cover again).
  SELECT * INTO v_source FROM public.poker_diamond_spin_reserve_source WHERE id = 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'diamond_spin_reserve_source_not_authorized' USING ERRCODE='55000';
  END IF;
  IF v_worst > v_source.max_underwrite_per_spin THEN
    RAISE EXCEPTION 'diamond_spin_reserve_over_its_authorized_cap: this table can ask the source for % Diamonds at a buy-in of %; % are authorized per Spin',
      v_worst, v_buy_in, v_source.max_underwrite_per_spin USING ERRCODE='55000';
  END IF;
  SELECT COALESCE(h.balance, 0) INTO v_held FROM public.ca_diamond_house h WHERE h.id = 1;
  IF COALESCE(v_held, 0) < v_cover THEN
    RAISE EXCEPTION 'diamond_spin_reserve_cannot_cover_the_table: the source holds %, the table needs % at a buy-in of %',
      COALESCE(v_held, 0), v_cover, v_buy_in USING ERRCODE='55000';
  END IF;

  v_name := COALESCE(NULLIF(btrim(p_config->>'name'),''),'Diamond Spin');
  BEGIN
    v_start := COALESCE((p_config->>'startTime')::timestamptz, now() + interval '1 minute');
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_start_time' USING ERRCODE='22023';
  END;
  v_sb := (v_blinds->0->>'smallBlind')::numeric;
  v_bb := (v_blinds->0->>'bigBlind')::numeric;

  -- The listing, as the chip seat-first creator writes a Spin: three seats,
  -- no fee, no late registration, undrawn (no multiplier, no pool), and the
  -- smallest ladder until the draw stamps the drawn one.
  INSERT INTO public.tournaments (
    club_id, union_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, guaranteed_prize, starting_chips, max_players, table_size, min_players,
    current_players, status, blind_structure, payout_structure, start_time,
    late_reg_levels, late_reg_mins, is_bounty, is_pko, is_mystery_bounty, bounty_amount,
    is_rebuy, is_reentry, add_on_available, free_buy, is_private, action_time_seconds)
  VALUES (
    p_arena, NULL, v_name, v_game, 'spin', 'SPIN',
    v_buy_in, 0, 0, v_chips::integer, 3, 3, 3,
    0, 'REGISTERING', v_blinds::text, '[{"place":1,"percentage":100}]', v_start,
    0, 0, false, false, false, 0,
    false, false, false, false, false, 15)
  RETURNING id INTO v_id;

  v_sha := encode(extensions.digest(v_manifest::text, 'sha256'), 'hex');
  INSERT INTO public.poker_diamond_spin_contracts
    (tournament_id, buy_in, starting_chips, rake_rate, rule_manifest, rule_sha256, worst_excess, required_cover, created_by)
  VALUES (v_id, v_buy_in, v_chips::integer, (v_manifest->>'rake_rate')::numeric, v_manifest, v_sha, v_worst, v_cover, v_actor);

  -- Its joinable table, in the same transaction, as the chip creator opens it.
  INSERT INTO public.tables (
    club_id, tournament_id, name, game_type, game_variant, stakes,
    small_blind, big_blind, min_buy_in, max_buy_in, max_players, current_players, status)
  VALUES (
    p_arena, v_id, v_name, 'tournament', lower(v_game), v_sb::text || '/' || v_bb::text,
    v_sb, v_bb, 0, 0, 3, 0, 'waiting')
  RETURNING id INTO v_table;

  -- The row this door wrote must be one the money path prices in Diamonds and
  -- the seat door sells as a Spin.
  IF public.fn_ca_tournament_unit_cents(v_id) <> 100 OR NOT public.fn_poker_diamond_tournament(v_id)
     OR public.fn_ca_tournament_recorded_format(v_id) IS DISTINCT FROM 'spin-v1'
     OR NOT public.fn_ca_tournament_recorded_seat_first(v_id, false) THEN
    RAISE EXCEPTION 'diamond_tournament_would_not_be_recognised' USING ERRCODE='23514';
  END IF;
  RETURN jsonb_build_object('success',true,'tournamentId',v_id,'id',v_id,'table_id',v_table,
    'buy_in_amount',v_buy_in,'buy_in_fee',0,'total',v_buy_in,'bounty_amount',0,'is_mystery_bounty',false,
    'asset','diamonds','format','spin','rule_sha256',v_sha,'multiplier_table',v_manifest->'tiers',
    'max_multiplier',(SELECT max((x->>'multiplier')::numeric) FROM jsonb_array_elements(v_manifest->'tiers') x),
    'worst_excess',v_worst,'required_cover',v_cover);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_create_tournament(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='28000'; END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RAISE EXCEPTION 'diamond_tournament_staff_only' USING ERRCODE='42501';
  END IF;
  -- DIAMOND PHASE 11: a signed-out staff token moves nothing here either.
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'diamond_staff_session_required' USING ERRCODE='28000';
  END IF;
  -- DIAMOND PHASE 10: the answer files its audit row on the way out.
  RETURN public.fn_poker_diamond_audit_tournament_created(
    public.fn_poker_diamond_create_tournament_core(p_config, jsonb_build_object('door', 'admin')));
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_create_tournament_core(p_config jsonb, p_authority jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_arena uuid; v_id uuid;
  v_total bigint; v_fee bigint; v_buy_in bigint; v_ratio numeric;
  v_max integer; v_min integer; v_type text; v_variant text; v_game text;
  v_start timestamptz; v_payouts jsonb; v_blinds jsonb; v_pct numeric; v_chips integer;
  v_rebuy boolean; v_reentry boolean; v_addon boolean; v_rebuy_cost bigint; v_addon_cost bigint;
  v_rebuy_num numeric; v_addon_num numeric; v_name text;
  v_is_bounty boolean; v_bounty_num numeric; v_bounty bigint;
  v_mystery boolean; v_mb_activation text; v_mb_profile text; v_mb_value numeric; v_mb_top numeric;
  v_mb_pool numeric; v_mb_regular numeric; v_mb_min_mult numeric; v_mb_max_mult numeric;
  v_unlimited boolean;
  v_satellite boolean; v_target_text text; v_target_id uuid; v_target public.tournaments%ROWTYPE;
  -- 2026-10-06: the two doors this core serves, and what Midway's board needs.
  v_cfg jsonb := p_config;
  v_door text := COALESCE(p_authority->>'door','');
  v_schedule uuid := NULLIF(p_authority->>'schedule_id','')::uuid;
  v_key text; v_from text; v_to text;
  v_guar_num numeric; v_guarantee bigint := 0;
  v_seats_num numeric; v_seats integer := 0; v_seat_guarantee bigint := 0; v_effective bigint := 0;
  v_freeroll boolean := false;
  v_rebuy_chips integer; v_addon_chips integer; v_rebuy_levels integer; v_addon_levels integer;
  v_max_rebuys integer; v_max_reentries integer; v_action_seconds integer := 15;
BEGIN
  -- 2026-10-06: TWO DOORS, ONE RULE BOOK. The staff door (a signed-in platform
  -- admin with a live session, exactly as before) and the scheduled door (the
  -- service role spawning a tournament_schedules row seeded under Dan's ruling
  -- of 2026-10-06). Every validation below runs for both.
  IF v_door = 'admin' THEN
    IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='28000'; END IF;
    IF NOT public.fn_is_platform_admin() THEN
      RAISE EXCEPTION 'diamond_tournament_staff_only' USING ERRCODE='42501';
    END IF;
    -- DIAMOND PHASE 11: a signed-out staff token moves nothing here either.
    IF NOT public.fn_caller_session_is_live() THEN
      RAISE EXCEPTION 'diamond_staff_session_required' USING ERRCODE='28000';
    END IF;
  ELSIF v_door = 'schedule' THEN
    IF v_schedule IS NULL OR NULLIF(p_authority->>'scheduled_start','') IS NULL
       OR COALESCE(auth.role(),'') <> 'service_role' THEN
      RAISE EXCEPTION 'diamond_schedule_authority_incomplete' USING ERRCODE='42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'diamond_tournament_unknown_door' USING ERRCODE='42501';
  END IF;
  SELECT c.id INTO v_arena FROM public.clubs c
   WHERE c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL LIMIT 1;
  IF v_arena IS NULL THEN RAISE EXCEPTION 'diamond_arena_not_found' USING ERRCODE='P0002'; END IF;
  IF v_cfg IS NULL OR jsonb_typeof(v_cfg)<>'object' THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_configuration' USING ERRCODE='22023';
  END IF;
  -- DIAMOND PHASE 9, STEP 0 (the_chip_legs_refuse_a_diamond_row): the estate's builder
  -- (TournamentService.buildRpcConfig) sends these money keys, and this door reads
  -- guarantee, rebuy, reentry, addOn and addonCost instead. A value in one of them
  -- would be dropped and the event created without it, so it is refused by name.
  -- The builder's own default (0, false or null) means what the door does without
  -- the key, and is admitted.
  IF EXISTS (SELECT 1 FROM jsonb_each(v_cfg) k
              WHERE k.key IN ('addOnFromStart')
                AND k.value NOT IN ('0'::jsonb, 'false'::jsonb, 'null'::jsonb)) THEN
    RAISE EXCEPTION 'diamond_tournament_money_key_not_read: %', (
      SELECT string_agg(k.key, ', ' ORDER BY k.key) FROM jsonb_each(v_cfg) k
       WHERE k.key IN ('addOnFromStart')
         AND k.value NOT IN ('0'::jsonb, 'false'::jsonb, 'null'::jsonb))
      USING ERRCODE = '22023';
  END IF;
  -- 2026-10-06: THE BUILDER'S MONEY KEYS ARE READ, NOT REFUSED. Midway's
  -- schedule configs (and TournamentService.buildRpcConfig) spell the guarantee
  -- guaranteedPrize and the rebuy and add-on isRebuy, isReentry, addOnAvailable
  -- and addOnCost. Each is folded onto the key this door has always read; the
  -- two spellings of one key may not disagree.
  FOR v_key IN SELECT unnest(ARRAY['guaranteedPrize>guarantee','isRebuy>rebuy','isReentry>reentry',
                                   'addOnAvailable>addOn','addOnCost>addonCost'])
  LOOP
    v_from := split_part(v_key,'>',1); v_to := split_part(v_key,'>',2);
    IF v_cfg ? v_from AND v_cfg->v_from <> 'null'::jsonb THEN
      IF v_cfg ? v_to AND v_cfg->v_to <> 'null'::jsonb AND v_cfg->v_to <> v_cfg->v_from THEN
        RAISE EXCEPTION 'diamond_tournament_money_keys_disagree:%/%', v_from, v_to USING ERRCODE='22023';
      END IF;
      v_cfg := jsonb_set(v_cfg - v_from, ARRAY[v_to], v_cfg->v_from);
    ELSE
      v_cfg := v_cfg - v_from;
    END IF;
  END LOOP;

  v_type := lower(COALESCE(v_cfg->>'type','mtt'));
  -- DIAMOND PHASE 9: A SPIN IS ADMITTED BY ITS OWN BRANCH, under the chip
  -- seat-first configuration door's rules (fn_poker_diamond_create_spin:
  -- three seats, no fee, a multiplier that is drawn and never configured, a
  -- multiplier table held to the draw authority's rules and to whole Diamonds
  -- at its buy-in). A Spin's configuration on any other format is refused.
  IF v_type = 'spin' THEN
    -- DIAMOND PHASE 10: the answer files its audit row on the way out.
    IF v_door <> 'admin' THEN
      RAISE EXCEPTION 'diamond_schedule_cannot_create_a_spin' USING ERRCODE='55000';
    END IF;
    RETURN public.fn_poker_diamond_create_spin(v_cfg, v_arena);
  END IF;
  IF v_cfg ?| ARRAY['spinTiers','spinMultiplier','spinLockedTiers','spin_multiplier','spin_locked_tiers'] THEN
    RAISE EXCEPTION 'diamond_tournament_spin_requires_a_spin_format' USING ERRCODE='22023';
  END IF;
  IF v_type NOT IN ('mtt','sng','bounty','progressive_bounty','mystery_bounty','satellite') THEN
    -- spin is admitted above, by fn_poker_diamond_create_spin.
    RAISE EXCEPTION 'diamond_tournament_format_not_open' USING ERRCODE='55000';
  END IF;
  -- A FREE BUY IS THE FREEROLL FORMAT (2026-10-09): admitted on a zero-entry
  -- event, where every freeroll check below still applies; a paid event that
  -- says freeBuy is refused as before.
  IF COALESCE((v_cfg->>'freeBuy')::boolean,false)
     AND COALESCE(NULLIF(v_cfg->>'buyIn','')::numeric,0) <> 0 THEN
    RAISE EXCEPTION 'diamond_tournament_format_not_open' USING ERRCODE='55000';
  END IF;
  -- 2026-10-06: A GUARANTEE IS SET ASIDE ON THE HOUSE AT CREATION (A1, A7).
  -- Whole Diamonds; the earmark ledger's guard applies A4 and A5 and the
  -- house's available balance when the earmark is opened below.
  v_guar_num := COALESCE(NULLIF(v_cfg->>'guarantee','')::numeric,0);
  IF v_guar_num <> trunc(v_guar_num) OR v_guar_num < 0 OR v_guar_num > 2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_guarantee' USING ERRCODE='22023';
  END IF;
  v_guarantee := v_guar_num;
  -- A satellite is a format, not a flag: its target rides on a 'satellite'
  -- event and on nothing else, and a satellite has exactly one target.
  v_satellite := v_type = 'satellite';
  v_target_text := NULLIF(btrim(COALESCE(v_cfg->>'satelliteTargetId','')),'');
  IF v_target_text IS NOT NULL AND NOT v_satellite THEN
    RAISE EXCEPTION 'diamond_tournament_target_requires_a_satellite_format' USING ERRCODE='22023';
  END IF;
  IF v_satellite THEN
    IF v_target_text IS NULL
       OR v_target_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'diamond_satellite_requires_a_target' USING ERRCODE='22023';
    END IF;
    v_target_id := v_target_text::uuid;
    -- ASSETS NEVER CROSS: a Diamond satellite seats a Diamond target only.
    IF NOT public.fn_poker_diamond_tournament(v_target_id) THEN
      RAISE EXCEPTION 'diamond_satellite_target_must_be_a_diamond_tournament' USING ERRCODE='22023';
    END IF;
    IF NOT public.fn_ca_diamond_satellite_target_accepts_new_feeder(v_target_id) THEN
      RAISE EXCEPTION 'diamond_satellite_target_cannot_take_a_satellite' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_target FROM public.tournaments t WHERE t.id=v_target_id;
    IF upper(COALESCE(v_target.status,'')) NOT IN ('ANNOUNCED','REGISTERING')
       OR COALESCE(v_target.prize_pool_finalized,false) THEN
      RAISE EXCEPTION 'diamond_satellite_target_is_not_open' USING ERRCODE='55000';
    END IF;
    -- A seat count promised in advance is a guarantee: reserved to the owner.
    -- 2026-10-06: A SEAT COUNT PROMISED IN ADVANCE IS A GUARANTEE, and it is
    -- set aside on the house like one: seats x the target's whole ticket.
    v_seats_num := COALESCE(NULLIF(v_cfg->>'satelliteSeats','')::numeric,0);
    IF v_seats_num <> trunc(v_seats_num) OR v_seats_num < 0 OR v_seats_num > 10000 THEN
      RAISE EXCEPTION 'diamond_satellite_requires_whole_seats' USING ERRCODE='22023';
    END IF;
    v_seats := v_seats_num;
    v_seat_guarantee := v_seats::bigint * (COALESCE(v_target.buy_in_amount,0) + COALESCE(v_target.buy_in_fee,0))::bigint;
    -- The chip scheduled satellite is a freezeout; so is this one.
    IF COALESCE((v_cfg->>'rebuy')::boolean,false) OR COALESCE((v_cfg->>'reentry')::boolean,false)
       OR COALESCE((v_cfg->>'addOn')::boolean,false) THEN
      RAISE EXCEPTION 'diamond_satellite_is_a_freezeout' USING ERRCODE='22023';
    END IF;
  END IF;
  -- A knockout bounty is a format, not a flag: the flat bounty rides on a
  -- 'bounty', 'progressive_bounty' or 'mystery_bounty' event and on nothing else.
  v_is_bounty := v_type IN ('bounty','progressive_bounty','mystery_bounty');
  v_mystery := v_type = 'mystery_bounty';
  v_bounty_num := COALESCE((v_cfg->>'bountyAmount')::numeric,0);
  IF NOT v_is_bounty AND (v_bounty_num<>0 OR COALESCE((v_cfg->>'isBounty')::boolean,false)) THEN
    RAISE EXCEPTION 'diamond_tournament_bounty_requires_a_bounty_format' USING ERRCODE='22023';
  END IF;
  IF NOT v_mystery AND (v_cfg ? 'mysteryBountyMin' OR v_cfg ? 'mysteryBountyMax' OR v_cfg ? 'mysteryBounty') THEN
    RAISE EXCEPTION 'diamond_tournament_mystery_requires_a_mystery_format' USING ERRCODE='22023';
  END IF;
  v_game := upper(btrim(COALESCE(v_cfg->>'gameVariant','NLH')));
  -- 2026-10-06: the schedule spellings the engine's GAME_TYPE_MAP already reads.
  v_game := CASE v_game WHEN 'PLO' THEN 'PLO4' WHEN 'SHORTDECK' THEN 'SHORT_DECK' ELSE v_game END;
  IF v_game NOT IN ('NLH','PLO4','PLO5','PLO6','PLO8','SHORT_DECK','FLH','FLO8') THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_supported_game' USING ERRCODE='22023';
  END IF;

  v_total := COALESCE((v_cfg->>'buyIn')::numeric,0);
  IF (v_cfg->>'buyIn')::numeric IS DISTINCT FROM v_total::numeric OR v_total<0 OR v_total>2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_positive_buy_in' USING ERRCODE='22023';
  END IF;
  -- 2026-10-06: A FREEROLL (A10, A11). Zero to enter, a plain MTT, its prize
  -- the guarantee set aside on the house, and rebuys and add-ons at one Diamond
  -- each wholly to the prize pool, as Midway runs its own (Dan, 2026-10-06:
  -- "USE THE SAME TOURNAMENT SCHEDULE AND RAKE AS THE MIDWAY UNION FOR NOW").
  v_freeroll := v_total = 0;
  IF v_freeroll THEN
    IF v_type <> 'mtt' THEN
      RAISE EXCEPTION 'diamond_freeroll_must_be_a_plain_mtt' USING ERRCODE='22023';
    END IF;
    IF v_guarantee < 1 THEN
      RAISE EXCEPTION 'diamond_freeroll_requires_a_guarantee' USING ERRCODE='22023';
    END IF;
    IF NOT public.fn_ca_diamond_economic_on('freeroll_allowed') THEN
      RAISE EXCEPTION 'diamond_freeroll_not_open' USING ERRCODE='55000';
    END IF;
    IF public.fn_ca_diamond_economic_text('freeroll_rebuy_cost') IS DISTINCT FROM 'one_hundred_diamonds_to_the_prize_pool'
       OR public.fn_ca_diamond_economic_text('freeroll_addon_cost') IS DISTINCT FROM 'one_hundred_diamonds_to_the_prize_pool' THEN
      RAISE EXCEPTION 'diamond_freeroll_rebuy_and_addon_are_not_offered' USING ERRCODE='55000';
    END IF;
  END IF;
  v_unlimited:=public.fn_ca_new_tournament_is_unlimited(jsonb_build_object('tournament_type',
    CASE WHEN v_type='sng' THEN 'SNG' WHEN v_satellite THEN 'SATELLITE' ELSE 'MTT' END));
  v_max := CASE WHEN v_unlimited THEN NULL ELSE COALESCE((v_cfg->>'maxPlayers')::int,0) END;
  IF NOT v_unlimited AND (v_max<2 OR v_max>10000) THEN RAISE EXCEPTION 'diamond_tournament_requires_a_real_field' USING ERRCODE='22023'; END IF;
  v_min := GREATEST(COALESCE((v_cfg->>'minPlayers')::int,3),CASE WHEN v_unlimited THEN 3 ELSE 2 END);
  IF NOT v_unlimited AND v_min>v_max THEN v_min := v_max; END IF;
  -- The fee rule the recovery fee already states, at this entry's own unit.
  v_ratio := CASE WHEN NOT v_unlimited AND v_max<=2 THEN 0.05 ELSE 0.10 END;
  v_fee := public.fn_ca_unit_floor_cents(round(v_total*100*v_ratio)::bigint, 100)/100;
  v_buy_in := v_total - v_fee;
  IF v_buy_in<1 AND NOT v_freeroll THEN RAISE EXCEPTION 'diamond_tournament_buy_in_below_one_diamond' USING ERRCODE='22023'; END IF;
  -- The chip door's bounty rule at the Diamond unit: a whole bounty of at
  -- least one Diamond, no larger than the buy-in after the fee (the prize
  -- part is what remains; it may be zero, as the chip split allows).
  -- 2026-10-06: a scheduled bounty that is not a whole Diamond (Midway's 2.5,
  -- 6.75) is rounded DOWN; the remainder stays in the prize part of the entry.
  IF v_door = 'schedule' THEN
    v_bounty_num := trunc(v_bounty_num);
  END IF;
  IF v_is_bounty THEN
    IF v_bounty_num<>trunc(v_bounty_num) OR v_bounty_num<1 OR v_bounty_num>v_buy_in THEN
      RAISE EXCEPTION 'diamond_tournament_requires_a_whole_bounty_within_the_buy_in' USING ERRCODE='22023';
    END IF;
    v_bounty := v_bounty_num;
  ELSE
    v_bounty := 0;
  END IF;
  -- The mystery rules are the chip configuration door's rules
  -- (fn_apply_mystery_bounty_config), stamped here because that door consults
  -- a club owner the arena does not have. The lobby's advertised range is the
  -- chip door's multipliers on the flat bounty, in whole Diamonds.
  IF v_mystery THEN
    v_mb_activation := COALESCE(v_cfg->'mysteryBounty'->>'activation', 'at_the_money');
    IF v_mb_activation NOT IN ('at_the_money','percent_field','player_count') THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_bad_activation_mode' USING ERRCODE='22023';
    END IF;
    v_mb_profile := COALESCE(v_cfg->'mysteryBounty'->>'profile', 'classic');
    IF v_mb_profile NOT IN ('balanced','classic','jackpot') THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_bad_profile' USING ERRCODE='22023';
    END IF;
    v_mb_value := (v_cfg->'mysteryBounty'->>'activationValue')::numeric;
    IF v_mb_activation = 'percent_field' AND (COALESCE(v_mb_value,0) <= 0 OR v_mb_value > 100) THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_activation_percent_out_of_range' USING ERRCODE='22023';
    END IF;
    IF v_mb_activation = 'player_count' AND COALESCE(v_mb_value,0) < 2 THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_activation_count_too_small' USING ERRCODE='22023';
    END IF;
    v_mb_top := COALESCE((v_cfg->'mysteryBounty'->>'topPercent')::numeric, 20);
    IF v_mb_top <= 0 OR v_mb_top > 100 THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_top_percent_out_of_range' USING ERRCODE='22023';
    END IF;
    v_mb_pool := COALESCE((v_cfg->'mysteryBounty'->>'poolPercent')::numeric, 50);
    v_mb_regular := COALESCE((v_cfg->'mysteryBounty'->>'regularPoolPercent')::numeric, 100 - v_mb_pool);
    IF v_mb_pool < 0 OR v_mb_regular < 0 OR v_mb_pool + v_mb_regular <= 0 THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_pool_split_invalid' USING ERRCODE='22023';
    END IF;
    v_mb_min_mult := COALESCE(NULLIF(v_cfg->>'mysteryBountyMin','')::numeric, 0.5);
    v_mb_max_mult := COALESCE(NULLIF(v_cfg->>'mysteryBountyMax','')::numeric, 13);
    IF v_mb_min_mult <= 0 OR v_mb_max_mult < v_mb_min_mult THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_range_invalid' USING ERRCODE='22023';
    END IF;
  END IF;

  v_chips := COALESCE((v_cfg->>'startingStack')::int, 10000);
  IF v_chips<1 THEN RAISE EXCEPTION 'diamond_tournament_requires_a_starting_stack' USING ERRCODE='22023'; END IF;
  v_blinds := COALESCE(v_cfg->'blindStructure','[]'::jsonb);
  v_payouts := COALESCE(v_cfg->'payoutStructure','[]'::jsonb);
  IF jsonb_typeof(v_blinds)<>'array' OR jsonb_array_length(v_blinds)=0 THEN
    RAISE EXCEPTION 'blind_structure_required' USING ERRCODE='22023';
  END IF;
  IF jsonb_typeof(v_payouts)<>'array' OR jsonb_array_length(v_payouts)=0 THEN
    RAISE EXCEPTION 'payout_structure_required' USING ERRCODE='22023';
  END IF;
  SELECT COALESCE(sum((e->>'percentage')::numeric),0) INTO v_pct FROM jsonb_array_elements(v_payouts) e;
  IF abs(v_pct-100)>1 THEN RAISE EXCEPTION 'payouts_must_total_100' USING ERRCODE='22023'; END IF;
  IF NOT v_unlimited AND jsonb_array_length(v_payouts)>v_max THEN RAISE EXCEPTION 'more_paid_places_than_players' USING ERRCODE='22023'; END IF;
  v_start := CASE WHEN v_door = 'schedule' THEN (p_authority->>'scheduled_start')::timestamptz
                  ELSE COALESCE((v_cfg->>'startTime')::timestamptz, now()+interval '1 minute') END;
  -- A satellite plays before its target, as the chip scheduled satellite does.
  IF v_satellite AND (v_target.start_time IS NULL OR v_start >= v_target.start_time) THEN
    RAISE EXCEPTION 'diamond_satellite_must_start_before_its_target' USING ERRCODE='22023';
  END IF;
  v_rebuy := COALESCE((v_cfg->>'rebuy')::boolean,false);
  v_reentry := COALESCE((v_cfg->>'reentry')::boolean,v_rebuy);
  v_addon := COALESCE((v_cfg->>'addOn')::boolean,false);
  v_rebuy_num := COALESCE((v_cfg->>'rebuyCost')::numeric, v_total);
  v_addon_num := COALESCE((v_cfg->>'addonCost')::numeric, v_total);
  IF (v_rebuy OR v_reentry) AND (v_rebuy_num <> trunc(v_rebuy_num) OR v_rebuy_num < 1 OR v_rebuy_num > 2147483647) THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_rebuy_cost' USING ERRCODE='22023';
  END IF;
  IF v_addon AND (v_addon_num <> trunc(v_addon_num) OR v_addon_num < 1 OR v_addon_num > 2147483647) THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_addon_cost' USING ERRCODE='22023';
  END IF;
  v_rebuy_cost := v_rebuy_num; v_addon_cost := v_addon_num;
  IF v_freeroll THEN
    IF (v_cfg ? 'rebuyCost' AND v_cfg->'rebuyCost' <> 'null'::jsonb AND v_rebuy_num <> 100)
       OR (v_cfg ? 'addonCost' AND v_cfg->'addonCost' <> 'null'::jsonb AND v_addon_num <> 100) THEN
      RAISE EXCEPTION 'diamond_freeroll_rebuy_and_addon_cost_one_hundred_diamonds' USING ERRCODE='22023';
    END IF;
    v_rebuy := true; v_reentry := COALESCE((v_cfg->>'reentry')::boolean, true); v_addon := true;
    v_rebuy_cost := 100; v_addon_cost := 100;
  END IF;
  -- The staff door's structure defaults are unchanged. The scheduled door reads
  -- Midway's own: the rebuy and add-on stacks and levels it configures, and no
  -- rebuy or re-entry limit unless one is set (the chip spawner's NULL).
  v_rebuy_chips := v_chips; v_addon_chips := v_chips; v_rebuy_levels := 6; v_addon_levels := 1;
  v_max_rebuys := COALESCE((v_cfg->>'maxRebuys')::int,2);
  v_max_reentries := COALESCE((v_cfg->>'maxReentries')::int,1);
  IF v_door = 'schedule' THEN
    v_rebuy_chips := COALESCE(NULLIF((v_cfg->>'rebuyChips')::int,0), v_chips);
    v_addon_chips := COALESCE(NULLIF(COALESCE(v_cfg->>'addOnChips', v_cfg->>'addonChips')::int,0), v_chips);
    v_rebuy_levels := COALESCE(NULLIF((v_cfg->>'rebuyLevels')::int,0), 6);
    v_addon_levels := COALESCE(NULLIF(COALESCE(v_cfg->>'addOnLevels', v_cfg->>'addonLevels')::int,0), 1);
    v_max_rebuys := (v_cfg->>'maxRebuys')::int;
    v_max_reentries := (v_cfg->>'maxReentries')::int;
    v_action_seconds := LEAST(60, GREATEST(5, COALESCE((v_cfg->>'actionTimeSeconds')::int, 15)));
    IF v_rebuy_chips < 1 OR v_addon_chips < 1 OR v_rebuy_levels < 1 OR v_addon_levels < 1
       OR COALESCE(v_max_rebuys,0) < 0 OR COALESCE(v_max_reentries,0) < 0 THEN
      RAISE EXCEPTION 'diamond_tournament_requires_a_real_rebuy_structure' USING ERRCODE='22023';
    END IF;
  END IF;

  -- THE GUARANTEE IS SET ASIDE BEFORE THE ROW EXISTS. The row's id is drawn
  -- first so the earmark can name it, and trg_tournaments_guarantee_affordable
  -- and the readiness contract find the earmark when the INSERT below runs.
  -- The earmark guard (fn_ca_diamond_earmark_guard) refuses by name a
  -- guarantee over A4, over A5, or over what the house has available.
  v_effective := GREATEST(v_guarantee, v_seat_guarantee);
  v_id := gen_random_uuid();
  IF v_effective > 0 THEN
    INSERT INTO public.ca_diamond_house_earmarks
      (entry, earmark_key, purpose, amount, tournament_id, recorded_by, reason)
    VALUES ('open', 'guarantee:' || v_id::text, 'guarantee', v_effective, v_id,
      CASE WHEN v_door = 'admin' THEN v_actor END,
      CASE WHEN v_door = 'schedule'
           THEN format('Scheduled guarantee set aside at creation: schedule %s at %s, a row seeded under Dan 2026-10-06 "USE THE SAME TOURNAMENT SCHEDULE AND RAKE AS THE MIDWAY UNION FOR NOW"',
                       v_schedule, p_authority->>'scheduled_start')
           ELSE format('Staff guarantee set aside at creation by platform admin %s', v_actor) END);
  END IF;
  v_name := COALESCE(NULLIF(btrim(v_cfg->>'name'),''),'Diamond Tournament');
  v_variant := CASE v_type WHEN 'sng' THEN 'sng' WHEN 'bounty' THEN 'bounty'
                           WHEN 'progressive_bounty' THEN 'progressive_bounty'
                           WHEN 'mystery_bounty' THEN 'mystery_bounty'
                           WHEN 'satellite' THEN 'satellite' ELSE 'freezeout' END;

  INSERT INTO public.tournaments (
    id, club_id, union_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, guaranteed_prize, starting_chips, max_players, table_size, min_players,
    current_players, status, blind_structure, payout_structure, start_time,
    late_reg_levels, late_reg_mins, is_bounty, is_pko, is_mystery_bounty, bounty_amount,
    mystery_bounty_min, mystery_bounty_max,
    mystery_bounty_activation, mystery_bounty_activation_value, mystery_bounty_profile,
    mystery_bounty_top_percent, mystery_bounty_pool_percent, mystery_bounty_regular_pool_percent,
    is_rebuy, is_reentry, rebuy_cost, rebuy_chips, rebuy_levels, max_rebuys, max_reentries,
    add_on_available, addon_cost, addon_chips, addon_levels,
    payout_percent, free_buy, is_private, action_time_seconds,
    satellite_target_id, satellite_seats,
    schedule_id, short_description, is_pinned, bubble_protection, final_table_deal_enabled, big_blind_ante)
  VALUES (
    v_id, v_arena, NULL, v_name, v_game, v_variant,
    CASE WHEN v_type='sng' THEN 'SNG' WHEN v_satellite THEN 'SATELLITE' ELSE 'MTT' END,
    v_buy_in, v_fee, v_guarantee, v_chips, v_max, CASE WHEN v_unlimited THEN LEAST(9,GREATEST(2,COALESCE((v_cfg->>'tableSize')::int,9))) ELSE LEAST(9,GREATEST(2,v_max)) END, v_min,
    0, 'REGISTERING', v_blinds::text, v_payouts::text, v_start,
    CASE WHEN v_satellite THEN 0 ELSE COALESCE((v_cfg->>'lateRegLevels')::int,
      CASE WHEN v_door='schedule' THEN (v_cfg->>'lateRegistrationLevels')::int END,
      CASE WHEN v_type='sng' THEN 0 ELSE 8 END) END,
    CASE WHEN v_satellite THEN 0 ELSE 8 END,
    v_is_bounty, v_type='progressive_bounty', v_mystery, v_bounty,
    CASE WHEN v_mystery THEN trunc(v_bounty * v_mb_min_mult) ELSE 0 END,
    CASE WHEN v_mystery THEN trunc(v_bounty * v_mb_max_mult) ELSE 0 END,
    CASE WHEN v_mystery THEN v_mb_activation ELSE 'at_the_money' END, CASE WHEN v_mystery THEN v_mb_value END,
    CASE WHEN v_mystery THEN v_mb_profile ELSE 'classic' END,
    CASE WHEN v_mystery THEN v_mb_top ELSE 20 END, CASE WHEN v_mystery THEN v_mb_pool ELSE 50 END,
    CASE WHEN v_mystery THEN v_mb_regular ELSE 50 END,
    v_rebuy, v_reentry, CASE WHEN v_rebuy OR v_reentry THEN v_rebuy_cost ELSE 0 END,
    CASE WHEN v_rebuy OR v_reentry THEN v_rebuy_chips ELSE 0 END, CASE WHEN v_rebuy OR v_reentry THEN v_rebuy_levels ELSE 4 END,
    CASE WHEN v_rebuy THEN v_max_rebuys ELSE 0 END,
    CASE WHEN v_reentry THEN v_max_reentries ELSE 0 END,
    v_addon, CASE WHEN v_addon THEN v_addon_cost ELSE 0 END, CASE WHEN v_addon THEN v_addon_chips ELSE 0 END, v_addon_levels,
    CASE WHEN (v_cfg->>'payoutPercent')::int IN (10,15,20) THEN (v_cfg->>'payoutPercent')::smallint ELSE 10 END,
    false, false, v_action_seconds,
    CASE WHEN v_satellite THEN v_target_id END, CASE WHEN v_satellite THEN v_seats END,
    v_schedule,
    CASE WHEN v_door='schedule' THEN NULLIF(btrim(COALESCE(v_cfg->>'shortDescription','')),'') END,
    v_door='schedule' AND COALESCE((v_cfg->>'isFeatured')::boolean,false),
    v_door='schedule' AND COALESCE((v_cfg->>'bubbleProtection')::boolean,false),
    v_door='schedule' AND COALESCE((v_cfg->>'finalTableDealEnabled')::boolean,false),
    v_door='schedule' AND COALESCE((v_cfg->>'bigBlindAnte')::boolean,false))
  RETURNING id INTO v_id;
  -- The guarantee the row carries is exactly what was set aside for it.
  IF public.fn_ca_diamond_earmark_open('guarantee:' || v_id::text) <> v_effective THEN
    RAISE EXCEPTION 'diamond_guarantee_earmark_does_not_match_the_row' USING ERRCODE='23514';
  END IF;

  -- The row this door wrote must be one the money path will price: whole
  -- Diamonds everywhere, and the unit rule must recognise it.
  IF public.fn_ca_tournament_unit_cents(v_id) <> 100 OR NOT public.fn_poker_diamond_tournament(v_id) THEN
    RAISE EXCEPTION 'diamond_tournament_would_not_be_recognised' USING ERRCODE='23514';
  END IF;
  -- The staff door files its audit row with this answer on the way out; the
  -- scheduled door files its receipt in ca_diamond_scheduled_spawns.
  RETURN jsonb_build_object('success',true,'tournamentId',v_id,
    'guaranteed_prize',v_guarantee,'guarantee_set_aside',v_effective,'freeroll',v_freeroll,
    'satellite_seats',CASE WHEN v_satellite THEN v_seats END,'schedule_id',v_schedule,'id',v_id,'buy_in_amount',v_buy_in,'buy_in_fee',v_fee,
    'total',v_total,'bounty_amount',v_bounty,'is_mystery_bounty',v_mystery,'asset','diamonds',
    'satellite_target_id',v_target_id,'satellite_ticket',
    CASE WHEN v_satellite THEN v_target.buy_in_amount + COALESCE(v_target.buy_in_fee,0) END);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_entry_custody_is_the_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moved bigint;
BEGIN
 -- OLD is only touched inside the UPDATE branch; a BEFORE/AFTER INSERT has none.
 IF TG_OP='UPDATE' THEN
   IF OLD.purpose='tournament_entry' OR NEW.purpose='tournament_entry' THEN
     IF NEW.user_id IS DISTINCT FROM OLD.user_id
        OR NEW.target_id IS DISTINCT FROM OLD.target_id
        OR NEW.arena_id IS DISTINCT FROM OLD.arena_id
        OR NEW.entry_key IS DISTINCT FROM OLD.entry_key
        OR NEW.purpose IS DISTINCT FROM OLD.purpose THEN
       RAISE EXCEPTION 'A Diamond Tournament Entry Is Fixed To The Player And Event It Paid For'
         USING ERRCODE='P0815';
     END IF;
   END IF;
 END IF;
 IF NEW.purpose <> 'tournament_entry' THEN RETURN NULL; END IF;

 IF NEW.seat_id IS NOT NULL OR NEW.seat_joined_at IS NOT NULL OR NEW.occupancy_id IS NOT NULL THEN
   RAISE EXCEPTION 'A Diamond Tournament Entry Never Binds To A Seat' USING ERRCODE='P0813';
 END IF;

 SELECT COALESCE(sum(CASE WHEN m.action='reserve' THEN m.amount ELSE -m.amount END),0)
   INTO v_moved FROM public.poker_diamond_movements m WHERE m.custody_id=NEW.id;
 IF NEW.balance IS DISTINCT FROM v_moved THEN
   RAISE EXCEPTION 'A Diamond Tournament Entry Holds Only What Was Reserved For It'
     USING ERRCODE='P0814';
 END IF;

 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_release(p_custody_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner uuid;
  v_c public.poker_diamond_custody%ROWTYPE;
  v_prev public.poker_diamond_movements%ROWTYPE;
  v_request jsonb;
  v_credit jsonb;
  v_receipt jsonb;
  v_lot record;
  v_debt_journal uuid;
BEGIN
  IF p_custody_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_diamond_release' USING ERRCODE = '22023';
  END IF;

  SELECT user_id INTO v_owner
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'diamond_custody_not_found';
  END IF;

  -- The wallet always locks before its custody, exactly as reserve does.
  PERFORM id FROM public.profiles WHERE id = v_owner FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;
  SELECT * INTO v_c
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id
   FOR UPDATE;

  v_request := jsonb_build_object(
    'action', 'release',
    'custody_id', p_custody_id,
    'user_id', v_owner
  );

  SELECT * INTO v_prev
    FROM public.poker_diamond_movements
   WHERE request_id = p_request_id;
  IF FOUND THEN
    IF v_prev.request <> v_request THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch';
    END IF;
    RETURN v_prev.receipt;
  END IF;

  IF v_c.state = 'released' THEN
    RAISE EXCEPTION 'diamond_custody_already_released';
  END IF;
  -- A DIAMOND TOURNAMENT ENTRY GOES HOME ONLY THROUGH ITS REFUND AUTHORITY
  -- (Phase 8). fn_poker_diamond_tournament_refund names this row in a
  -- transaction-local setting for the one call it makes; any other caller,
  -- service role included, is refused. An entry in play is never releasable.
  IF v_c.purpose = 'tournament_entry'
     AND current_setting('app.poker_diamond_tournament_release', true) IS DISTINCT FROM p_custody_id::text THEN
    RAISE EXCEPTION 'diamond_tournament_entry_requires_refund_authority' USING ERRCODE = '42501';
  END IF;
  -- An ACTIVE tournament entry (activated by the entry door, as the seat
  -- guards P0810-P0812 require) is released whole by its refund authority;
  -- the settlement test below is the cash seat's and stays the cash seat's.
  IF v_c.state <> 'reserved' AND v_c.purpose <> 'tournament_entry' THEN
    IF v_c.state <> 'active' OR v_c.purpose <> 'cash_seat'
       OR v_c.occupancy_id IS NULL OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_c.seat_id AND s.joined_at=v_c.seat_joined_at
            AND s.occupancy_id=v_c.occupancy_id AND s.user_id=v_c.user_id
            AND s.table_id=v_c.target_id AND s.left_at IS NOT NULL
            AND s.stack=v_c.balance) THEN
      RAISE EXCEPTION 'diamond_custody_requires_settlement';
    END IF;
  END IF;

  FOR v_lot IN
    SELECT l.id, r.amount-r.consumed AS amount
      FROM public.poker_diamond_lot_reservations r
      JOIN public.diamond_purchase_lots l ON l.id = r.lot_id
     WHERE r.custody_id = p_custody_id
       AND r.released_at IS NULL
     ORDER BY l.created_at, l.id
     FOR UPDATE OF l
  LOOP
    UPDATE public.diamond_purchase_lots
       SET arena_reserved = arena_reserved - v_lot.amount
     WHERE id = v_lot.id;
  END LOOP;

  UPDATE public.poker_diamond_lot_reservations
     SET released_at = now()
   WHERE custody_id = p_custody_id
     AND released_at IS NULL;

  IF v_c.balance > 0 THEN
  v_credit := public.add_diamonds_to_balance(
    v_owner,
    v_c.balance::integer,
    'arena_withdraw',
    'Released Poker Arena reservation',
    'poker-release:' || p_custody_id || ':' || p_request_id
  );
  IF (v_credit->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'diamond_release_credit_failed:%', v_credit->>'error';
  END IF;

  ELSE
    SELECT jsonb_build_object('success',true,'new_balance',diamonds,
      'debt_settled',0,'transaction_id',NULL) INTO v_credit
      FROM public.profiles WHERE id=v_owner;
  END IF;

  IF COALESCE((v_credit->>'debt_settled')::bigint, 0) > 0 THEN
    SELECT id INTO v_debt_journal
      FROM public.diamond_transactions
     WHERE user_id = v_owner
       AND reference_id = 'debt-settlement:' || (v_credit->>'transaction_id')
       AND type = 'debt_settlement'
       AND amount = -(v_credit->>'debt_settled')::bigint;
    IF v_debt_journal IS NULL THEN
      RAISE EXCEPTION 'diamond_debt_journal_missing';
    END IF;

    PERFORM public.fn_ca_register_diamond_journal_row(v_debt_journal);
    IF NOT EXISTS (
      SELECT 1
        FROM public.ca_mint_ledger
       WHERE diamond_tx_id = v_debt_journal
         AND action = 'burn'
         AND asset = 'diamonds'
         AND holder_type = 'player'
         AND holder_id = v_owner
         AND amount = (v_credit->>'debt_settled')::bigint
    ) THEN
      RAISE EXCEPTION 'diamond_debt_retirement_missing';
    END IF;
  END IF;

  UPDATE public.poker_diamond_custody
     SET balance = 0,
         state = 'released',
         released_at = now()
   WHERE id = p_custody_id;

  v_receipt := jsonb_build_object(
    'success', true,
    'custody_id', p_custody_id,
    'request_id', p_request_id,
    'amount', v_c.balance,
    'available_balance', (v_credit->>'new_balance')::bigint,
    'custody_balance', 0,
    'debt_settled', (v_credit->>'debt_settled')::bigint,
    'journal_id', v_credit->>'transaction_id'
  );

  INSERT INTO public.poker_diamond_movements(
    request_id, custody_id, user_id, action, amount,
    source_account, destination_account, wallet_journal_id, request, receipt
  ) VALUES (
    p_request_id, p_custody_id, v_owner, 'release', v_c.balance,
    'arena_custody:' || p_custody_id, 'player:' || v_owner,
    (v_credit->>'transaction_id')::uuid, v_request, v_receipt
  );

  RETURN v_receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_reserve(p_user_id uuid, p_purpose text, p_target_id uuid, p_entry_key text, p_amount numeric, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_request jsonb; v_previous public.poker_diamond_movements%ROWTYPE;
 v_wallet bigint; v_arena uuid; v_asset text; v_platform boolean; v_union uuid;
 v_min numeric; v_max numeric; v_status text; v_custody uuid; v_journal uuid;
 v_locked bigint; v_days integer; v_left bigint; v_take bigint; v_lot record; v_receipt jsonb;
BEGIN
 IF p_user_id IS NULL OR p_target_id IS NULL OR p_request_id IS NULL
    OR p_purpose IS NULL OR p_purpose NOT IN ('cash_seat','tournament_entry')
    OR p_entry_key IS NULL OR length(p_entry_key) NOT BETWEEN 1 AND 160
    OR p_amount IS NULL OR p_amount <= 0 OR p_amount > 2147483647 OR p_amount <> trunc(p_amount) THEN
   RAISE EXCEPTION 'invalid_diamond_reservation' USING ERRCODE = '22023';
 END IF;
 v_request := jsonb_build_object('user_id',p_user_id,'purpose',p_purpose,'target_id',p_target_id,
   'entry_key',p_entry_key,'amount',p_amount,'action','reserve');
 -- All operations for one wallet serialize on that profile, including shop spend/refunds.
 SELECT diamonds INTO v_wallet FROM public.profiles WHERE id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'profile_not_found'; END IF;
 SELECT * INTO v_previous FROM public.poker_diamond_movements WHERE request_id=p_request_id;
 IF FOUND THEN
   IF v_previous.request <> v_request THEN RAISE EXCEPTION 'idempotency_payload_mismatch'; END IF;
   RETURN v_previous.receipt;
 END IF;
 IF p_purpose='cash_seat' THEN
   SELECT t.club_id,t.min_buy_in,t.max_buy_in,t.status INTO v_arena,v_min,v_max,v_status
   FROM public.tables t WHERE t.id=p_target_id FOR SHARE;
   IF NOT FOUND OR v_min IS NULL OR v_max IS NULL OR p_amount<v_min OR p_amount>v_max THEN
     RAISE EXCEPTION 'invalid_diamond_table_buy_in';
   END IF;
 ELSE
   SELECT t.club_id,t.buy_in_amount+COALESCE(t.buy_in_fee,0),t.status
   INTO v_arena,v_min,v_status FROM public.tournaments t
     JOIN public.clubs c ON c.id=t.club_id
     JOIN public.ca_arena_settings a ON a.id=1 AND a.club_id=c.id
   WHERE t.id=p_target_id AND c.asset='diamonds' AND c.is_platform IS TRUE
     AND c.union_id IS NULL AND t.union_id IS NULL AND a.tournaments_enabled
   FOR SHARE OF t;
   IF NOT FOUND THEN
     RAISE EXCEPTION 'diamond_tournaments_not_open' USING ERRCODE='55000';
   END IF;
   IF v_min IS NULL OR p_amount<>v_min THEN RAISE EXCEPTION 'invalid_diamond_entry_price'; END IF; END IF;
 SELECT asset,is_platform,union_id INTO v_asset,v_platform,v_union FROM public.clubs WHERE id=v_arena FOR SHARE;
 IF v_asset IS DISTINCT FROM 'diamonds' OR v_platform IS DISTINCT FROM true OR v_union IS NOT NULL THEN
   RAISE EXCEPTION 'diamond_asset_required';
 END IF;
 IF v_status IS NULL OR v_status IN ('completed','cancelled','closed','archived') THEN
   RAISE EXCEPTION 'diamond_target_closed';
 END IF;
 SELECT settlement_window_days INTO v_days FROM public.ca_arena_settings WHERE id=1 AND club_id=v_arena;
 IF v_days IS NULL THEN RAISE EXCEPTION 'diamond_arena_policy_missing'; END IF;
 IF EXISTS(SELECT 1 FROM public.diamond_debts WHERE user_id=p_user_id AND settled_at IS NULL AND amount>0) THEN
   RAISE EXCEPTION 'diamond_debt_requires_settlement';
 END IF;
 -- Lock lots before evaluating age/freeze, so a concurrent dispute cannot slip through.
 PERFORM id FROM public.diamond_purchase_lots WHERE user_id=p_user_id ORDER BY created_at,id FOR UPDATE;
 SELECT COALESCE(sum(GREATEST(issued-consumed-refunded-arena_reserved,0)),0) INTO v_locked
 FROM public.diamond_purchase_lots WHERE user_id=p_user_id
 AND (frozen_at IS NOT NULL OR created_at>now()-make_interval(days=>v_days));
 IF v_wallet IS NULL OR v_wallet-v_locked<p_amount THEN
   -- RULING 14 / DR16. A lot frozen or younger than the settlement window is not depositable,
   -- and this door has refused it by this name since Phase 3. The rule mode is READ here so
   -- DR16 has a consumer and a flip means something (the DR15 shape, 20260908041432). The
   -- refusal stands in both modes: the lot reservation below draws only on settled lots, so
   -- an unsettled lot admitted here would sit in custody with nothing for a chargeback to
   -- find. Armed, the same refusal is raised under the rule's own code with the numbers in
   -- its DETAIL; a raise cannot file an incident that survives it (20260906102549), so the
   -- evidence rides in the error, where the Postgres log counts it. The leading token is
   -- what the engine and the client match on and does not change.
   IF v_locked>0 AND v_wallet IS NOT NULL AND v_wallet>=p_amount
      AND public.fn_ca_diamond_rule_mode('DR16:deposit_inside_settlement_window')='refuse' THEN
     RAISE EXCEPTION 'insufficient_settled_diamonds' USING ERRCODE='P0416',
       DETAIL=format('DR16:deposit_inside_settlement_window refused %s: %s purchased diamond(s) frozen or inside the %s-day settlement window; %s settled',
                     p_amount, v_locked, v_days, v_wallet-v_locked);
   END IF;
   RAISE EXCEPTION 'insufficient_settled_diamonds';
 END IF;
 INSERT INTO public.poker_diamond_custody(user_id,arena_id,purpose,target_id,entry_key,balance)
 VALUES(p_user_id,v_arena,p_purpose,p_target_id,p_entry_key,p_amount) RETURNING id INTO v_custody;
 v_left:=p_amount;
 FOR v_lot IN SELECT id,GREATEST(issued-consumed-refunded-arena_reserved,0) available
 FROM public.diamond_purchase_lots WHERE user_id=p_user_id AND frozen_at IS NULL
 AND created_at<=now()-make_interval(days=>v_days) ORDER BY created_at,id LOOP
   EXIT WHEN v_left=0;
   v_take:=LEAST(v_left,v_lot.available);
   IF v_take>0 THEN
     UPDATE public.diamond_purchase_lots SET arena_reserved=arena_reserved+v_take WHERE id=v_lot.id;
     INSERT INTO public.poker_diamond_lot_reservations(custody_id,lot_id,amount) VALUES(v_custody,v_lot.id,v_take);
     v_left:=v_left-v_take;
   END IF;
 END LOOP;
 -- Journal the transfer before the balance update so the existing DR6 audit
 -- sees its evidence inside this same atomic transaction.
 INSERT INTO public.diamond_transactions(user_id,type,transaction_type,amount,balance_after,reference_id,
 description,source,issuance_class,counterparty,metadata)
 VALUES(p_user_id,'arena_deposit','arena_deposit',-p_amount::integer,v_wallet-p_amount,
 'poker-reserve:'||p_request_id,'Reserved diamonds for Poker Arena','poker_arena','arena',
 'arena_custody:'||v_custody,jsonb_build_object('custody_id',v_custody,'request_id',p_request_id,
 'purpose',p_purpose,'target_id',p_target_id,'purchased_reserved',p_amount-v_left)) RETURNING id INTO v_journal;
 UPDATE public.profiles SET diamonds=diamonds-p_amount::integer,updated_at=now() WHERE id=p_user_id;
 v_receipt:=jsonb_build_object('success',true,'custody_id',v_custody,'request_id',p_request_id,
 'amount',p_amount,'available_balance',v_wallet-p_amount,'custody_balance',p_amount,'journal_id',v_journal);
 INSERT INTO public.poker_diamond_movements(request_id,custody_id,user_id,action,amount,source_account,
 destination_account,wallet_journal_id,request,receipt)
 VALUES(p_request_id,v_custody,p_user_id,'reserve',p_amount,'player:'||p_user_id,
 'arena_custody:'||v_custody,v_journal,v_request,v_receipt);
 RETURN v_receipt;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_spawn_scheduled_tournament(p_schedule_id uuid, p_scheduled_start timestamp with time zone, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_arena uuid; v_s record; v_prior public.ca_diamond_scheduled_spawns%ROWTYPE;
  v_result jsonb; v_id uuid; v_state text; v_msg text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'service_role_only');
  END IF;
  IF p_schedule_id IS NULL OR p_scheduled_start IS NULL OR p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;
  SELECT c.id INTO v_arena FROM public.clubs c
   WHERE c.asset = 'diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL LIMIT 1;
  IF v_arena IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamond_arena_not_found');
  END IF;
  SELECT s.id, s.club_id, s.union_id, s.active INTO v_s
    FROM public.tournament_schedules s WHERE s.id = p_schedule_id FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'schedule_not_found'); END IF;
  IF v_s.club_id IS DISTINCT FROM v_arena OR v_s.union_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'schedule_is_not_a_diamond_arena_schedule');
  END IF;

  -- One spawn per occurrence: concurrent callers queue here, and the second
  -- finds the first one's receipt.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'diamond-scheduled-spawn:' || p_schedule_id::text || ':' || p_scheduled_start::text, 0));
  SELECT * INTO v_prior FROM public.ca_diamond_scheduled_spawns r
   WHERE r.schedule_id = p_schedule_id AND r.scheduled_start = p_scheduled_start;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'tournament_id', v_prior.tournament_id, 'replayed', true);
  END IF;

  IF v_s.active IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'schedule_not_active');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ca_arena_settings a
                  WHERE a.club_id = v_arena AND a.tournaments_enabled) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamond_tournaments_not_open');
  END IF;

  BEGIN
    v_result := public.fn_poker_diamond_create_tournament_core(p_config, jsonb_build_object(
      'door', 'schedule', 'schedule_id', p_schedule_id, 'scheduled_start', p_scheduled_start));
  EXCEPTION
    WHEN unique_violation THEN
      GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
      RETURN jsonb_build_object('ok', false, 'reason', 'scheduled_occurrence_already_on_the_board', 'detail', v_msg);
    WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT, v_state = RETURNED_SQLSTATE;
      RETURN jsonb_build_object('ok', false,
        'reason', btrim(split_part(split_part(v_msg, ':', 1), ' ', 1)),
        'detail', v_msg, 'sqlstate', v_state);
  END;
  v_id := (v_result->>'tournamentId')::uuid;
  INSERT INTO public.ca_diamond_scheduled_spawns
    (schedule_id, scheduled_start, tournament_id, config, result, authority)
  VALUES (p_schedule_id, p_scheduled_start, v_id, p_config, v_result,
    'tournament_schedules row ' || p_schedule_id::text
    || ', seeded under Dan 2026-10-06: "USE THE SAME TOURNAMENT SCHEDULE AND RAKE AS THE MIDWAY UNION FOR NOW"');
  RETURN jsonb_build_object('ok', true, 'tournament_id', v_id, 'replayed', false,
    'buy_in_amount', v_result->'buy_in_amount', 'buy_in_fee', v_result->'buy_in_fee',
    'bounty_amount', v_result->'bounty_amount', 'guaranteed_prize', v_result->'guaranteed_prize');
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_spin_contract(p_buy_in bigint, p_starting_chips integer, p_tiers jsonb, p_blinds jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rake numeric; v_b record; v_c jsonb; v_tier jsonb; v_place record; v_key text;
  v_m numeric; v_f numeric; v_thr numeric; v_pool numeric; v_share numeric; v_pct numeric;
  v_ladder jsonb; v_estate jsonb; v_tiers jsonb := '[]'::jsonb;
  v_freq numeric := 0; v_weight numeric := 0; v_worst numeric := 0; v_cover numeric := 0;
BEGIN
  IF p_buy_in IS NULL OR p_buy_in < 1 OR p_buy_in > 2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_positive_buy_in' USING ERRCODE='22023';
  END IF;
  IF p_starting_chips IS NULL OR p_starting_chips < 1 THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_starting_stack' USING ERRCODE='22023';
  END IF;

  -- The blind ladder, under the chip draw authority's manifest rule: twelve
  -- levels in order, no ante, the twelfth carrying the continuation that
  -- prices every level after it (the engine refuses a receipt without it).
  IF jsonb_typeof(p_blinds) IS DISTINCT FROM 'array' OR jsonb_array_length(p_blinds) <> 12 THEN
    RAISE EXCEPTION 'diamond_spin_requires_its_blind_ladder' USING ERRCODE='22023';
  END IF;
  FOR v_b IN SELECT b.value, b.ordinality FROM jsonb_array_elements(p_blinds) WITH ORDINALITY b ORDER BY b.ordinality LOOP
    IF jsonb_typeof(v_b.value) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_b.value->'level') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_b.value->'smallBlind') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_b.value->'bigBlind') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_b.value->'duration') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_b.value->'ante') IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION 'diamond_spin_requires_its_blind_ladder' USING ERRCODE='22023';
    END IF;
    IF (v_b.value->>'level')::numeric <> v_b.ordinality
       OR (v_b.value->>'smallBlind')::numeric <= 0
       OR (v_b.value->>'bigBlind')::numeric < (v_b.value->>'smallBlind')::numeric
       OR (v_b.value->>'duration')::numeric <= 0
       OR (v_b.value->>'ante')::numeric <> 0 THEN
      RAISE EXCEPTION 'diamond_spin_requires_its_blind_ladder' USING ERRCODE='22023';
    END IF;
  END LOOP;
  v_c := p_blinds->11->'spinContinuation';
  IF jsonb_typeof(v_c) IS DISTINCT FROM 'object'
     OR jsonb_typeof(v_c->'version') IS DISTINCT FROM 'number'
     OR jsonb_typeof(v_c->'anchorLevel') IS DISTINCT FROM 'number'
     OR jsonb_typeof(v_c->'anchorBigBlind') IS DISTINCT FROM 'number'
     OR jsonb_typeof(v_c->'growth') IS DISTINCT FROM 'number'
     OR jsonb_typeof(v_c->'roundBigTo') IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION 'diamond_spin_requires_its_blind_ladder' USING ERRCODE='22023';
  END IF;
  IF (v_c->>'version')::numeric <> 1
     OR (v_c->>'anchorLevel')::numeric <= 0 OR (v_c->>'anchorLevel')::numeric <> trunc((v_c->>'anchorLevel')::numeric)
     OR (v_c->>'anchorBigBlind')::numeric <= 0
     OR (v_c->>'growth')::numeric <= 1
     OR (v_c->>'roundBigTo')::numeric <= 0 THEN
    RAISE EXCEPTION 'diamond_spin_requires_its_blind_ladder' USING ERRCODE='22023';
  END IF;

  -- The multiplier table, tier by tier, under the chip draw authority's rules.
  IF jsonb_typeof(p_tiers) IS DISTINCT FROM 'array' OR jsonb_array_length(p_tiers) NOT BETWEEN 1 AND 32 THEN
    RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid' USING ERRCODE='22023';
  END IF;
  v_rake := public.fn_spin_rake_rate(p_buy_in);
  FOR v_tier IN SELECT t.value FROM jsonb_array_elements(p_tiers) WITH ORDINALITY t ORDER BY t.ordinality LOOP
    IF jsonb_typeof(v_tier) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_tier->'multiplier') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_tier->'freq') IS DISTINCT FROM 'number'
       OR jsonb_typeof(COALESCE(v_tier->'reserveThresholdX', '0'::jsonb)) IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid' USING ERRCODE='22023';
    END IF;
    FOR v_key IN SELECT jsonb_object_keys(v_tier) LOOP
      IF v_key NOT IN ('multiplier','freq','reserveThresholdX','payoutStructure') THEN
        RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid: a tier does not take %', v_key USING ERRCODE='22023';
      END IF;
    END LOOP;
    v_m := (v_tier->>'multiplier')::numeric;
    v_f := (v_tier->>'freq')::numeric;
    v_thr := COALESCE((v_tier->>'reserveThresholdX')::numeric, 0);
    IF v_m <= 0 OR v_f <= 0 OR v_thr < 0 THEN
      RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid' USING ERRCODE='22023';
    END IF;
    -- The ladder: the tier's own, or the estate's for this multiplier. The
    -- terminal prices a multiplier the estate knows from the estate's ladder
    -- (fn_ca_tournament_place_amounts), so a tier may not advertise another.
    v_estate := NULL;
    SELECT l.structure INTO v_estate FROM public.spin_payout_ladder l WHERE l.multiplier = v_m;
    v_ladder := COALESCE(v_tier->'payoutStructure', v_estate);
    IF v_ladder IS NULL THEN
      RAISE EXCEPTION 'diamond_spin_tier_needs_a_payout_ladder: %x has no ladder of its own and none in spin_payout_ladder', v_m
        USING ERRCODE='22023';
    END IF;
    IF v_estate IS NOT NULL AND v_ladder IS DISTINCT FROM v_estate THEN
      RAISE EXCEPTION 'diamond_spin_ladder_is_not_the_estate_ladder: %x pays %, the estate pays %', v_m, v_ladder, v_estate
        USING ERRCODE='22023';
    END IF;
    IF jsonb_typeof(v_ladder) IS DISTINCT FROM 'array' OR jsonb_array_length(v_ladder) NOT BETWEEN 1 AND 3 THEN
      RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid' USING ERRCODE='22023';
    END IF;
    -- THE WHOLE-DIAMOND RULE: the pool, and every place of its ladder, is a
    -- whole number of Diamonds at this buy-in, or the tier cannot be honoured.
    v_pool := v_m * p_buy_in;
    IF v_pool <> trunc(v_pool) OR v_pool < 1 THEN
      RAISE EXCEPTION 'diamond_spin_tier_not_whole_at_the_buy_in: %x at a buy-in of % Diamonds is a prize pool of % Diamonds',
        v_m, p_buy_in, v_pool USING ERRCODE='22023';
    END IF;
    v_pct := 0;
    FOR v_place IN SELECT p.value, p.ordinality FROM jsonb_array_elements(v_ladder) WITH ORDINALITY p ORDER BY p.ordinality LOOP
      IF jsonb_typeof(v_place.value) IS DISTINCT FROM 'object'
         OR jsonb_typeof(v_place.value->'place') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_place.value->'percentage') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid' USING ERRCODE='22023';
      END IF;
      IF (v_place.value->>'place')::numeric <> v_place.ordinality
         OR (v_place.value->>'percentage')::numeric <= 0 THEN
        RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid' USING ERRCODE='22023';
      END IF;
      v_share := v_pool * (v_place.value->>'percentage')::numeric / 100;
      IF v_share <> trunc(v_share) OR v_share < 1 THEN
        RAISE EXCEPTION 'diamond_spin_tier_not_whole_at_the_buy_in: %x place % takes % of a % Diamond pool',
          v_m, v_place.ordinality, v_share, v_pool USING ERRCODE='22023';
      END IF;
      v_pct := v_pct + (v_place.value->>'percentage')::numeric;
    END LOOP;
    IF v_pct <> 100 THEN
      RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid' USING ERRCODE='22023';
    END IF;
    v_freq := v_freq + v_f;
    v_weight := v_weight + v_f * v_m;
    -- What the source can be asked for: the pool above the three entries.
    -- What it must hold for the tier to be drawable: that, or the tier's
    -- reserve threshold times its pool (the chip reserve gate, with this
    -- event's own buy-in as its stake), whichever is more.
    v_worst := GREATEST(v_worst, v_pool - 3 * p_buy_in);
    v_cover := GREATEST(v_cover, v_pool - 3 * p_buy_in, CASE WHEN v_thr > 0 THEN ceil(v_pool * v_thr) ELSE 0 END);
    v_tiers := v_tiers || jsonb_build_array(jsonb_build_object(
      'multiplier', v_m, 'freq', v_f, 'reserveThresholdX', v_thr,
      'blind_structure', p_blinds, 'payout_structure', v_ladder));
  END LOOP;
  IF (SELECT count(DISTINCT (x->>'multiplier')::numeric) FROM jsonb_array_elements(v_tiers) x) <> jsonb_array_length(v_tiers) THEN
    RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid: a multiplier appears twice' USING ERRCODE='22023';
  END IF;
  -- The chip authority's one pricing rule: E[multiplier] = seats x (1 - rake), exactly.
  IF v_weight <> v_freq * 3 * (1 - v_rake) THEN
    RAISE EXCEPTION 'diamond_spin_multiplier_table_invalid: the table expects %x of three seats, the approved edge prices %x',
      round(v_weight / v_freq, 6), 3 * (1 - v_rake) USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object(
    'manifest', jsonb_build_object('version', 1, 'asset', 'diamonds', 'unit_cents', 100,
      'buy_in', p_buy_in, 'seats', 3, 'starting_chips', p_starting_chips, 'rake_rate', v_rake, 'tiers', v_tiers),
    'worst_excess', v_worst::bigint, 'required_cover', v_cover::bigint);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_cancel(p_tournament_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_actor uuid := COALESCE(auth.uid(), p_actor_id, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);
  v_t public.tournaments%ROWTYPE; v_player record; v_refund jsonb;
  v_cancelled_at timestamptz := transaction_timestamp();
  v_refunds jsonb := '[]'::jsonb; v_receipt jsonb;
  v_source_player_ids uuid[]; v_refunded_registration_ids uuid[] := ARRAY[]::uuid[];
  v_zero_refund_registration_ids uuid[] := ARRAY[]::uuid[]; v_closed_table_ids uuid[];
  v_source_seat_ids uuid[]; v_released_seat_ids uuid[];
  v_total bigint := 0; v_fees bigint := 0; v_count integer := 0; v_lines integer := 0;
  v_rake_before numeric; v_rows integer; v_request uuid;
BEGIN
  IF p_tournament_id IS NULL THEN RAISE EXCEPTION 'Tournament id is required' USING ERRCODE='22004'; END IF;
  -- The global settlement lane is already held when atomic_cancel_tournament
  -- routes here; taken again for a direct owner call, it is re-entrant.
  PERFORM public.fn_ca_lock_settlement_lane_global();
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514';
  END IF;
  -- The arena has no club operators; platform staff cancel a Diamond event,
  -- the same authority that creates one. A service-role call carries no uid.
  IF v_uid IS NOT NULL AND NOT public.fn_is_platform_admin() THEN
    RAISE EXCEPTION 'Only platform staff may cancel a Diamond tournament' USING ERRCODE='42501';
  END IF;
  -- A stored receipt is the answer, replayed exactly.
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h WHERE h.tournament_id=p_tournament_id) THEN
    RETURN public.fn_ca_tournament_cancellation_receipt(p_tournament_id,NULL);
  END IF;
  IF upper(COALESCE(v_t.status::text,'')) IN ('COMPLETED','CANCELLED','CANCELED','COMPLETING') THEN
    RAISE EXCEPTION 'Tournament is already %',v_t.status USING ERRCODE='55000';
  END IF;
  -- THE CHIP RULE, UNCHANGED: a started event is resumed or settled, never voided.
  IF v_t.started_at IS NOT NULL
     OR upper(COALESCE(v_t.status::text,'')) IN ('RUNNING','BREAK')
     OR EXISTS (SELECT 1 FROM public.tournament_launch_receipts r
                 WHERE r.tournament_id=p_tournament_id AND r.completed_at IS NOT NULL)
     OR EXISTS (SELECT 1 FROM public.hand_history hh WHERE hh.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tables tb JOIN public.hand_history hh ON hh.table_id=tb.id
                 WHERE tb.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id=p_tournament_id AND o.kind<>'refund' AND o.amount_paid>0)
     OR EXISTS (SELECT 1 FROM public.poker_diamond_tournament_ledger l
                 WHERE l.tournament_id=p_tournament_id AND l.kind IN ('prize','bounty','fee')) THEN
    RAISE EXCEPTION 'Tournament has started or committed awards; resume or settle it instead of cancelling'
      USING ERRCODE='55000';
  END IF;

  -- Freeze every identity before any refund runs.
  PERFORM 1 FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id ORDER BY tp.user_id,tp.id FOR UPDATE;
  PERFORM 1 FROM public.tables tb WHERE tb.tournament_id=p_tournament_id ORDER BY tb.id FOR UPDATE;
  PERFORM 1 FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
    WHERE tb.tournament_id=p_tournament_id ORDER BY s.table_id,s.id FOR UPDATE OF s;
  SELECT COALESCE(array_agg(tp.id ORDER BY tp.id),ARRAY[]::uuid[]) INTO v_source_player_ids
    FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id),ARRAY[]::uuid[]) INTO v_closed_table_ids
    FROM public.tables tb WHERE tb.tournament_id=p_tournament_id;
  SELECT COALESCE(array_agg(s.id ORDER BY s.table_id,s.id),ARRAY[]::uuid[]) INTO v_source_seat_ids
    FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id WHERE tb.tournament_id=p_tournament_id;
  v_rake_before := COALESCE(v_t.total_rake,0);
  -- The caches must equal the custody banks before anything moves.
  IF (SELECT prize_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id)) IS DISTINCT FROM COALESCE(v_t.prize_pool,0)
     OR (SELECT bounty_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id)) IS DISTINCT FROM COALESCE(v_t.bounty_pool,0)
     OR (SELECT fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id)) IS DISTINCT FROM v_rake_before THEN
    RAISE EXCEPTION 'tournament % caches do not equal exact custody before cancellation', p_tournament_id USING ERRCODE='P0404';
  END IF;

  -- Whoever paid in gets it back, entry by entry, from their own custody row.
  FOR v_player IN
    SELECT tp.id, tp.user_id FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id ORDER BY tp.user_id, tp.id
  LOOP
    IF v_player.user_id IS NOT NULL AND EXISTS (
         SELECT 1 FROM public.poker_diamond_custody c
          WHERE c.user_id=v_player.user_id AND c.purpose='tournament_entry'
            AND c.target_id=p_tournament_id AND c.state<>'released') THEN
      v_request := uuid_in(md5('poker-tournament-cancel:'||p_tournament_id::text||':'||v_player.user_id::text)::cstring);
      v_refund := public.fn_poker_diamond_tournament_refund(
        p_tournament_id, v_player.user_id, 'cancel', 'atomic_cancel_tournament', v_request);
      IF COALESCE((v_refund->>'idempotent')::boolean,false) THEN
        RAISE EXCEPTION 'tournament % refund for % was already recorded before this cancellation', p_tournament_id, v_player.user_id USING ERRCODE='P0404';
      END IF;
      v_total := v_total + (v_refund->>'paid')::bigint;
      v_fees := v_fees + (v_refund->>'refund_fee')::bigint;
      v_count := v_count + 1; v_lines := v_lines + 1;
      v_refunded_registration_ids := array_append(v_refunded_registration_ids, v_player.id);
      v_refunds := v_refunds || jsonb_build_object(
        'registration_id',v_player.id,'user_id',v_player.user_id,
        'custody_id',(v_refund->>'custody_id')::uuid,'ledger_id',(v_refund->>'ledger_id')::bigint,
        'amount',(v_refund->>'paid')::numeric,'refund_prize',(v_refund->>'refund_prize')::numeric,
        'refund_bounty',(v_refund->>'refund_bounty')::numeric,'refund_fee',(v_refund->>'refund_fee')::numeric,
        'obligation_id',(v_refund->>'obligation_id')::uuid,'journal_id',NULLIF(v_refund->>'journal_id','')::uuid,
        'request_id',v_request);
    ELSE
      v_zero_refund_registration_ids := array_append(v_zero_refund_registration_ids, v_player.id);
    END IF;
  END LOOP;
  IF public.fn_poker_diamond_tournament_custody(p_tournament_id) <> 0
     OR EXISTS (SELECT 1 FROM public.poker_diamond_custody c
                 WHERE c.purpose='tournament_entry' AND c.target_id=p_tournament_id AND c.state<>'released') THEN
    RAISE EXCEPTION 'diamond_tournament_custody_not_empty_after_cancel' USING ERRCODE='P0404';
  END IF;
  IF (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id)) <> 0 THEN
    RAISE EXCEPTION 'tournament % cancellation did not close all custody banks', p_tournament_id USING ERRCODE='P0404';
  END IF;

  -- 2026-10-06 (20261007000010): a cancelled event keeps no promise; its
  -- guarantee earmark is released back to the house's available balance.
  PERFORM public.fn_poker_diamond_guarantee_release(p_tournament_id, 'cancel');
  UPDATE public.tournament_players
     SET status='eliminated',eliminated_at=v_cancelled_at,chips=0,current_bounty=0
   WHERE tournament_id=p_tournament_id;
  WITH released AS (
    UPDATE public.table_seats s
       SET left_at=v_cancelled_at,status='left',leave_pending=false,
           is_sitting_out=false,is_away=false,sit_out_at=NULL,scheduled_leave_hands=NULL
      FROM public.tables tb
     WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id AND s.left_at IS NULL
     RETURNING s.id)
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[]) INTO v_released_seat_ids FROM released;
  UPDATE public.table_seats s
     SET status='left',leave_pending=false,is_sitting_out=false,is_away=false,sit_out_at=NULL,scheduled_leave_hands=NULL
   WHERE s.id=ANY(v_source_seat_ids) AND s.left_at IS NOT NULL;
  UPDATE public.tournaments
     SET status='CANCELLED',ended_at=v_cancelled_at,updated_at=now(),
         prize_pool=0,bounty_pool=0,total_rake=0,current_players=0,
         on_break=false,break_started_at=NULL,break_ends_at=NULL
   WHERE id=p_tournament_id
     AND upper(COALESCE(status::text,'')) NOT IN ('COMPLETED','CANCELLED','CANCELED','COMPLETING');
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'tournament % lost its cancellation lifecycle claim', p_tournament_id USING ERRCODE='55000'; END IF;
  UPDATE public.tables
     SET status='closed',lifecycle='closed',current_players=0,terminal_closed_at=v_cancelled_at,updated_at=now()
   WHERE tournament_id=p_tournament_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>cardinality(v_closed_table_ids) THEN
    RAISE EXCEPTION 'tournament % did not close every table', p_tournament_id USING ERRCODE='55000';
  END IF;

  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[]) INTO v_refunded_registration_ids FROM unnest(v_refunded_registration_ids) ids(id);
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[]) INTO v_zero_refund_registration_ids FROM unnest(v_zero_refund_registration_ids) ids(id);
  v_receipt := jsonb_build_object(
    'ok',true,'success',true,'fully_settled',true,'receipt_version',2,'asset','diamonds',
    'tournament_id',p_tournament_id,'actor_id',v_actor,'status','CANCELLED',
    'source_player_count',cardinality(v_source_player_ids),
    'refunded_count',v_count,'refund_line_count',v_lines,
    'ticket_return_count',0,'total_ticket_returned',0,
    'total_refunded',v_total,'fees_reversed',v_fees,
    'closed_table_count',cardinality(v_closed_table_ids),
    'source_seat_count',cardinality(v_source_seat_ids),
    'released_seat_count',cardinality(v_released_seat_ids),
    'refunds',v_refunds,'ticket_returns','[]'::jsonb,
    'settled_at',v_cancelled_at);
  INSERT INTO public.tournament_cancellation_receipts(
    tournament_id,actor_id,receipt_version,
    source_player_count,source_player_ids,
    refunded_count,refunded_registration_ids,refund_line_count,
    ticket_return_count,ticket_return_ids,total_ticket_returned,
    zero_refund_count,zero_refund_registration_ids,
    total_refunded,fees_reversed,total_rake_before,total_rake_after,
    closed_table_count,closed_table_ids,source_seat_count,source_seat_ids,
    released_seat_count,released_seat_ids,fee_reversal_ids,
    escrow_closed_at,escrow_close_note,spin_unwind_tournament_id,
    receipt,settled_at)
  VALUES(
    p_tournament_id,v_actor,2,
    cardinality(v_source_player_ids),v_source_player_ids,
    v_count,v_refunded_registration_ids,v_lines,
    0,ARRAY[]::uuid[],0,
    cardinality(v_zero_refund_registration_ids),v_zero_refund_registration_ids,
    v_total,v_fees,v_rake_before,0,
    cardinality(v_closed_table_ids),v_closed_table_ids,cardinality(v_source_seat_ids),v_source_seat_ids,
    cardinality(v_released_seat_ids),v_released_seat_ids,ARRAY[]::uuid[],
    v_cancelled_at,'diamond custody returned: exact zero',NULL,v_receipt,v_cancelled_at);
  RETURN public.fn_ca_tournament_cancellation_receipt(p_tournament_id,v_actor);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_charge(p_user_id uuid, p_tournament_id uuid, p_kind text, p_gross numeric, p_prize numeric, p_bounty numeric, p_fee numeric, p_registration_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_arena uuid; v_c public.poker_diamond_custody%ROWTYPE; v_receipt jsonb;
  v_request uuid; v_ledger bigint; v_existing public.poker_diamond_tournament_ledger%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_tournament_id IS NULL OR p_idempotency_key IS NULL
     OR p_kind IS NULL OR p_kind NOT IN ('entry','rebuy','reentry','addon')
     OR p_gross IS NULL OR p_prize IS NULL OR p_bounty IS NULL OR p_fee IS NULL
     OR p_gross < 1 OR p_prize < 0 OR p_bounty < 0 OR p_fee < 0
     OR p_gross <> trunc(p_gross) OR p_prize <> trunc(p_prize)
     OR p_bounty <> trunc(p_bounty) OR p_fee <> trunc(p_fee)
     OR p_prize + p_bounty + p_fee <> p_gross THEN
    RAISE EXCEPTION 'diamond_tournament_charge_requires_whole_parts' USING ERRCODE='22023';
  END IF;
  IF p_kind = 'entry' AND p_registration_id IS NULL THEN
    RAISE EXCEPTION 'diamond_tournament_entry_requires_a_registration' USING ERRCODE='22023';
  END IF;
  -- Phase 9: the bounty part is a bank of its own (fn_poker_diamond_tournament_drain
  -- 'bounty'); a knockout bounty event carries one on every entry and re-entry.
  SELECT t.club_id INTO v_arena FROM public.tournaments t JOIN public.clubs c ON c.id=t.club_id
   WHERE t.id=p_tournament_id AND c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL AND t.union_id IS NULL;
  IF v_arena IS NULL THEN
    RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514';
  END IF;

  -- The same key twice is the same charge: return what it wrote.
  SELECT * INTO v_existing FROM public.poker_diamond_tournament_ledger WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN
    IF v_existing.user_id<>p_user_id OR v_existing.tournament_id<>p_tournament_id
       OR v_existing.kind<>p_kind OR v_existing.amount<>p_gross THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch';
    END IF;
    RETURN jsonb_build_object('success',true,'idempotent',true,'custody_id',v_existing.custody_id,
      'ledger_id',v_existing.id,'journal_id',v_existing.wallet_journal_id,'amount',v_existing.amount);
  END IF;
  v_request := uuid_in(md5('poker-tournament-charge:'||p_idempotency_key)::cstring);

  SELECT * INTO v_c FROM public.poker_diamond_custody
   WHERE user_id=p_user_id AND purpose='tournament_entry' AND target_id=p_tournament_id AND state<>'released'
   FOR UPDATE;
  IF p_kind = 'entry' THEN
    IF FOUND THEN
      RAISE EXCEPTION 'diamond_tournament_entry_already_held' USING ERRCODE='23505';
    END IF;
    -- The reserve door prices the entry itself (buy-in plus fee, exactly) and
    -- refuses while tournaments_enabled is off. Both refusals surface here.
    v_receipt := public.fn_poker_diamond_reserve(
      p_user_id,'tournament_entry',p_tournament_id,'entry:'||p_registration_id::text,p_gross,v_request);
    IF COALESCE((v_receipt->>'success')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'diamond_tournament_reserve_failed' USING ERRCODE='P0404';
    END IF;
    SELECT * INTO v_c FROM public.poker_diamond_custody WHERE id=(v_receipt->>'custody_id')::uuid FOR UPDATE;
    -- THE ENTRY IS ACTIVE FROM THE MOMENT IT IS PAID. The seat guards (P0810,
    -- P0812) admit a Diamond tournament seat only against an active entry for
    -- its player and event; this is the tournament mirror of the cash binder,
    -- moved to where the money is, and it never binds a seat (P0813).
    UPDATE public.poker_diamond_custody SET state='active' WHERE id=v_c.id AND state='reserved' AND purpose='tournament_entry';
    IF NOT FOUND THEN RAISE EXCEPTION 'diamond_tournament_entry_activation_failed' USING ERRCODE='P0404'; END IF;
    v_c.state := 'active';
    -- The first entry locks the entry contract, as the chip entitlement
    -- trigger does: a price nobody has paid may change, a paid one may not.
    UPDATE public.tournaments t SET entry_contract_locked=true WHERE t.id=p_tournament_id AND NOT t.entry_contract_locked;
  ELSE
    IF NOT FOUND THEN
      RAISE EXCEPTION 'diamond_tournament_entry_not_held' USING ERRCODE='55000';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.ca_arena_settings a WHERE a.id=1 AND a.club_id=v_arena AND a.tournaments_enabled) THEN
      RAISE EXCEPTION 'diamond_tournaments_not_open' USING ERRCODE='55000';
    END IF;
    v_receipt := public.fn_poker_diamond_tournament_custody_add(v_c.id,p_gross,v_request);
    IF COALESCE((v_receipt->>'success')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'diamond_tournament_add_failed' USING ERRCODE='P0404';
    END IF;
  END IF;

  INSERT INTO public.poker_diamond_tournament_ledger(
    tournament_id,arena_id,user_id,custody_id,kind,amount,prize_part,bounty_part,fee_part,
    idempotency_key,wallet_journal_id,registration_id,request)
  VALUES (p_tournament_id,v_arena,p_user_id,v_c.id,p_kind,p_gross::bigint,p_prize::bigint,p_bounty::bigint,p_fee::bigint,
    p_idempotency_key,(v_receipt->>'journal_id')::uuid,p_registration_id,
    jsonb_build_object('kind',p_kind,'gross',p_gross,'prize',p_prize,'bounty',p_bounty,'fee',p_fee,'request_id',v_request))
  RETURNING id INTO v_ledger;

  -- Once the escrow shadow is open (a knockout paid mid-event opens it from
  -- the ledger), every later inflow - a late entry, a re-entry, a rebuy, an
  -- add-on - is applied to it, as a chip entry's wallet row applies itself.
  IF EXISTS (SELECT 1 FROM public.tournament_escrow x WHERE x.tournament_id=p_tournament_id) THEN
    PERFORM public.fn_ca_escrow_apply(p_tournament_id,'diamond '||p_kind,
      p_gross_in => p_gross, p_fee_entries_in => p_fee, p_bounty_in => p_bounty);
  END IF;

  -- The banks and the custody must agree after every charge.
  IF (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id))
     IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_tournament_id)::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_escrow_disagrees_with_custody' USING ERRCODE='P0404';
  END IF;
  RETURN jsonb_build_object('success',true,'custody_id',v_c.id,'ledger_id',v_ledger,
    'journal_id',v_receipt->>'journal_id','amount',p_gross,'request_id',v_request);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_close_custody(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_c record; v_n integer := 0; v_open bigint; v_receipt jsonb;
BEGIN
  IF NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514';
  END IF;
  v_open := public.fn_poker_diamond_tournament_custody(p_tournament_id);
  IF v_open <> 0 THEN
    RETURN jsonb_build_object('ok',true,'closed',0,'still_held',v_open);
  END IF;
  FOR v_c IN SELECT c.id FROM public.poker_diamond_custody c
              WHERE c.purpose='tournament_entry' AND c.target_id=p_tournament_id AND c.state<>'released' AND c.balance=0
              ORDER BY c.created_at, c.id
  LOOP
    PERFORM set_config('app.poker_diamond_tournament_release', v_c.id::text, true);
    v_receipt := public.fn_poker_diamond_release(v_c.id, uuid_in(md5('poker-tournament-close:'||v_c.id::text)::cstring));
    PERFORM set_config('app.poker_diamond_tournament_release', '', true);
    IF COALESCE((v_receipt->>'success')::boolean,false) IS NOT TRUE OR (v_receipt->>'amount')::bigint <> 0 THEN
      RAISE EXCEPTION 'diamond_tournament_close_failed' USING ERRCODE='P0404';
    END IF;
    v_n := v_n + 1;
  END LOOP;
  -- 2026-10-06 (20261007000010): a completed event keeps no promise; any
  -- guarantee earmark still open is released (fn_settle_tournament_rake calls
  -- this door at the terminal).
  PERFORM public.fn_poker_diamond_guarantee_release(p_tournament_id, 'complete');
  RETURN jsonb_build_object('ok',true,'closed',v_n,'still_held',0);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_custody_add(p_custody_id uuid, p_amount numeric, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_c public.poker_diamond_custody%ROWTYPE;
 v_prev public.poker_diamond_movements%ROWTYPE;
 v_request jsonb; v_receipt jsonb;
 v_wallet bigint; v_locked bigint; v_days integer;
 v_left bigint; v_take bigint; v_lot record; v_journal uuid;
BEGIN
 IF p_custody_id IS NULL OR p_request_id IS NULL
    OR p_amount IS NULL OR p_amount NOT BETWEEN 1 AND 2147483647 OR p_amount<>trunc(p_amount) THEN
  RAISE EXCEPTION 'invalid_diamond_tournament_add' USING ERRCODE='22023';
 END IF;
 SELECT user_id INTO v_c.user_id FROM public.poker_diamond_custody WHERE id=p_custody_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'diamond_custody_not_found'; END IF;
 -- Wallet first, exactly as the reserve and the top-up take it.
 SELECT diamonds INTO v_wallet FROM public.profiles WHERE id=v_c.user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'profile_not_found'; END IF;
 SELECT * INTO v_c FROM public.poker_diamond_custody WHERE id=p_custody_id FOR UPDATE;
 v_request:=jsonb_build_object('user_id',v_c.user_id,'custody_id',p_custody_id,
  'amount',p_amount,'action','tournament_add');
 SELECT * INTO v_prev FROM public.poker_diamond_movements WHERE request_id=p_request_id;
 IF FOUND THEN
  IF v_prev.request IS DISTINCT FROM v_request THEN RAISE EXCEPTION 'idempotency_payload_mismatch'; END IF;
  RETURN v_prev.receipt;
 END IF;
 IF v_c.purpose<>'tournament_entry' OR v_c.state<>'active' THEN
  RAISE EXCEPTION 'diamond_tournament_custody_not_open' USING ERRCODE='55000';
 END IF;
 IF v_c.balance+p_amount>2147483647 THEN
  RAISE EXCEPTION 'diamond_amount_out_of_range' USING ERRCODE='22003';
 END IF;
 SELECT settlement_window_days INTO v_days FROM public.ca_arena_settings WHERE id=1 AND club_id=v_c.arena_id;
 IF v_days IS NULL THEN RAISE EXCEPTION 'diamond_arena_policy_missing'; END IF;
 IF EXISTS(SELECT 1 FROM public.diamond_debts WHERE user_id=v_c.user_id AND settled_at IS NULL AND amount>0) THEN
  RAISE EXCEPTION 'diamond_debt_requires_settlement';
 END IF;
 PERFORM id FROM public.diamond_purchase_lots WHERE user_id=v_c.user_id ORDER BY created_at,id FOR UPDATE;
 SELECT COALESCE(sum(GREATEST(issued-consumed-refunded-arena_reserved,0)),0) INTO v_locked
  FROM public.diamond_purchase_lots WHERE user_id=v_c.user_id
   AND (frozen_at IS NOT NULL OR created_at>now()-make_interval(days=>v_days));
 IF v_wallet IS NULL OR v_wallet-v_locked<p_amount THEN
  RAISE EXCEPTION 'insufficient_settled_diamonds';
 END IF;
 v_left:=p_amount;
 FOR v_lot IN SELECT id,GREATEST(issued-consumed-refunded-arena_reserved,0) available
  FROM public.diamond_purchase_lots WHERE user_id=v_c.user_id AND frozen_at IS NULL
   AND created_at<=now()-make_interval(days=>v_days) ORDER BY created_at,id LOOP
  EXIT WHEN v_left=0;
  v_take:=LEAST(v_left,v_lot.available);
  IF v_take>0 THEN
   UPDATE public.diamond_purchase_lots SET arena_reserved=arena_reserved+v_take WHERE id=v_lot.id;
   UPDATE public.poker_diamond_lot_reservations SET amount=amount+v_take
     WHERE custody_id=v_c.id AND lot_id=v_lot.id AND released_at IS NULL;
   IF NOT FOUND THEN
    BEGIN
     INSERT INTO public.poker_diamond_lot_reservations(custody_id,lot_id,amount) VALUES(v_c.id,v_lot.id,v_take);
    EXCEPTION WHEN unique_violation THEN
     RAISE EXCEPTION 'diamond_tournament_lot_already_released' USING ERRCODE='23514';
    END;
   END IF;
   v_left:=v_left-v_take;
  END IF;
 END LOOP;
 INSERT INTO public.diamond_transactions(user_id,type,transaction_type,amount,balance_after,
  reference_id,description,source,issuance_class,counterparty,metadata)
 VALUES(v_c.user_id,'arena_deposit','arena_deposit',-p_amount::integer,v_wallet-p_amount,
  'poker-tournament-add:'||p_request_id,'Added diamonds to a Poker Arena tournament entry','poker_arena','arena',
  'arena_custody:'||v_c.id,jsonb_build_object('custody_id',v_c.id,'request_id',p_request_id,
   'purpose','tournament_entry','target_id',v_c.target_id,'purchased_reserved',p_amount-v_left)) RETURNING id INTO v_journal;
 UPDATE public.profiles SET diamonds=diamonds-p_amount::integer,updated_at=now() WHERE id=v_c.user_id;
 UPDATE public.poker_diamond_custody SET balance=balance+p_amount WHERE id=v_c.id;
 v_receipt:=jsonb_build_object('success',true,'custody_id',v_c.id,'request_id',p_request_id,
  'amount',p_amount,'custody_balance',v_c.balance+p_amount,
  'available_balance',v_wallet-p_amount,'journal_id',v_journal);
 INSERT INTO public.poker_diamond_movements(request_id,custody_id,user_id,action,amount,
  source_account,destination_account,wallet_journal_id,request,receipt)
 VALUES(p_request_id,v_c.id,v_c.user_id,'reserve',p_amount,'player:'||v_c.user_id,
  'arena_custody:'||v_c.id,v_journal,v_request,v_receipt);
 RETURN v_receipt;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_drain(p_tournament_id uuid, p_bank text, p_amount bigint, p_reason text, p_destination_account text, p_journal_for uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_left bigint := p_amount; v_take bigint; v_c record; v_lot record; v_loss bigint;
  v_drained jsonb := '[]'::jsonb; v_req uuid; v_journal uuid; v_wallet bigint; v_name text;
  v_register text; v_label text; v_supply numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_bank NOT IN ('prize','fee','bounty') OR p_amount IS NULL OR p_amount < 1 OR p_reason IS NULL
     OR p_destination_account IS NULL OR length(btrim(p_destination_account))=0 THEN
    RAISE EXCEPTION 'invalid_diamond_tournament_drain' USING ERRCODE='22023';
  END IF;
  IF public.fn_poker_diamond_tournament_custody(p_tournament_id) < p_amount THEN
    RAISE EXCEPTION 'diamond_tournament_custody_short' USING ERRCODE='P0404';
  END IF;
  SELECT t.name INTO v_name FROM public.tournaments t WHERE t.id=p_tournament_id;
  SET CONSTRAINTS public.zzz_diamond_entry_custody_is_the_entry IMMEDIATE;
  FOR v_c IN
    SELECT c.id, c.user_id, c.balance, c.arena_id,
           (SELECT COALESCE(sum(CASE WHEN p_bank='prize' THEN l.prize_part
                                     WHEN p_bank='bounty' THEN l.bounty_part
                                     ELSE l.fee_part END),0)
              FROM public.poker_diamond_tournament_ledger l
             WHERE l.custody_id=c.id AND l.kind IN ('entry','rebuy','reentry','addon','spin_underwrite','overlay'))
         - (SELECT COALESCE(sum(m.amount),0) FROM public.poker_diamond_movements m
             WHERE m.custody_id=c.id AND m.action='release'
               AND m.request->>'action'='tournament_drain' AND m.request->>'bank'=p_bank) AS held
      FROM public.poker_diamond_custody c
     WHERE c.purpose='tournament_entry' AND c.target_id=p_tournament_id AND c.state<>'released' AND c.balance > 0
     ORDER BY c.created_at, c.id
     FOR UPDATE OF c
  LOOP
    EXIT WHEN v_left = 0;
    CONTINUE WHEN v_c.held <= 0;
    v_take := LEAST(v_left, v_c.held, v_c.balance);
    -- The lots this row holds are consumed for what leaves it, oldest first,
    -- exactly as fn_poker_diamond_settle_cash_hand consumes a lost stack.
    v_loss := v_take;
    FOR v_lot IN
      SELECT l.id, r.amount-r.consumed AS held, greatest(l.issued-l.consumed-l.refunded,0) AS outstanding
        FROM public.poker_diamond_lot_reservations r
        JOIN public.diamond_purchase_lots l ON l.id=r.lot_id
       WHERE r.custody_id=v_c.id AND r.released_at IS NULL
       ORDER BY l.created_at, l.id FOR UPDATE OF l, r
    LOOP
      EXIT WHEN v_loss = 0;
      IF v_lot.held > 0 THEN
        UPDATE public.diamond_purchase_lots
           SET arena_reserved=arena_reserved-LEAST(v_loss,v_lot.held),
               consumed=consumed+LEAST(LEAST(v_loss,v_lot.held),v_lot.outstanding)::integer
         WHERE id=v_lot.id;
        UPDATE public.poker_diamond_lot_reservations SET consumed=consumed+LEAST(v_loss,v_lot.held)
         WHERE custody_id=v_c.id AND lot_id=v_lot.id;
        v_loss := v_loss - LEAST(v_loss,v_lot.held);
      END IF;
    END LOOP;
    -- The journal row the movement carries: the recipient's credit for a
    -- prize or a bounty, which moved that recipient's wallet.
    --
    -- A HOUSE-BOUND DRAIN (a fee, a Spin surplus, a guarantee overlay return)
    -- MOVES NO WALLET, SO IT WRITES NO WALLET JOURNAL ROW (20261007132503).
    -- The Diamonds left the player's wallet once, when the entry was bought
    -- (that arena_deposit row is the wallet's record of it); here they leave
    -- custody for the house. A diamond_transactions row would record the same
    -- Diamonds leaving the wallet a second time, and from 13:03 UTC on
    -- 2026-10-07 it did (four tournament_fee rows, 800 Diamonds). The register
    -- still retires them from the player, because it counts custody Diamonds as
    -- the player's: that burn is written here directly, with the wallet
    -- unchanged on both sides, exactly as fn_ca_diamond_sweep_cash_rake writes
    -- the cash rake (20261007112751).
    IF p_journal_for IS NOT NULL THEN
      v_journal := p_journal_for;
      v_register := NULL;
    ELSE
      v_journal := NULL;
      v_register := p_reason||':'||v_c.id::text;
      SELECT COALESCE(diamonds,0), COALESCE(NULLIF(btrim(username),''), full_name, id::text)
        INTO v_wallet, v_label FROM public.profiles WHERE id=v_c.user_id;
      IF v_supply IS NULL THEN
        SELECT COALESCE(SUM(CASE WHEN action='mint' THEN amount ELSE -amount END),0) INTO v_supply
          FROM public.ca_mint_ledger WHERE asset='diamonds';
      END IF;
      v_supply := v_supply - v_take;
      INSERT INTO public.ca_mint_ledger
        (op_id, action, asset, holder_type, holder_id, holder_label, amount,
         balance_before, balance_after, supply_after, reason)
      VALUES
        (v_register, 'burn', 'diamonds', 'player', v_c.user_id, COALESCE(v_label, v_c.user_id::text), v_take,
         COALESCE(v_wallet,0), COALESCE(v_wallet,0), v_supply,
         CASE WHEN p_bank='prize' AND p_reason LIKE 'poker-guarantee-overlay-return:%'
              THEN 'Diamond guarantee overlay returned from this player''s entry custody to the house: '||COALESCE(v_name,'tournament')
              WHEN p_bank='prize'
              THEN 'Diamond Spin surplus returned from this player''s entry custody to the house: '||COALESCE(v_name,'spin')
              ELSE 'Tournament entry fee retired from this player''s entry custody for the house: '||COALESCE(v_name,'tournament') END
         ||'. The wallet does not move: the Diamonds left it when the entry was bought.');
    END IF;
    -- The movement first, then the balance: P0814 (an entry holds exactly its
    -- movements) is checked at the end of this UPDATE, not at commit, because
    -- a row drained twice in one settlement (the fee, then a prize) would
    -- otherwise present its first version against the final movement sum.
    v_req := uuid_in(md5(p_reason||':'||v_c.id::text)::cstring);
    INSERT INTO public.poker_diamond_movements(request_id,custody_id,user_id,action,amount,
      source_account,destination_account,wallet_journal_id,request,receipt)
    VALUES (v_req,v_c.id,v_c.user_id,'release',v_take,'arena_custody:'||v_c.id,p_destination_account,v_journal,
      jsonb_build_object('action','tournament_drain','bank',p_bank,'reason',p_reason,'custody_id',v_c.id,'amount',v_take),
      jsonb_build_object('success',true,'custody_id',v_c.id,'amount',v_take,'custody_balance',v_c.balance-v_take,'journal_id',v_journal,
                         'register_op_id',v_register));
    UPDATE public.poker_diamond_custody SET balance=balance-v_take WHERE id=v_c.id;
    v_drained := v_drained || jsonb_build_object('custody_id',v_c.id,'user_id',v_c.user_id,'amount',v_take,'journal_id',v_journal,
                                                 'register_op_id',v_register,'request_id',v_req);
    v_left := v_left - v_take;
  END LOOP;
  SET CONSTRAINTS public.zzz_diamond_entry_custody_is_the_entry DEFERRED;
  IF v_left <> 0 THEN
    RAISE EXCEPTION 'diamond_tournament_custody_short' USING ERRCODE='P0404';
  END IF;
  RETURN v_drained;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_pay(p_user_id uuid, p_amount numeric, p_idempotency_key text, p_category text, p_tournament_id uuid, p_description text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_arena uuid; v_kind text; v_bank numeric; v_inserted integer; v_drained jsonb; v_credit jsonb; v_e record;
  v_category text := lower(COALESCE(p_category,''));
  v_prior public.poker_diamond_tournament_ledger%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_tournament_id IS NULL OR p_idempotency_key IS NULL
     OR p_amount IS NULL OR p_amount < 1 OR p_amount <> trunc(p_amount) OR p_amount > 2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_pay_requires_whole_diamonds' USING ERRCODE='22023';
  END IF;
  SELECT t.club_id INTO v_arena FROM public.tournaments t JOIN public.clubs c ON c.id=t.club_id
   WHERE t.id=p_tournament_id AND c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL AND t.union_id IS NULL;
  IF v_arena IS NULL THEN RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514'; END IF;
  v_kind := CASE WHEN v_category='bounty' THEN 'bounty'
                 WHEN v_category='prize' THEN 'prize'
                 ELSE NULL END;
  IF v_kind IS NULL THEN
    -- A refund never reaches this door: the Diamond refund authority returns
    -- entries whole through fn_poker_diamond_release.
    RAISE EXCEPTION 'diamond_tournament_pay_unknown_category:%', v_category USING ERRCODE='22023';
  END IF;

  -- The key is claimed before any Diamond moves, as the chip credit claims it.
  INSERT INTO public.wallet_credit_idempotency(key,user_id,amount)
  VALUES (p_idempotency_key,p_user_id,p_amount) ON CONFLICT (key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    -- DIAMOND PHASE 11: A RETRY GETS ITS FIRST RECEIPT. The key is the
    -- payment's identity. The same payee, event, bank and amount under it is
    -- this payment, already made: it answers as the first delivery did (true)
    -- and moves nothing. Any other use of the key - another payee, event, bank
    -- or amount, or a key another credit claimed - is refused by name, as every
    -- other Diamond door refuses a reused request id. The description is the
    -- payment's label, not its identity.
    SELECT l.* INTO v_prior FROM public.poker_diamond_tournament_ledger l
     WHERE l.idempotency_key='poker-tournament-pay:'||p_idempotency_key;
    IF NOT FOUND
       OR v_prior.kind IS DISTINCT FROM v_kind
       OR v_prior.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_prior.user_id IS DISTINCT FROM p_user_id
       OR v_prior.amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'diamond_tournament_pay_key_reused' USING ERRCODE='22023';
    END IF;
    RETURN true;
  END IF;

  -- The bank this payment draws on: a place from the prize bank, a knockout
  -- (its cash half, the champion's own head, the residual) from the bounty
  -- bank. Each is the sum of the entries' parts less what it already paid.
  SELECT * INTO v_e FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id);
  v_bank := CASE WHEN v_kind='bounty' THEN v_e.bounty_balance ELSE v_e.prize_balance END;
  IF v_bank < p_amount THEN
    RAISE EXCEPTION 'diamond_tournament_bank_short' USING ERRCODE='P0404';
  END IF;
  -- A knockout is paid while the event runs, before the terminal opens the
  -- escrow shadow; the shadow is opened here from the Diamond ledger's exact
  -- parts (idempotent, asserted) so the chip shadow never opens itself from a
  -- proportional split at the first bounty.
  PERFORM public.fn_poker_diamond_tournament_open_shadow(p_tournament_id);

  -- The recipient's wallet first (its journal row is what every drained
  -- row's movement carries), then the custody rows, oldest first.
  v_credit := public.add_diamonds_to_balance(
    p_user_id, p_amount::integer, 'arena_withdraw',
    COALESCE(NULLIF(btrim(p_description),''), CASE WHEN v_kind='bounty' THEN 'Tournament bounty' ELSE 'Tournament prize' END),
    'poker-tournament-pay:'||p_idempotency_key);
  IF COALESCE((v_credit->>'success')::boolean,false) IS NOT TRUE OR NULLIF(v_credit->>'transaction_id','') IS NULL THEN
    RAISE EXCEPTION 'diamond_tournament_pay_credit_failed:%', v_credit->>'error' USING ERRCODE='P0404';
  END IF;
  v_drained := public.fn_poker_diamond_tournament_drain(
    p_tournament_id, v_kind, p_amount::bigint, 'poker-tournament-pay:'||p_idempotency_key, 'player:'||p_user_id::text,
    (v_credit->>'transaction_id')::uuid);

  INSERT INTO public.poker_diamond_tournament_ledger(
    tournament_id,arena_id,user_id,custody_id,kind,amount,prize_part,bounty_part,fee_part,
    idempotency_key,wallet_journal_id,request)
  VALUES (p_tournament_id,v_arena,p_user_id,NULL,v_kind,p_amount::bigint,
    CASE WHEN v_kind='prize' THEN p_amount::bigint ELSE 0 END,
    CASE WHEN v_kind='bounty' THEN p_amount::bigint ELSE 0 END,0,
    'poker-tournament-pay:'||p_idempotency_key,(v_credit->>'transaction_id')::uuid,
    jsonb_build_object('kind',v_kind,'credit_key',p_idempotency_key,'drained',v_drained,'description',p_description));

  -- The escrow shadow follows, as a chip payment's wallet row makes it follow.
  IF v_kind='bounty' THEN
    PERFORM public.fn_ca_escrow_apply(p_tournament_id,'diamond bounty',p_bounty_out => p_amount);
  ELSE
    PERFORM public.fn_ca_escrow_apply(p_tournament_id,'diamond prize',p_prize_out => p_amount);
  END IF;

  IF (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id))
     IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_tournament_id)::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_escrow_disagrees_with_custody' USING ERRCODE='P0404';
  END IF;
  -- The answer no longer tells a payment from its retry, so the payment names
  -- its key for the one caller that must know: fn_credit_and_log writes the
  -- payout evidence once, on the call that paid. A retry names nothing.
  PERFORM set_config('app.diamond_tournament_pay_claimed', p_idempotency_key, true);
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_refund(p_tournament_id uuid, p_user_id uuid, p_kind text, p_source text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t record; v_c public.poker_diamond_custody%ROWTYPE; v_parts record;
  v_receipt jsonb; v_key text; v_ledger bigint; v_ob uuid; v_existing public.poker_diamond_tournament_ledger%ROWTYPE;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_request_id IS NULL
     OR p_kind IS NULL OR p_kind NOT IN ('unregister','cancel')
     OR p_source IS NULL OR length(btrim(p_source))=0 THEN
    RAISE EXCEPTION 'invalid_diamond_tournament_refund' USING ERRCODE='22023';
  END IF;
  SELECT t.id,t.status,t.started_at,t.name INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND OR NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514';
  END IF;
  v_key := 'poker-tournament-refund:'||p_tournament_id::text||':'||p_user_id::text||':'||p_kind||':'||p_request_id::text;
  SELECT * INTO v_existing FROM public.poker_diamond_tournament_ledger WHERE idempotency_key=v_key;
  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'idempotent',true,'fully_settled',true,'remaining',0,
      'paid',v_existing.amount,'refund_prize',v_existing.prize_part,'refund_bounty',v_existing.bounty_part,
      'refund_fee',v_existing.fee_part,'custody_id',v_existing.custody_id,'ledger_id',v_existing.id);
  END IF;

  -- DIAMOND PHASE 9: A DRAWN SPIN IS NOT REFUNDED. Once a Diamond Spin's draw
  -- has written its receipt (and moved its reserve legs), its entries are its
  -- prize pool: every exit - a withdrawal, a seat exit, a cancellation - comes
  -- through this door and is refused here by name, as the chip unregistration
  -- refuses a booked Spin (spin_entry_already_booked). A 3x draw moves no leg,
  -- so the receipt, not the ledger, is what decides.
  IF EXISTS (SELECT 1 FROM public.spin_draw_receipts r WHERE r.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.poker_diamond_tournament_ledger l
                 WHERE l.tournament_id=p_tournament_id AND l.kind IN ('spin_underwrite','spin_surplus')) THEN
    RAISE EXCEPTION 'diamond_spin_entry_already_booked' USING ERRCODE='55000';
  END IF;
  -- 2026-10-06 (20261007000010): a guaranteed event whose overlay the house
  -- has paid into custody has started; its entries are its prize pool.
  IF EXISTS (SELECT 1 FROM public.poker_diamond_tournament_ledger l
              WHERE l.tournament_id=p_tournament_id AND l.kind IN ('overlay','overlay_return')) THEN
    RAISE EXCEPTION 'diamond_guaranteed_entry_already_funded' USING ERRCODE='55000';
  END IF;

  -- The roster decides whether this Diamond can go home: before the event
  -- starts a registration may be withdrawn; once it has started only a
  -- cancellation returns entries, and a cancellation returns every entry.
  IF p_kind='unregister' THEN
    IF upper(COALESCE(v_t.status,'')) NOT IN ('ANNOUNCED','REGISTERING') OR v_t.started_at IS NOT NULL THEN
      RAISE EXCEPTION 'diamond_tournament_entry_in_play' USING ERRCODE='55000';
    END IF;
  ELSE
    IF upper(COALESCE(v_t.status,'')) IN ('COMPLETED','COMPLETING') THEN
      RAISE EXCEPTION 'diamond_tournament_already_settled' USING ERRCODE='55000';
    END IF;
  END IF;
  -- An event that has paid anybody is not refundable by this door.
  IF EXISTS (SELECT 1 FROM public.poker_diamond_tournament_ledger l
              WHERE l.tournament_id=p_tournament_id AND l.kind IN ('prize','bounty','fee')) THEN
    RAISE EXCEPTION 'diamond_tournament_already_paid' USING ERRCODE='55000';
  END IF;

  SELECT * INTO v_c FROM public.poker_diamond_custody
   WHERE user_id=p_user_id AND purpose='tournament_entry' AND target_id=p_tournament_id AND state<>'released'
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'diamond_tournament_entry_not_held' USING ERRCODE='55000';
  END IF;
  -- 2026-10-06 (20261007000010): A FREEROLL ENTRY HOLDS NOTHING. Its custody
  -- row was opened at zero (fn_poker_diamond_tournament_free_entry) and has
  -- taken no inflow, so it is released whole, at zero, and no ledger row is
  -- written: there is nothing to return.
  IF v_c.state='active' AND v_c.balance=0 AND v_c.seat_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.poker_diamond_tournament_ledger l WHERE l.custody_id=v_c.id) THEN
    PERFORM set_config('app.poker_diamond_tournament_release', v_c.id::text, true);
    v_receipt := public.fn_poker_diamond_release(v_c.id, p_request_id);
    PERFORM set_config('app.poker_diamond_tournament_release', '', true);
    IF COALESCE((v_receipt->>'success')::boolean,false) IS NOT TRUE OR (v_receipt->>'amount')::bigint <> 0 THEN
      RAISE EXCEPTION 'diamond_tournament_release_failed' USING ERRCODE='P0404';
    END IF;
    RETURN jsonb_build_object('ok',true,'fully_settled',true,'remaining',0,'paid',0,'free_entry',true,
      'refund_prize',0,'refund_bounty',0,'refund_fee',0,'custody_id',v_c.id,'ledger_id',NULL,
      'obligation_id',NULL,'journal_id',NULL,'available_balance',v_receipt->>'available_balance');
  END IF;
  IF v_c.state<>'active' OR v_c.balance<1 OR v_c.seat_id IS NOT NULL THEN
    RAISE EXCEPTION 'diamond_custody_requires_settlement' USING ERRCODE='55000';
  END IF;
  -- What this custody row holds, by bank: everything that entered it, less
  -- nothing, because nothing has left it (asserted above).
  SELECT COALESCE(sum(prize_part),0) AS prize, COALESCE(sum(bounty_part),0) AS bounty,
         COALESCE(sum(fee_part),0) AS fee, COALESCE(sum(amount),0) AS gross
    INTO v_parts FROM public.poker_diamond_tournament_ledger
   WHERE custody_id=v_c.id AND kind IN ('entry','rebuy','reentry','addon');
  IF v_parts.gross IS DISTINCT FROM v_c.balance THEN
    RAISE EXCEPTION 'diamond_tournament_custody_disagrees_with_ledger' USING ERRCODE='P0404';
  END IF;

  -- Open the release for this one row, in this transaction only, then close it.
  PERFORM set_config('app.poker_diamond_tournament_release', v_c.id::text, true);
  v_receipt := public.fn_poker_diamond_release(v_c.id, p_request_id);
  PERFORM set_config('app.poker_diamond_tournament_release', '', true);
  IF COALESCE((v_receipt->>'success')::boolean,false) IS NOT TRUE
     OR (v_receipt->>'amount')::bigint IS DISTINCT FROM v_c.balance THEN
    RAISE EXCEPTION 'diamond_tournament_release_failed' USING ERRCODE='P0404';
  END IF;

  -- The refund is an obligation the way a chip refund is, so the reconciler
  -- and the receipt see one vocabulary. amount_paid closes at amount_owed.
  INSERT INTO public.tournament_obligations(tournament_id,kind,place,user_id,amount_owed,amount_paid,source,settled_at)
  VALUES (p_tournament_id,'refund',NULL,p_user_id,v_c.balance,v_c.balance,p_source,now())
  ON CONFLICT (tournament_id,kind,user_id) WHERE place IS NULL DO UPDATE
    SET amount_owed = public.tournament_obligations.amount_owed + EXCLUDED.amount_owed,
        amount_paid = public.tournament_obligations.amount_paid + EXCLUDED.amount_paid,
        updated_at = now(), settled_at = now()
  RETURNING id INTO v_ob;

  INSERT INTO public.poker_diamond_tournament_ledger(
    tournament_id,arena_id,user_id,custody_id,kind,amount,prize_part,bounty_part,fee_part,
    idempotency_key,wallet_journal_id,obligation_id,request)
  VALUES (p_tournament_id,v_c.arena_id,p_user_id,v_c.id,'refund',v_c.balance,v_parts.prize,v_parts.bounty,v_parts.fee,
    v_key,NULLIF(v_receipt->>'journal_id','')::uuid,v_ob,
    jsonb_build_object('kind',p_kind,'source',p_source,'request_id',p_request_id))
  RETURNING id INTO v_ledger;

  IF (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id))
     IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_tournament_id)::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_escrow_disagrees_with_custody' USING ERRCODE='P0404';
  END IF;
  RETURN jsonb_build_object('ok',true,'fully_settled',true,'remaining',0,'paid',v_c.balance,
    'refund_prize',v_parts.prize,'refund_bounty',v_parts.bounty,'refund_fee',v_parts.fee,
    'custody_id',v_c.id,'ledger_id',v_ledger,'obligation_id',v_ob,'journal_id',v_receipt->>'journal_id',
    'available_balance',v_receipt->>'available_balance');
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_seat_transfer(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_registration_id uuid, p_ticket numeric, p_prize numeric, p_fee numeric, p_seat_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sat record; v_target record; v_reg public.tournament_players%ROWTYPE;
  v_existing public.poker_diamond_tournament_ledger%ROWTYPE; v_e record;
  v_out_key text; v_in_key text; v_wallet bigint; v_journal uuid; v_custody uuid;
  v_request uuid; v_drained jsonb; v_out_ledger bigint; v_in_ledger bigint; v_receipt jsonb;
BEGIN
  IF p_satellite_id IS NULL OR p_target_id IS NULL OR p_user_id IS NULL OR p_registration_id IS NULL
     OR p_seat_key IS NULL OR length(btrim(p_seat_key)) = 0 OR length(p_seat_key) > 300
     OR p_ticket IS NULL OR p_prize IS NULL OR p_fee IS NULL
     OR p_ticket < 1 OR p_ticket > 2147483647 OR p_prize < 0 OR p_fee < 0
     OR p_ticket <> trunc(p_ticket) OR p_prize <> trunc(p_prize) OR p_fee <> trunc(p_fee)
     OR p_prize + p_fee <> p_ticket THEN
    RAISE EXCEPTION 'diamond_satellite_seat_requires_whole_parts' USING ERRCODE='22023';
  END IF;
  -- ASSETS NEVER CROSS: both ends of a Diamond seat are Diamond events.
  IF NOT public.fn_poker_diamond_tournament(p_satellite_id)
     OR NOT public.fn_poker_diamond_tournament(p_target_id) THEN
    RAISE EXCEPTION 'diamond_satellite_seat_requires_two_diamond_events: satellite % target %',
      p_satellite_id, p_target_id USING ERRCODE='23514';
  END IF;
  SELECT t.id, t.club_id, t.name, t.satellite_target_id, t.satellite_target
    INTO v_sat FROM public.tournaments t WHERE t.id=p_satellite_id;
  SELECT t.id, t.club_id, t.name, t.buy_in_amount, t.buy_in_fee, t.bounty_amount,
         t.is_bounty, t.is_pko, t.is_mystery_bounty
    INTO v_target FROM public.tournaments t WHERE t.id=p_target_id;
  IF COALESCE(v_sat.satellite_target_id, v_sat.satellite_target) IS DISTINCT FROM p_target_id THEN
    RAISE EXCEPTION 'diamond_satellite_seat_names_another_target' USING ERRCODE='23514';
  END IF;
  IF v_target.buy_in_amount IS DISTINCT FROM p_prize OR COALESCE(v_target.buy_in_fee,0) IS DISTINCT FROM p_fee
     OR COALESCE(v_target.bounty_amount,0) <> 0 OR v_target.is_bounty IS DISTINCT FROM false
     OR v_target.is_pko IS DISTINCT FROM false OR v_target.is_mystery_bounty IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'diamond_satellite_seat_is_not_the_target_entry' USING ERRCODE='23514';
  END IF;
  v_out_key := 'poker-tournament-seat-out:' || p_seat_key;
  v_in_key := 'poker-tournament-seat-in:' || p_seat_key;

  -- The same seat twice is the same seat: return what it wrote.
  SELECT * INTO v_existing FROM public.poker_diamond_tournament_ledger WHERE idempotency_key=v_in_key;
  IF FOUND THEN
    IF v_existing.user_id IS DISTINCT FROM p_user_id OR v_existing.tournament_id IS DISTINCT FROM p_target_id
       OR v_existing.amount IS DISTINCT FROM p_ticket::bigint
       OR v_existing.registration_id IS DISTINCT FROM p_registration_id THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch';
    END IF;
    RETURN jsonb_build_object('success',true,'idempotent',true,'custody_id',v_existing.custody_id,
      'target_ledger_id',v_existing.id,'journal_id',v_existing.wallet_journal_id,'amount',v_existing.amount);
  END IF;

  -- The registration the seat funds is the satellite's own qualifier row.
  SELECT * INTO v_reg FROM public.tournament_players tp WHERE tp.id=p_registration_id FOR UPDATE;
  IF NOT FOUND OR v_reg.tournament_id IS DISTINCT FROM p_target_id OR v_reg.user_id IS DISTINCT FROM p_user_id
     OR COALESCE(v_reg.is_satellite_qualifier,false) IS NOT TRUE
     OR v_reg.source_satellite_id IS DISTINCT FROM p_satellite_id THEN
    RAISE EXCEPTION 'diamond_satellite_seat_has_no_qualifier_registration' USING ERRCODE='23514';
  END IF;
  -- One funded entry per player per event, as the entry door holds it.
  IF EXISTS (SELECT 1 FROM public.poker_diamond_custody c
              WHERE c.user_id=p_user_id AND c.purpose='tournament_entry'
                AND c.target_id=p_target_id AND c.state<>'released') THEN
    RAISE EXCEPTION 'diamond_tournament_entry_already_held' USING ERRCODE='23505';
  END IF;
  SELECT * INTO v_e FROM public.fn_poker_diamond_tournament_escrow(p_satellite_id);
  IF v_e.prize_balance < p_ticket THEN
    RAISE EXCEPTION 'diamond_tournament_bank_short' USING ERRCODE='P0404';
  END IF;

  -- THE JOURNAL ROW THE MOVEMENTS CARRY. A custody movement names a journal
  -- row. This one moves no wallet: amount 0 at the unchanged balance, so the
  -- register (which follows no zero) does not move; its metadata names the
  -- Diamonds that moved between the two custody accounts, so the qualifier's
  -- own journal shows the seat.
  v_custody := gen_random_uuid();
  SELECT COALESCE(p.diamonds,0) INTO v_wallet FROM public.profiles p WHERE p.id=p_user_id FOR UPDATE;
  INSERT INTO public.diamond_transactions(user_id,type,transaction_type,amount,balance_after,
    reference_id,description,source,issuance_class,counterparty,metadata)
  VALUES (p_user_id,'tournament_satellite_seat','tournament_satellite_seat',0,v_wallet,
    'poker-tournament-satellite-seat:'||p_seat_key,
    'Satellite seat: '||p_ticket::bigint::text||' Diamonds moved from the prize bank of '
      ||COALESCE(v_sat.name,'the satellite')||' into your entry in '||COALESCE(v_target.name,'its target')
      ||' (your wallet did not move)',
    'poker_arena','arena','arena_custody:'||v_custody::text,
    jsonb_build_object('satellite_id',p_satellite_id,'target_id',p_target_id,'registration_id',p_registration_id,
      'custody_id',v_custody,'amount',p_ticket,'prize_part',p_prize,'fee_part',p_fee,'wallet_moved',0,
      'seat_key',p_seat_key))
  RETURNING id INTO v_journal;

  -- OUT: the whole ticket leaves the satellite's prize bank, oldest entry rows
  -- first, each drained row releasing its part to the new entry row.
  v_drained := public.fn_poker_diamond_tournament_drain(
    p_satellite_id, 'prize', p_ticket::bigint, v_out_key, 'arena_custody:'||v_custody::text, v_journal);
  INSERT INTO public.poker_diamond_tournament_ledger(
    tournament_id,arena_id,user_id,custody_id,kind,amount,prize_part,bounty_part,fee_part,
    idempotency_key,wallet_journal_id,registration_id,request)
  VALUES (p_satellite_id,v_sat.club_id,p_user_id,NULL,'prize',p_ticket::bigint,p_ticket::bigint,0,0,
    v_out_key,v_journal,NULL,
    jsonb_build_object('kind','prize','delivery','satellite_seat','seat_key',p_seat_key,'target_id',p_target_id,
      'registration_id',p_registration_id,'target_custody_id',v_custody,'drained',v_drained))
  RETURNING id INTO v_out_ledger;

  -- IN: the same Diamonds become the qualifier's funded entry in the target,
  -- ACTIVE from the moment it exists (the seat guards admit a Diamond seat
  -- only against an active entry) and never bound to a seat.
  INSERT INTO public.poker_diamond_custody(id,user_id,arena_id,purpose,target_id,entry_key,balance,state)
  VALUES (v_custody,p_user_id,v_target.club_id,'tournament_entry',p_target_id,
    'entry:'||p_registration_id::text,p_ticket::bigint,'active');
  v_request := uuid_in(md5(v_in_key)::cstring);
  v_receipt := jsonb_build_object('success',true,'custody_id',v_custody,'request_id',v_request,
    'amount',p_ticket,'custody_balance',p_ticket,'journal_id',v_journal,
    'source','tournament_prize_bank:'||p_satellite_id::text);
  INSERT INTO public.poker_diamond_movements(request_id,custody_id,user_id,action,amount,
    source_account,destination_account,wallet_journal_id,request,receipt)
  VALUES (v_request,v_custody,p_user_id,'reserve',p_ticket::bigint,
    'tournament_prize_bank:'||p_satellite_id::text,'arena_custody:'||v_custody::text,v_journal,
    jsonb_build_object('action','satellite_seat','satellite_id',p_satellite_id,'target_id',p_target_id,
      'user_id',p_user_id,'registration_id',p_registration_id,'amount',p_ticket,'seat_key',p_seat_key),
    v_receipt);
  INSERT INTO public.poker_diamond_tournament_ledger(
    tournament_id,arena_id,user_id,custody_id,kind,amount,prize_part,bounty_part,fee_part,
    idempotency_key,wallet_journal_id,registration_id,request)
  VALUES (p_target_id,v_target.club_id,p_user_id,v_custody,'entry',p_ticket::bigint,p_prize::bigint,0,p_fee::bigint,
    v_in_key,v_journal,p_registration_id,
    jsonb_build_object('kind','entry','source','satellite_seat','satellite_id',p_satellite_id,'gross',p_ticket,
      'prize',p_prize,'bounty',0,'fee',p_fee,'request_id',v_request,'seat_key',p_seat_key))
  RETURNING id INTO v_in_ledger;

  -- The first funded entry locks the target's entry contract, as the entry
  -- door locks it; an open target shadow follows the entry, as it follows one.
  UPDATE public.tournaments t SET entry_contract_locked=true
   WHERE t.id=p_target_id AND NOT t.entry_contract_locked;
  IF EXISTS (SELECT 1 FROM public.tournament_escrow x WHERE x.tournament_id=p_target_id) THEN
    PERFORM public.fn_ca_escrow_apply(p_target_id,'diamond satellite seat',
      p_gross_in => p_ticket, p_fee_entries_in => p_fee);
  END IF;

  -- Both events' banks agree with their custody after the move.
  IF (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_satellite_id))
       IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_satellite_id)::numeric
     OR (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_target_id))
       IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_target_id)::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_escrow_disagrees_with_custody' USING ERRCODE='P0404';
  END IF;
  RETURN jsonb_build_object('success',true,'custody_id',v_custody,'registration_id',p_registration_id,
    'amount',p_ticket,'prize',p_prize,'fee',p_fee,'journal_id',v_journal,'request_id',v_request,
    'satellite_ledger_id',v_out_ledger,'target_ledger_id',v_in_ledger,'drained',v_drained);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_settle_fee(p_tournament_id uuid, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_house constant uuid := '00000000-0000-0000-0000-00000000d1a0';
  v_arena uuid; v_e record; v_fee bigint; v_drained jsonb; v_before numeric; v_after numeric;
  v_supply numeric; v_key text; v_ledger bigint; v_name text; v_existing bigint; v_burned numeric;
BEGIN
  IF p_tournament_id IS NULL THEN RAISE EXCEPTION 'invalid_diamond_tournament_fee' USING ERRCODE='22023'; END IF;
  SELECT t.club_id, t.name INTO v_arena, v_name FROM public.tournaments t JOIN public.clubs c ON c.id=t.club_id
   WHERE t.id=p_tournament_id AND c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL AND t.union_id IS NULL;
  IF v_arena IS NULL THEN RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514'; END IF;
  v_key := 'poker-tournament-fee:'||p_tournament_id::text;
  SELECT id INTO v_existing FROM public.poker_diamond_tournament_ledger WHERE idempotency_key=v_key;
  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'already_settled',true,'amount',(SELECT amount FROM public.poker_diamond_tournament_ledger WHERE id=v_existing));
  END IF;
  SELECT * INTO v_e FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id);
  v_fee := v_e.fee_balance::bigint;
  IF v_fee <= 0 THEN
    RETURN jsonb_build_object('ok',true,'amount',0,'destination','none');
  END IF;

  -- Out of the fee parts of the custody rows: each player's own fee, retired
  -- from that player in the register by the drain itself. No wallet journal
  -- row: the fee left the wallet inside the entry's arena_deposit, and a
  -- second row is the double count of 2026-10-07 (20261007132503).
  v_drained := public.fn_poker_diamond_tournament_drain(p_tournament_id, 'fee', v_fee, v_key, 'house', NULL);
  SELECT COALESCE(sum(m.amount),0) INTO v_burned FROM public.ca_mint_ledger m
   WHERE m.asset='diamonds' AND m.action='burn' AND m.holder_type='player'
     AND m.op_id IN (SELECT d->>'register_op_id' FROM jsonb_array_elements(v_drained) d);
  IF v_burned IS DISTINCT FROM v_fee::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_fee_not_retired_from_players (% of %)', v_burned, v_fee USING ERRCODE='P0404';
  END IF;

  -- Into the house: the balance and the register, exactly as fn_ca_mint
  -- issues to the house (no house journal row: that journal is keyed by a
  -- user, and ca_mint_ledger is the record of a house-side issuance; the
  -- register's generated origin reads 'operator' for every non-journal op_id,
  -- as it does for fn_ca_mint's own house rows).
  INSERT INTO public.ca_diamond_house (id, balance) VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
  SELECT COALESCE(balance,0) INTO v_before FROM public.ca_diamond_house WHERE id=1 FOR UPDATE;
  UPDATE public.ca_diamond_house SET balance=COALESCE(balance,0)+v_fee, updated_at=now() WHERE id=1 RETURNING balance INTO v_after;
  SELECT COALESCE(SUM(CASE WHEN action='mint' THEN amount ELSE -amount END),0) INTO v_supply FROM public.ca_mint_ledger WHERE asset='diamonds';
  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount, balance_before, balance_after, supply_after, reason)
  VALUES
    (v_key, 'mint', 'diamonds', 'house', c_house, 'the house', v_fee, v_before, v_after, v_supply+v_fee,
     'Tournament entry fees banked to the house from the players'' custody ('||COALESCE(v_name,'tournament')||'), DR14 (poker_tournament_fee)');

  INSERT INTO public.poker_diamond_tournament_ledger(
    tournament_id,arena_id,user_id,custody_id,kind,amount,prize_part,bounty_part,fee_part,idempotency_key,request)
  VALUES (p_tournament_id,v_arena,NULL,NULL,'fee',v_fee,0,0,v_fee,v_key,
    jsonb_build_object('source',p_source,'drained',v_drained,'house_balance_after',v_after))
  RETURNING id INTO v_ledger;

  IF (SELECT prize_balance+bounty_balance+fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id))
     IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_tournament_id)::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_escrow_disagrees_with_custody' USING ERRCODE='P0404';
  END IF;
  RETURN jsonb_build_object('ok',true,'amount',v_fee,'destination','diamond_house','ledger_id',v_ledger,'house_balance_after',v_after);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_settle_overlay(p_tournament_id uuid, p_moment text, p_guarantee numeric)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_house constant uuid := '00000000-0000-0000-0000-00000000d1a0';
  v_t record; v_l record; v_g bigint; v_collected bigint; v_funded bigint; v_delta bigint; v_amount bigint;
  v_key text; v_n integer; v_share bigint; v_rest bigint; v_take bigint; v_i integer := 0;
  v_c public.poker_diamond_custody%ROWTYPE; v_wallet bigint; v_label text; v_register text;
  v_registers text[] := ARRAY[]::text[]; v_running numeric;
  v_req uuid; v_before numeric; v_after numeric; v_supply numeric; v_registered numeric;
  v_drained jsonb; v_d jsonb; v_open bigint;
BEGIN
  IF p_tournament_id IS NULL OR p_moment NOT IN ('lock','finalize') OR p_guarantee IS NULL
     OR p_guarantee < 0 OR p_guarantee <> trunc(p_guarantee) THEN
    RAISE EXCEPTION 'invalid_diamond_overlay_request' USING ERRCODE = '22023';
  END IF;
  IF NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE = '23514';
  END IF;
  SELECT t.id, t.club_id, t.name INTO v_t FROM public.tournaments t WHERE t.id = p_tournament_id;
  v_g := p_guarantee;
  SELECT COALESCE(sum(prize_part) FILTER (WHERE kind IN ('entry','rebuy','reentry','addon')),0)
           - COALESCE(sum(prize_part) FILTER (WHERE kind = 'refund'),0) AS collected,
         COALESCE(sum(amount) FILTER (WHERE kind = 'overlay'),0)
           - COALESCE(sum(amount) FILTER (WHERE kind = 'overlay_return'),0) AS funded
    INTO v_l FROM public.poker_diamond_tournament_ledger WHERE tournament_id = p_tournament_id;
  v_collected := v_l.collected; v_funded := v_l.funded;
  v_delta := GREATEST(v_g, v_collected) - (v_collected + v_funded);
  IF v_delta = 0 THEN RETURN 0; END IF;

  INSERT INTO public.ca_diamond_house (id, balance) VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
  SELECT COALESCE(h.balance, 0) INTO v_before FROM public.ca_diamond_house h WHERE h.id = 1 FOR UPDATE;
  SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END), 0) INTO v_supply
    FROM public.ca_mint_ledger m WHERE m.asset = 'diamonds';

  IF v_delta > 0 THEN
    v_amount := v_delta;
    v_key := 'poker-guarantee-overlay:' || p_tournament_id::text || ':' || p_moment;
    -- The promise was set aside at creation; it is kept from the earmark and
    -- from nothing else (A7). Ruling 21: no cap is read here.
    v_open := public.fn_ca_diamond_earmark_open('guarantee:' || p_tournament_id::text);
    IF v_open < v_amount THEN
      RAISE EXCEPTION 'diamond_guarantee_overlay_exceeds_its_earmark:% set aside, % needed', v_open, v_amount
        USING ERRCODE = '23514';
    END IF;
    IF v_before < v_amount THEN
      RAISE EXCEPTION 'diamond_house_cannot_pay_the_overlay:% held, % needed', v_before, v_amount
        USING ERRCODE = '23514';
    END IF;
    SELECT count(*) INTO v_n FROM public.poker_diamond_custody c
     WHERE c.purpose = 'tournament_entry' AND c.target_id = p_tournament_id AND c.state = 'active';
    IF v_n = 0 THEN
      RAISE EXCEPTION 'diamond_overlay_has_no_entry_to_hold_it' USING ERRCODE = '55000';
    END IF;
    UPDATE public.ca_diamond_house SET balance = balance - v_amount, updated_at = now()
     WHERE id = 1 RETURNING balance INTO v_after;
    INSERT INTO public.ca_mint_ledger
      (op_id, action, asset, holder_type, holder_id, holder_label, amount, balance_before, balance_after, supply_after, reason)
    VALUES (v_key, 'burn', 'diamonds', 'house', c_house, 'the house', v_amount, v_before, v_after, v_supply - v_amount,
      'Diamond guarantee overlay paid from the house into the event custody (' || COALESCE(v_t.name, 'tournament')
      || ', ' || p_moment || '), the guarantee set aside at creation');
    SET CONSTRAINTS public.zzz_diamond_entry_custody_is_the_entry IMMEDIATE;
    v_running := v_supply - v_amount;
    v_share := v_amount / v_n;
    v_rest := v_amount % v_n;
    FOR v_c IN SELECT c.* FROM public.poker_diamond_custody c
                WHERE c.purpose = 'tournament_entry' AND c.target_id = p_tournament_id AND c.state = 'active'
                ORDER BY c.created_at, c.id FOR UPDATE LOOP
      v_i := v_i + 1;
      v_take := v_share + CASE WHEN v_i <= v_rest THEN 1 ELSE 0 END;
      CONTINUE WHEN v_take = 0;
      -- THE SHARE LANDS IN CUSTODY, NEVER IN A WALLET, SO IT WRITES NO WALLET
      -- JOURNAL ROW (20261007132503). The register counts custody Diamonds as
      -- the player's, so it is minted to the player there, directly, with the
      -- wallet unchanged on both sides. A diamond_transactions credit here
      -- would tell the wallet it grew by Diamonds that are not in it.
      SELECT COALESCE(pr.diamonds, 0), COALESCE(NULLIF(btrim(pr.username), ''), pr.full_name, pr.id::text)
        INTO v_wallet, v_label FROM public.profiles pr WHERE pr.id = v_c.user_id;
      v_register := v_key || ':' || v_c.id::text;
      v_running := v_running + v_take;
      INSERT INTO public.ca_mint_ledger
        (op_id, action, asset, holder_type, holder_id, holder_label, amount, balance_before, balance_after, supply_after, reason)
      VALUES (v_register, 'mint', 'diamonds', 'player', v_c.user_id, COALESCE(v_label, v_c.user_id::text), v_take,
        v_wallet, v_wallet, v_running,
        'Diamond guarantee overlay paid by the house into this player''s entry custody: ' || COALESCE(v_t.name, 'tournament')
          || ' (' || p_moment || '). Paid out only as prizes; the wallet does not move.');
      v_registers := v_registers || v_register;
      v_req := uuid_in(md5(v_key || ':' || v_c.id::text)::cstring);
      INSERT INTO public.poker_diamond_movements(request_id, custody_id, user_id, action, amount,
        source_account, destination_account, wallet_journal_id, request, receipt)
      VALUES (v_req, v_c.id, v_c.user_id, 'reserve', v_take, 'house:' || c_house::text, 'arena_custody:' || v_c.id::text,
        NULL,
        jsonb_build_object('action', 'guarantee_overlay', 'bank', 'prize', 'tournament_id', p_tournament_id,
                           'custody_id', v_c.id, 'amount', v_take),
        jsonb_build_object('success', true, 'custody_id', v_c.id, 'amount', v_take,
                           'custody_balance', v_c.balance + v_take, 'journal_id', NULL, 'register_op_id', v_register));
      UPDATE public.poker_diamond_custody SET balance = balance + v_take WHERE id = v_c.id;
      INSERT INTO public.poker_diamond_tournament_ledger(tournament_id, arena_id, user_id, custody_id, kind, amount,
        prize_part, bounty_part, fee_part, idempotency_key, wallet_journal_id, request)
      VALUES (p_tournament_id, v_t.club_id, v_c.user_id, v_c.id, 'overlay', v_take, v_take, 0, 0,
        v_key || ':' || v_c.id::text, NULL,
        jsonb_build_object('kind', 'overlay', 'source', 'house', 'moment', p_moment, 'request_id', v_req,
                           'register_op_id', v_register));
    END LOOP;
    SET CONSTRAINTS public.zzz_diamond_entry_custody_is_the_entry DEFERRED;
    SELECT COALESCE(sum(m.amount), 0) INTO v_registered FROM public.ca_mint_ledger m
     WHERE m.asset = 'diamonds' AND m.action = 'mint' AND m.holder_type = 'player'
       AND m.op_id = ANY (v_registers);
    IF v_registered IS DISTINCT FROM v_amount::numeric THEN
      RAISE EXCEPTION 'diamond_overlay_not_registered_to_players (% of %)', v_registered, v_amount USING ERRCODE = 'P0404';
    END IF;
    INSERT INTO public.ca_diamond_house_earmarks (entry, earmark_key, purpose, amount, tournament_id, reason)
    VALUES ('pay', 'guarantee:' || p_tournament_id::text, 'guarantee', v_amount, p_tournament_id,
            'Guarantee overlay paid into the event custody at ' || p_moment);
    IF EXISTS (SELECT 1 FROM public.tournament_escrow x WHERE x.tournament_id = p_tournament_id) THEN
      PERFORM public.fn_ca_escrow_apply(p_tournament_id, 'diamond guarantee overlay', p_overlay_in => v_amount);
    END IF;
  ELSE
    v_amount := LEAST(-v_delta, v_funded);
    IF v_amount <= 0 THEN RETURN 0; END IF;
    v_key := 'poker-guarantee-overlay-return:' || p_tournament_id::text || ':' || p_moment;
    v_drained := public.fn_poker_diamond_tournament_drain(p_tournament_id, 'prize', v_amount, v_key, 'house', NULL);
    SELECT COALESCE(sum(m.amount), 0) INTO v_registered FROM public.ca_mint_ledger m
     WHERE m.asset = 'diamonds' AND m.action = 'burn' AND m.holder_type = 'player'
       AND m.op_id IN (SELECT d->>'register_op_id' FROM jsonb_array_elements(v_drained) d);
    IF v_registered IS DISTINCT FROM v_amount::numeric THEN
      RAISE EXCEPTION 'diamond_overlay_return_not_retired_from_players (% of %)', v_registered, v_amount USING ERRCODE = 'P0404';
    END IF;
    -- The drain has just retired v_amount from the players; the house mint's
    -- supply_after is read after it, as the fee settlement reads it.
    SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END), 0) INTO v_supply
      FROM public.ca_mint_ledger m WHERE m.asset = 'diamonds';
    UPDATE public.ca_diamond_house SET balance = balance + v_amount, updated_at = now()
     WHERE id = 1 RETURNING balance INTO v_after;
    INSERT INTO public.ca_mint_ledger
      (op_id, action, asset, holder_type, holder_id, holder_label, amount, balance_before, balance_after, supply_after, reason)
    VALUES (v_key, 'mint', 'diamonds', 'house', c_house, 'the house', v_amount, v_before, v_after, v_supply + v_amount,
      'Diamond guarantee overlay the entries made unnecessary returned from the event custody to the house ('
      || COALESCE(v_t.name, 'tournament') || ', ' || p_moment || ')');
    FOR v_d IN SELECT d.value FROM jsonb_array_elements(v_drained) d LOOP
      INSERT INTO public.poker_diamond_tournament_ledger(tournament_id, arena_id, user_id, custody_id, kind, amount,
        prize_part, bounty_part, fee_part, idempotency_key, wallet_journal_id, request)
      VALUES (p_tournament_id, v_t.club_id, (v_d->>'user_id')::uuid, (v_d->>'custody_id')::uuid, 'overlay_return',
        (v_d->>'amount')::bigint, (v_d->>'amount')::bigint, 0, 0,
        v_key || ':' || (v_d->>'custody_id'), NULL,
        jsonb_build_object('kind', 'overlay_return', 'destination', 'house', 'moment', p_moment,
                           'request_id', v_d->>'request_id', 'register_op_id', v_d->>'register_op_id'));
    END LOOP;
    IF EXISTS (SELECT 1 FROM public.tournament_escrow x WHERE x.tournament_id = p_tournament_id) THEN
      PERFORM public.fn_ca_escrow_apply(p_tournament_id, 'diamond guarantee overlay return', p_overlay_in => -v_amount);
    END IF;
    v_amount := -v_amount;
  END IF;

  IF (SELECT prize_balance + bounty_balance + fee_balance FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id))
     IS DISTINCT FROM public.fn_poker_diamond_tournament_custody(p_tournament_id)::numeric THEN
    RAISE EXCEPTION 'diamond_tournament_escrow_disagrees_with_custody' USING ERRCODE = 'P0404';
  END IF;
  RETURN v_amount;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_unregister(p_tournament_id uuid, p_user_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE; v_reg public.tournament_players%ROWTYPE;
  v_refund jsonb; v_players_before integer; v_rows integer;
  v_prior public.poker_diamond_tournament_ledger%ROWTYPE; v_prior_reg uuid; v_prior_after bigint;
  v_authority text := 'scheduled_clock';
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'tournament, player and request ids are required' USING ERRCODE='22004';
  END IF;
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;
  IF NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514';
  END IF;

  -- A withdrawal that already happened answers with what it did: the same
  -- receipt the first answer carried, rebuilt from the refund ledger row
  -- (its registration id from the entry row of the same custody), so the
  -- client's one exact replay after a lost response is a receipt. The chip
  -- authority replays its stored receipt the same way, past the clock too.
  -- DIAMOND PHASE 11: word for word - no replay marker, and the balance it
  -- reports is the one the refund left, read from the release's own
  -- immutable receipt (keyed by this request id), never the wallet as it
  -- stands at the retry.
  SELECT l.* INTO v_prior FROM public.poker_diamond_tournament_ledger l
   WHERE l.tournament_id=p_tournament_id AND l.user_id=p_user_id AND l.kind='refund'
     AND l.request->>'request_id'=p_request_id::text
   ORDER BY l.id LIMIT 1;
  IF FOUND THEN
    SELECT e.registration_id INTO v_prior_reg FROM public.poker_diamond_tournament_ledger e
     WHERE e.custody_id=v_prior.custody_id AND e.kind='entry'
     ORDER BY e.id LIMIT 1;
    SELECT (m.receipt->>'available_balance')::bigint INTO v_prior_after
      FROM public.poker_diamond_movements m
     WHERE m.request_id=p_request_id AND m.custody_id=v_prior.custody_id AND m.action='release';
    IF v_prior_after IS NULL THEN
      RAISE EXCEPTION 'diamond_tournament_refund_receipt_missing' USING ERRCODE='P0404';
    END IF;
    RETURN jsonb_build_object('ok',true,'fully_settled',true,'remaining',0,
      'request_id',p_request_id,
      'refunded_diamonds',v_prior.amount,'refund_prize',v_prior.prize_part,
      'refund_bounty',v_prior.bounty_part,'refund_fee',v_prior.fee_part,
      'registration_id',v_prior_reg,'custody_id',v_prior.custody_id,'obligation_id',v_prior.obligation_id,
      'asset','diamonds','diamonds_after',v_prior_after);
  END IF;

  -- The start authority is the chip authority's. A scheduled event closes at
  -- its clock. A spin or a heads-up sit-and-go is seat-first: start_time is
  -- only its fill-window deadline, and it closes when it actually starts. A
  -- launch releasing a registrant it could not seat names its incomplete
  -- receipt through app.ca_launch_release_launch_id; it is past the clock by
  -- design and is held to the seat-first proofs instead. A persisted hand
  -- closes every product.
  IF v_t.format_contract='spin-v1' THEN
    v_authority := 'spin_actual_start';
  ELSIF v_t.format_contract='sng-v1'
     AND COALESCE(v_t.max_players,0)=2 THEN
    v_authority := 'heads_up_sng_actual_start';
  END IF;
  IF v_authority='scheduled_clock' AND EXISTS (
       SELECT 1 FROM public.tournament_launch_receipts r
        WHERE r.tournament_id=p_tournament_id
          AND r.completed_at IS NULL
          AND r.launch_id::text=NULLIF(current_setting('app.ca_launch_release_launch_id',true),'')) THEN
    v_authority := 'launch_release';
  END IF;
  IF upper(COALESCE(v_t.status,'')) NOT IN ('ANNOUNCED','REGISTERING') OR v_t.started_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;
  PERFORM public.fn_ca_tournament_recorded_format(p_tournament_id);
  IF EXISTS (SELECT 1 FROM public.hand_history hh WHERE hh.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tables ht JOIN public.hand_history hh ON hh.table_id=ht.id
                 WHERE ht.tournament_id=p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;
  IF v_authority='scheduled_clock' THEN
    IF v_t.start_time IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','registration_schedule_unset');
    END IF;
    IF clock_timestamp()>=v_t.start_time THEN
      RETURN jsonb_build_object('ok',false,'reason','tournament_started');
    END IF;
  ELSIF EXISTS (SELECT 1 FROM public.tournament_launch_receipts r
                 WHERE r.tournament_id=p_tournament_id AND r.completed_at IS NOT NULL) THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;

  SELECT * INTO v_reg FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id FOR UPDATE;
  IF v_reg.id IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','not_registered'); END IF;
  IF v_reg.status::text NOT IN ('registered','playing') THEN
    RETURN jsonb_build_object('ok',false,'reason','not_registered');
  END IF;
  SELECT count(*)::integer INTO v_players_before FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.status::text IN ('registered','playing');

  -- Money first: the release is the part that can refuse.
  v_refund := public.fn_poker_diamond_tournament_refund(
    p_tournament_id, p_user_id, 'unregister', 'fn_unregister_from_tournament', p_request_id);

  -- The same roster effects the chip authority produces, in the same order.
  UPDATE public.table_seats s
     SET left_at=transaction_timestamp(),status='left',leave_pending=false,
         is_sitting_out=false,is_away=false,sit_out_at=NULL,scheduled_leave_hands=NULL
   WHERE s.user_id=p_user_id AND s.left_at IS NULL
     AND EXISTS(SELECT 1 FROM public.tables tb WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id);
  UPDATE public.tables tb
     SET current_players=(SELECT count(*) FROM public.table_seats s WHERE s.table_id=tb.id AND s.left_at IS NULL),
         updated_at=now()
   WHERE tb.tournament_id=p_tournament_id;
  DELETE FROM public.tournament_players tp WHERE tp.id=v_reg.id;
  UPDATE public.tournaments
     SET current_players=v_players_before-1,
         prize_pool=round(COALESCE(prize_pool,0)-(v_refund->>'refund_prize')::numeric,2),
         bounty_pool=round(COALESCE(bounty_pool,0)-(v_refund->>'refund_bounty')::numeric,2),
         total_rake=round(COALESCE(total_rake,0)-(v_refund->>'refund_fee')::numeric,2),
         updated_at=now()
   WHERE id=p_tournament_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'tournament vanished during unregistration' USING ERRCODE='55000'; END IF;
  RETURN jsonb_build_object('ok',true,'fully_settled',true,'remaining',0,'request_id',p_request_id,
    'refunded_diamonds',(v_refund->>'paid')::numeric,'refund_prize',(v_refund->>'refund_prize')::numeric,
    'refund_bounty',(v_refund->>'refund_bounty')::numeric,'refund_fee',(v_refund->>'refund_fee')::numeric,
    'registration_id',v_reg.id,'custody_id',v_refund->>'custody_id','obligation_id',v_refund->>'obligation_id',
    'asset','diamonds','diamonds_after',(v_refund->>'available_balance')::bigint);
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_guard_arena_structure()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_asset text;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    IF TG_OP='UPDATE' AND (NEW.asset,NEW.is_platform) IS DISTINCT FROM (OLD.asset,OLD.is_platform) THEN
      RAISE EXCEPTION 'Arena Asset Is Immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.asset='diamonds' AND auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false) THEN
      RAISE EXCEPTION 'Diamond Arena Requires Platform Operations' USING ERRCODE='42501';
    END IF;
    -- THE ARENA BELONGS TO THE SYSTEM (2026-09-30, decided by Claude on Dan's
    -- delegation): a Diamond club is owned by the system account, which nobody
    -- signs in as, so no door that trusts a club's owner admits a person to
    -- the arena. Platform staff run it through the staff doors.
    IF NEW.asset='diamonds' AND NEW.owner_id IS DISTINCT FROM '00000000-0000-0000-0000-000000000001'::uuid THEN
      RAISE EXCEPTION 'The Diamond Arena Belongs To The System' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT asset INTO v_asset FROM public.clubs WHERE id=NEW.club_id;
  IF TG_TABLE_NAME='club_members' AND TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
     AND EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset='diamonds') THEN
    RAISE EXCEPTION 'Diamond Participation Cannot Become A Chip Membership' USING ERRCODE='23514';
  END IF;
  -- Branch before resolving fields: membership rows do not have union_id.
  IF TG_TABLE_NAME IN ('tables','tournaments') THEN
    IF TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
       AND (EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset IS DISTINCT FROM v_asset)
         OR (OLD.club_id IS NULL AND OLD.union_id IS NOT NULL AND v_asset='diamonds')) THEN
      RAISE EXCEPTION 'Game Asset Is Immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF v_asset='diamonds' THEN
    IF TG_TABLE_NAME='club_members' THEN
      IF TG_OP='INSERT' OR NEW.role IS DISTINCT FROM 'player' OR NEW.status IS DISTINCT FROM 'automatic'
         OR NEW.agent_id IS NOT NULL OR NEW.parent_agent_id IS NOT NULL
         OR coalesce(NEW.chip_balance,0)<>0 OR coalesce(NEW.credit_limit,0)<>0
         OR coalesce(NEW.credit_used,0)<>0 OR coalesce(NEW.promo_balance,0)<>0
         OR coalesce(NEW.held_chips,0)<>0 THEN
        RAISE EXCEPTION 'Diamond Membership Is Automatic And Has No Chip Wallet Or Hierarchy' USING ERRCODE='23514';
      END IF;
    ELSIF TG_TABLE_NAME='union_clubs' THEN
      RAISE EXCEPTION 'Diamond Arena Cannot Join A Union' USING ERRCODE='23514';
    ELSIF auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false)
       -- DIAMOND PHASE 8: a player's entry, add-on and withdrawal move the
       -- play-state counters through the estate's doors; the structure is
       -- still platform operations only.
       AND NOT (TG_OP='UPDATE' AND TG_TABLE_NAME IN ('tournaments','tables')
                -- DIAMOND PHASE 11: a stored generated column is NULL in NEW before
                -- the row is written, and follows the base columns compared here; it
                -- is left out, or a player's buy-in reads as a structural change.
                AND (to_jsonb(NEW) - public.fn_poker_diamond_play_state_columns(TG_TABLE_NAME)
                       - ARRAY(SELECT a.attname::text FROM pg_catalog.pg_attribute a
                                WHERE a.attrelid = TG_RELID AND a.attgenerated <> '' AND NOT a.attisdropped))
                  = (to_jsonb(OLD) - public.fn_poker_diamond_play_state_columns(TG_TABLE_NAME)
                       - ARRAY(SELECT a.attname::text FROM pg_catalog.pg_attribute a
                                WHERE a.attrelid = TG_RELID AND a.attgenerated <> '' AND NOT a.attisdropped))) THEN
      RAISE EXCEPTION 'Diamond Games Require Platform Operations' USING ERRCODE='42501';
    ELSIF NEW.union_id IS NOT NULL THEN
      RAISE EXCEPTION 'Diamond Games Cannot Belong To A Union' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_guard_chip_seat()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
     WHERE t.id=NEW.table_id AND c.asset='diamonds') THEN RETURN NEW; END IF;
 IF (SELECT t.tournament_id FROM public.tables t WHERE t.id=NEW.table_id) IS NULL THEN
   /* A CASH SEAT IS ITS CUSTODY. The stack a player sits down with IS the
      Diamonds held for that seat, which is why a cash-out can pay the stack.
      This block is the live rule, unchanged. */
   IF TG_OP<>'INSERT' OR NOT EXISTS (
     SELECT 1 FROM public.poker_diamond_custody c
       JOIN public.ca_arena_settings a ON a.club_id=c.arena_id AND a.id=1
     WHERE c.user_id=NEW.user_id AND c.target_id=NEW.table_id AND c.purpose='cash_seat'
       AND c.entry_key='seat:'||NEW.id AND c.state='reserved' AND c.balance=NEW.stack
       AND c.seat_id IS NULL AND a.cash_games_enabled
   ) THEN
     RAISE EXCEPTION 'Diamond Seat Requires Atomic Custody Funding' USING ERRCODE='23514';
   END IF;
 ELSE
   /* A TOURNAMENT SEAT IS NOT ITS CUSTODY. The stack is a nonredeemable play
      unit; the money is the ENTRY, held against the tournament. So the seat is
      admitted by a funded live entry and by NO equation with the stack. */
   IF NOT EXISTS (
     SELECT 1 FROM public.tables t
       JOIN public.poker_diamond_custody c ON c.target_id=t.tournament_id
        AND c.user_id=NEW.user_id AND c.arena_id=t.club_id
        AND c.purpose='tournament_entry' AND c.state='active' AND c.seat_id IS NULL
       JOIN public.ca_arena_settings a ON a.club_id=c.arena_id AND a.id=1
     WHERE t.id=NEW.table_id AND a.tournaments_enabled
   ) THEN
     RAISE EXCEPTION 'Diamond Tournament Seat Requires A Funded Entry' USING ERRCODE='P0810';
   END IF;
   /* One entry buys one event. Balancing may move the seat from table to table
      inside that event, and nowhere else. */
   IF TG_OP='UPDATE' THEN
     IF (SELECT t.tournament_id FROM public.tables t WHERE t.id=OLD.table_id)
        IS DISTINCT FROM (SELECT t.tournament_id FROM public.tables t WHERE t.id=NEW.table_id) THEN
       RAISE EXCEPTION 'A Diamond Tournament Seat Moves Only Inside Its Own Tournament'
         USING ERRCODE='P0811';
     END IF;
   END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_register_for_tournament_before_atomic_capacity_20260907(p_tournament_id uuid, p_seat_first_internal boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_original_entitlement uuid; v_original_wallet uuid;
  v_uid uuid := auth.uid();
  v_unit integer := public.fn_ca_tournament_unit_cents(p_tournament_id);  -- DIAMOND PHASE 8
  v_dia jsonb;                                                              -- DIAMOND PHASE 8
  v_t record; v_username text;
  v_split record;
  v_is_bounty boolean; v_head numeric := 0;
  v_player_id uuid;
  v_late_open boolean := false; v_ok boolean;
  v_start_chips integer := 0;
  v_players_before integer;
  v_expected_cached_players integer;
  v_rows integer;
  v_seat jsonb := NULL;                                  -- LATE SEAT 2026-08-23
  v_seat_reason text;                                    -- SEAT FIX 2026-08-27
  v_led_cat text; v_led_cp text; v_led_ent text; v_led_tid text; -- CHIP STANDARD 1.2 2026-09-02
BEGIN
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_register_for_tournament requires an authenticated caller' USING ERRCODE = '28000';
  END IF;
  SELECT id, status, buy_in_amount, buy_in_fee, max_players, current_players,
         late_reg_levels, late_reg_mins, current_level, started_at, club_id, name, prize_pool_finalized,
         is_bounty, is_pko, is_mystery_bounty, bounty_amount,
         start_time, authorized_to_register, is_vip_only, early_bird_enabled, early_bird_chips,
         variant
    INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;

  -- SEAT-FIRST GUARD 2026-08-27, REBUILT 2026-08-28. A seat-first event is
  -- bought by taking a seat; registering into one debits the player for a
  -- seat that is never allocated. But the seat path ITSELF registers the
  -- player through this function, so the guard admits that caller via
  -- p_seat_first_internal - the original guard refused it too and no human
  -- could buy a Spin or Heads-Up seat at all. And the predicate is now the
  -- CANONICAL seat-first test (variant 'spin' OR a positive max_players <= 2), matching
  -- fn_take_seat_and_buy_in and fn_sync_seat_first_player_count: the original
  -- blocked ALL sngs, which left 6-max and 9-max SNGs with no entry path in
  -- either door.
  IF NOT p_seat_first_internal
     AND NOT public.fn_ca_tournament_is_unlimited(p_tournament_id)
     AND (lower(COALESCE(v_t.variant, '')) = 'spin'
       OR (v_t.max_players IS NOT NULL
         AND v_t.max_players > 0 AND v_t.max_players <= 2)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_first_variant',
      'detail', 'This format is entered by taking a seat, not by registering. '
                || 'Call fn_take_seat_and_buy_in for the seat you want.',
      'variant', v_t.variant);
  END IF;

  IF v_t.status = 'RUNNING' THEN
    v_late_open:=public.fn_tournament_late_registration_open(p_tournament_id);
  END IF;
  IF v_t.status NOT IN ('ANNOUNCED', 'REGISTERING') AND NOT v_late_open THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'registration_closed');
  END IF;
  SELECT count(*)::integer INTO v_players_before
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status::text IN ('registered','playing');
  IF v_t.current_players IS DISTINCT FROM v_players_before THEN
    RAISE EXCEPTION
      'Tournament roster cache diverged before registration (cached %, actual %)',
      v_t.current_players,v_players_before
      USING ERRCODE='P0404';
  END IF;
  IF NOT public.fn_ca_tournament_is_unlimited(p_tournament_id)
     AND v_t.max_players IS NOT NULL AND v_t.max_players > 0
     AND v_players_before >= v_t.max_players THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_full');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players WHERE tournament_id = p_tournament_id AND user_id = v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_registered');
  END IF;

  -- PARITY GATE 1 (2026-08-22): owner-approved registration list.
  IF COALESCE(v_t.authorized_to_register, false) THEN
    IF NOT EXISTS (SELECT 1 FROM public.tournament_registration_approvals a
                    WHERE a.tournament_id = p_tournament_id AND a.user_id = v_uid)
       AND NOT public.is_club_admin(v_t.club_id, v_uid) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized_to_register');
    END IF;
  END IF;

  -- PARITY GATE 2 (2026-08-22): VIP-only events.
  IF COALESCE(v_t.is_vip_only, false) THEN
    IF NOT EXISTS (SELECT 1 FROM public.profiles pr
                    WHERE pr.id = v_uid AND COALESCE(pr.is_vip, false)
                      AND (pr.vip_expires_at IS NULL OR pr.vip_expires_at > now()))
       AND NOT EXISTS (SELECT 1 FROM public.club_members m
                        WHERE m.club_id = v_t.club_id AND m.user_id = v_uid
                          AND m.role IN ('owner', 'co_owner', 'admin', 'agent')) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'vip_only');
    END IF;
  END IF;

  -- PARITY 3 (2026-08-22): early bird bonus chips for pre-start registration.
  IF COALESCE(v_t.early_bird_enabled, false)
     AND now() < v_t.start_time
     AND COALESCE(v_t.early_bird_chips, 0) > 0 THEN
    v_start_chips := v_t.early_bird_chips;
  END IF;

  SELECT COALESCE(NULLIF(display_name, ''), NULLIF(username, ''), 'Player')
    INTO v_username FROM public.profiles WHERE id = v_uid;

  v_is_bounty := COALESCE(v_t.is_bounty, false) OR COALESCE(v_t.is_pko, false)
                 OR COALESCE(v_t.is_mystery_bounty, false);

  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_is_bounty);

  IF v_is_bounty AND v_split.prize < 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'misconfigured_bounty',
      'detail', format('bounty %s + rake %s exceeds buy-in %s',
                       v_split.bounty, v_split.rake, v_split.charge));
  END IF;

  -- MYSTERY BOUNTY 2026-08-25: every bounty format puts the flat bounty on
  -- the head; the mystery value is drawn from a funded inventory at the
  -- knockout, not from a seeded PRNG at the till.
  IF v_is_bounty THEN
    v_head := v_split.bounty;
  END IF;

  IF v_split.charge > 0 AND v_unit = 100 THEN
    -- DIAMOND PHASE 8: a Diamond entry is custody, not a club-wallet debit. The
    -- roster row is written first so the custody row can name it; the whole
    -- transaction still rolls back together.
    IF v_split.charge <> trunc(v_split.charge) OR v_split.prize <> trunc(v_split.prize)
       OR v_split.rake <> trunc(v_split.rake) OR v_split.bounty <> trunc(v_split.bounty) THEN
      RAISE EXCEPTION 'diamond_tournament_requires_whole_amounts' USING ERRCODE = '23514';
    END IF;
    v_player_id := gen_random_uuid();
    BEGIN
      v_dia := public.fn_poker_diamond_tournament_charge(
        v_uid, p_tournament_id, 'entry', v_split.charge, v_split.prize, v_split.bounty, v_split.rake,
        v_player_id, 'poker-tournament-entry:' || p_tournament_id::text || ':' || v_uid::text || ':' || v_player_id::text);
    EXCEPTION WHEN OTHERS THEN
      -- DIAMOND PHASE 8: an ordinary refusal is answered the way the chip core
      -- answers one, with a reason the client can say; anything else is raised.
      IF SQLERRM LIKE '%insufficient_settled_diamonds%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_diamonds');
      ELSIF SQLERRM LIKE '%diamond_tournaments_not_open%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'diamond_tournaments_not_open');
      ELSIF SQLERRM LIKE '%diamond_debt_requires_settlement%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'diamond_debt_requires_settlement');
      ELSIF SQLERRM LIKE '%diamond_tournament_entry_already_held%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'already_registered');
      END IF;
      RAISE;
    END;
  ELSIF v_split.charge = 0 AND v_unit = 100 THEN
    -- 2026-10-06 (20261007000010): A DIAMOND FREEROLL ENTRY. Nothing is
    -- charged; the entry is an active custody row at zero, so the seat guards
    -- (P0810, P0812) admit the seat and a one-Diamond rebuy or add-on has an
    -- entry to land in. A horse enters through this same arm (CLAUDE.md 10.5).
    v_player_id := gen_random_uuid();
    BEGIN
      v_dia := public.fn_poker_diamond_tournament_free_entry(v_uid, p_tournament_id, v_player_id);
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM LIKE '%diamond_tournaments_not_open%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'diamond_tournaments_not_open');
      ELSIF SQLERRM LIKE '%diamond_tournament_entry_already_held%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'already_registered');
      END IF;
      RAISE;
    END;
  ELSIF v_split.charge > 0 THEN
    -- CHIP STANDARD 1.2 (2026-09-02): THE REGISTRATION DEBIT NAMES ITS COUNTERPARTY.
    -- trg_club_members_audit_chip_movement journals the wallet write below; with no
    -- declaration it landed as adjustment player_wallet -> table_stack with no
    -- tournament_id (19,538 rows / 407,412.00 a day). Declared with set_config, not
    -- fn_ca_declare_ledger, so a vocabulary miss can never refuse a buy-in (the
    -- writer falls back to adjustment on its own). The whole charge (prize + bounty
    -- + fee) is ONE wallet write and so ONE row, booked against the tournament
    -- (prize_liability) that holds all three until it completes. The four settings
    -- are restored right after so nothing later in this transaction inherits them.
    v_led_cat := current_setting('app.ledger_category', true);
    v_led_cp  := current_setting('app.ledger_counterparty', true);
    v_led_ent := current_setting('app.ledger_counterparty_entity', true);
    v_led_tid := current_setting('app.ledger_tournament', true);
    PERFORM set_config('app.ledger_category', 'tournament_buyin', true);
    PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_tournament_id::text, true);
    PERFORM set_config('app.ledger_tournament', p_tournament_id::text, true);
    PERFORM set_config('app.pnl_tournament_entitlement','',true);
    v_ok := public.atomic_deduct_wallet_and_log(
      v_uid, v_split.charge, 'tournament_buyin',
      'Tournament buy-in: ' || COALESCE(v_t.name, 'tournament') ||
        CASE WHEN v_is_bounty
             THEN ' (' || v_split.prize || ' prize + ' || v_split.bounty || ' bounty + ' || v_split.rake || ' fee)'
             WHEN v_split.rake > 0
             THEN ' (' || v_split.prize || ' + ' || v_split.rake || ' fee)'
             ELSE '' END,
      NULL, NULL, p_tournament_id);
    v_original_entitlement:=NULLIF(current_setting('app.pnl_tournament_entitlement',true),'')::uuid;
    PERFORM set_config('app.ledger_category', COALESCE(v_led_cat, ''), true);
    PERFORM set_config('app.ledger_counterparty', COALESCE(v_led_cp, ''), true);
    PERFORM set_config('app.ledger_counterparty_entity', COALESCE(v_led_ent, ''), true);
    PERFORM set_config('app.ledger_tournament', COALESCE(v_led_tid, ''), true);
    IF NOT COALESCE(v_ok, false) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_balance');
    END IF;
    PERFORM public.log_wallet_transaction(
      v_uid, 'PLAYER', v_split.charge, 'debit', 'tournament_buyin',
      'Tournament buy-in: ' || COALESCE(v_t.name, 'tournament'),
      NULL, NULL, p_tournament_id);
    v_original_wallet:=NULLIF(current_setting('app.pnl_tournament_wallet_tx',true),'')::uuid;
  END IF;

  BEGIN
    IF v_dia IS NOT NULL THEN
      -- DIAMOND PHASE 8: the roster row carries the id the custody row was named with.
      -- DIAMOND PHASE 9: the head rides on the roster row as it does for a
      -- chip entry, so the roster trigger does not seed it a second time.
      INSERT INTO public.tournament_players
        (id, tournament_id, user_id, username, chips, status, current_bounty, mystery_bounty_value, bounties_collected, bounty_winnings)
      VALUES (v_player_id, p_tournament_id, v_uid, COALESCE(v_username,'Player'), v_start_chips, 'registered',
              v_head, 0, 0, 0)
      RETURNING id INTO v_player_id;
    ELSIF v_is_bounty THEN
      INSERT INTO public.tournament_players
        (tournament_id, user_id, username, chips, status, current_bounty, mystery_bounty_value, bounties_collected, bounty_winnings)
      VALUES (p_tournament_id, v_uid, COALESCE(v_username,'Player'), v_start_chips, 'registered', v_head, 0, 0, 0)
      RETURNING id INTO v_player_id;
    ELSE
      INSERT INTO public.tournament_players (tournament_id, user_id, username, chips, status)
      VALUES (p_tournament_id, v_uid, COALESCE(v_username,'Player'), v_start_chips, 'registered')
      RETURNING id INTO v_player_id;
    END IF;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION
      'Tournament registration identity changed after its atomic debit; retry the complete transaction'
      USING ERRCODE = '55000';
  END;

  IF v_split.rake > 0 AND v_t.club_id IS NOT NULL AND v_unit = 1 THEN
    -- DIAMOND PHASE 8: a Diamond fee stays in custody until the event settles;
    -- rake_records is the chip estate's fee rail.
    INSERT INTO public.rake_records
      (hand_id, table_id, club_id, rake_amount, pot_size, num_players, bbj_contribution,
       is_tournament, tournament_id, source, metadata)
    VALUES (NULL, NULL, v_t.club_id, v_split.rake, v_split.charge, 1, 0, true, p_tournament_id,
            'fn_register_for_tournament',
            jsonb_build_object('kind','tournament_entry_fee','user_id',v_uid,'registration_id',v_player_id));
  END IF;

  -- The roster trigger already writes the exact count while an event is
  -- ANNOUNCED/REGISTERING, but deliberately leaves RUNNING counts to the
  -- transaction that also seats the late entrant. Incrementing the cached
  -- value here therefore double-counted every pre-start entry. Require the
  -- exact state produced by that trigger (or the unchanged RUNNING state),
  -- then publish one roster-derived value together with the funded pools.
  v_expected_cached_players:=CASE
    WHEN v_t.status IN ('ANNOUNCED','REGISTERING') THEN v_players_before+1
    ELSE v_players_before
  END;
  UPDATE public.tournaments
     SET current_players = v_players_before + 1,
         prize_pool  = COALESCE(prize_pool, 0)  + v_split.prize,
         bounty_pool = COALESCE(bounty_pool, 0) + v_split.bounty,
         total_rake  = COALESCE(total_rake, 0)  + v_split.rake
   WHERE id = p_tournament_id
     AND current_players IS NOT DISTINCT FROM v_expected_cached_players;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION
      'Tournament roster cache changed during registration'
      USING ERRCODE='55000';
  END IF;

  -- LATE SEAT 2026-08-23
  IF v_late_open THEN
    v_seat := public.fn_seat_late_registrant(p_tournament_id, v_uid);

    -- SEAT FIX 2026-08-27: a late registrant who cannot be seated must not be
    -- charged; abort so debit, roster row, rake record and pool increments
    -- roll back together. 'already_seated_or_missing' is NOT a failure.
    v_seat_reason := v_seat->>'reason';
    IF NOT COALESCE((v_seat->>'ok')::boolean, false)
       AND COALESCE(v_seat_reason, '') <> 'already_seated_or_missing' THEN
      RAISE EXCEPTION
        'Late registration could not seat the player (%) - no charge has been made',
        COALESCE(v_seat_reason, 'unknown')
        USING ERRCODE = '55000';
    END IF;
  END IF;

  PERFORM public.fn_ca_record_tournament_participant_funding(v_player_id,'entry',NULL,
    v_split.charge,CASE WHEN v_unit=100 THEN 'diamonds' ELSE 'chips' END,
    v_original_entitlement,v_original_wallet,v_dia);

  RETURN jsonb_build_object('ok', true, 'registration_id', v_player_id,
    'cost', v_split.charge, 'prize_contribution', v_split.prize,
    'bounty_contribution', v_split.bounty, 'rake', v_split.rake,
    'bounty_head', CASE WHEN v_head > 0 THEN v_head END,
    'early_bird_chips', CASE WHEN v_start_chips > 0 THEN v_start_chips END,
    'late_registration', v_late_open,                    -- LATE SEAT 2026-08-23
    -- DIAMOND PHASE 8: the receipt names its asset and, for a Diamond entry,
    -- the wallet after the charge, so the client can move the balance it shows.
    'asset', CASE WHEN v_dia IS NOT NULL THEN 'diamonds' ELSE 'chips' END,
    'diamonds_after', CASE WHEN v_dia IS NOT NULL THEN (SELECT p.diamonds FROM public.profiles p WHERE p.id = v_uid) END,
    'seat', v_seat);                                     -- LATE SEAT 2026-08-23
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_register_horse_for_tournament(p_tournament_id uuid, p_user_id uuid, p_allow_wallet_charge boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_gate jsonb;
  v_paying uuid;
  v_result jsonb;
BEGIN
  -- 20261005224736 / A18 (horse_entry_funding, recorded 2026-10-05) and
  -- CLAUDE.md 10.5 (HORSES ARE PLAYERS - NO EXCEPTIONS). The owner's answer
  -- reads: "a horse funds its Diamond entry from its own balance, through the
  -- ordinary Diamond registration door a person uses." So this is no longer a
  -- blanket refusal resting on a Phase-9 assumption; it is that answer, READ
  -- AT CALL TIME. Changing the answer is one INSERT into ca_diamond_economics
  -- and no code change - 'own_balance' is never hard-coded as the decision.
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    DECLARE
      v_horse_entry_funding text;
    BEGIN
      BEGIN
        v_horse_entry_funding :=
          public.fn_ca_diamond_economic_text('horse_entry_funding','all');
      EXCEPTION WHEN SQLSTATE 'P0D01' THEN
        -- No answer recorded. Refuse by name below rather than guess which
        -- funding the owner meant.
        v_horse_entry_funding := NULL;
      END;
      IF v_horse_entry_funding = 'funding_account' THEN
        -- House money, and there is no funding path for it yet. Refused by
        -- name, and the reason names the setting that produced the refusal.
        RETURN jsonb_build_object('ok',false,
          'reason','diamond_horse_funding_account_not_open',
          'horse_entry_funding',v_horse_entry_funding);
      ELSIF v_horse_entry_funding IS DISTINCT FROM 'own_balance' THEN
        RETURN jsonb_build_object('ok',false,
          'reason','diamond_horse_entry_funding_unrecognised',
          'horse_entry_funding',v_horse_entry_funding);
      END IF;
      -- 'own_balance': fall through. The horse takes the same seat-acquisition
      -- lock and the same registration chain a person takes, and pays from its
      -- own profiles.diamonds through the same Diamond door (10.5).
    END;
  END IF;
  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    p_tournament_id,NULL,p_user_id);
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;
  /* THE WALLET THAT CAN PAY (2026-10-12), exactly as the person's door
     (fn_register_for_tournament) does it - CLAUDE.md 10.5, a horse is
     charged by the same rule. Only when this entry is paid from a wallet. */
  IF COALESCE(p_allow_wallet_charge, false) THEN
    v_paying := public.fn_ca_entry_paying_club(p_user_id, p_tournament_id);
    IF v_paying IS NOT NULL THEN
      PERFORM set_config('app.ca_entry_paying_club',
        p_tournament_id::text || ':' || p_user_id::text || ':' || v_paying::text, true);
    END IF;
  END IF;
  v_result := public.fn_register_horse_for_tournament_before_terminal_gate(
    p_tournament_id,p_user_id,p_allow_wallet_charge);
  PERFORM set_config('app.ca_entry_paying_club', '', true);
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_register_horse_for_tournament_before_atomic_lifecycle_gate(p_tournament_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  BEGIN
    v_result := public.fn_register_horse_for_tournament_before_maintenance_gate(
      p_tournament_id, p_user_id);
  EXCEPTION WHEN SQLSTATE '55000' THEN
    IF SQLERRM NOT LIKE 'Late registration could not seat the player (%)%' THEN
      RAISE;
    END IF;
    PERFORM public.fn_ensure_late_registration_capacity(p_tournament_id, 1);
    v_result := public.fn_register_horse_for_tournament_before_maintenance_gate(
      p_tournament_id, p_user_id);
  END;

  IF COALESCE((v_result->>'ok')::boolean, false)
     AND COALESCE((v_result->>'late_registration')::boolean, false) THEN
    PERFORM public.fn_emit_tournament_manager_wake(p_tournament_id, 'late_registration');
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_register_horse_for_tournament_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_original_entitlement uuid; v_original_wallet uuid;
  -- 20261005224736 / A18 'own_balance' + CLAUDE.md 10.5: a Diamond entry is
  -- custody, exactly as it is for a person. The unit decides the asset, read
  -- from the same function the human door reads it from.
  v_unit integer := public.fn_ca_tournament_unit_cents(p_tournament_id);
  v_dia jsonb;
  v_t record; v_username text;
  v_split record;
  v_is_bounty boolean; v_head numeric := 0;
  v_player_id uuid;
  v_is_horse boolean;
  v_ok boolean;
  v_late_open boolean := false;
  v_start_chips integer := 0;
  v_players_before integer;
  v_expected_cached_players integer;
  v_rows integer;
  v_seat jsonb := NULL;
  v_seat_reason text;
  v_led_cat text; v_led_cp text; v_led_ent text; v_led_tid text; -- CHIP STANDARD 1.2 2026-09-02
BEGIN
  SELECT is_horse INTO v_is_horse FROM public.profiles WHERE id = p_user_id;
  IF NOT COALESCE(v_is_horse, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_horse');
  END IF;

  SELECT id, status, buy_in_amount, buy_in_fee, max_players, current_players,
         club_id, name, is_bounty, is_pko, is_mystery_bounty,
         bounty_amount, start_time, early_bird_enabled, early_bird_chips,
         prize_pool_finalized
    INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;

  -- THE HUMAN DOOR'S STATUS TEST (2026-09-11). A finalized pool takes no
  -- entrant and says so as a reason; a RUNNING event admits an entrant while
  -- its late registration is open, exactly as fn_register_for_tournament does.
  IF COALESCE(v_t.prize_pool_finalized, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'registration_closed');
  END IF;
  IF v_t.status = 'RUNNING' THEN
    v_late_open := public.fn_tournament_late_registration_open(p_tournament_id);
  END IF;
  IF v_t.status NOT IN ('ANNOUNCED', 'REGISTERING') AND NOT v_late_open THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'registration_closed');
  END IF;

  SELECT count(*)::integer INTO v_players_before
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status::text IN ('registered','playing');
  IF v_t.current_players IS DISTINCT FROM v_players_before THEN
    RAISE EXCEPTION
      'Tournament roster cache diverged before horse registration (cached %, actual %)',
      v_t.current_players,v_players_before
      USING ERRCODE='P0404';
  END IF;
  /* ONE DEFINITION OF FULL (2026-09-06). This read `current_players >=
     max_players`, and on a seat-first event that column is overwritten with
     the live SEATED count - so an emptied seat read as a vacancy and this
     function walked back through the door, up to 32 paid entries into a
     two-handed sit-and-go. fn_enforce_tournament_capacity is the authority
     and would now refuse the insert outright; asking here keeps the refusal a
     reason rather than an exception, and rolls back nothing. */
  IF public.fn_tournament_entry_cap_reached(p_tournament_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_full');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players
              WHERE tournament_id = p_tournament_id AND user_id = p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_registered');
  END IF;

  IF COALESCE(v_t.early_bird_enabled, false)
     AND now() < v_t.start_time
     AND COALESCE(v_t.early_bird_chips, 0) > 0 THEN
    v_start_chips := v_t.early_bird_chips;
  END IF;

  SELECT COALESCE(NULLIF(display_name, ''), NULLIF(username, ''), 'Player')
    INTO v_username FROM public.profiles WHERE id = p_user_id;

  v_is_bounty := COALESCE(v_t.is_bounty, false) OR COALESCE(v_t.is_pko, false)
                 OR COALESCE(v_t.is_mystery_bounty, false);

  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_is_bounty);

  IF v_is_bounty AND v_split.prize < 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'misconfigured_bounty');
  END IF;

  -- MYSTERY BOUNTY 2026-08-25: no roll here either. A horse and a human must
  -- enter the same event on the same terms; when the two register functions
  -- disagreed about how a bounty head was set, they were two tournaments.
  IF v_is_bounty THEN
    v_head := v_split.bounty;
  END IF;

  IF v_split.charge > 0 AND v_unit = 100 THEN
    -- 20261005224736 / A18 'own_balance' + 10.5: THE HORSE PAYS THROUGH THE
    -- DOOR THE PERSON PAYS THROUGH. This arm is the human door's Diamond arm
    -- statement for statement, with the horse's own id in place of auth.uid().
    -- A Diamond entry is custody, not a club-wallet debit; the roster row is
    -- written after the charge and carries the id the custody row was named
    -- with. The horse's Diamonds are its own (profiles.diamonds, ruling 9) -
    -- no house money reaches this path, and the chip treasury funder (a
    -- chip account ruling 16 forbids in a Diamond format) is never called.
    IF v_split.charge <> trunc(v_split.charge) OR v_split.prize <> trunc(v_split.prize)
       OR v_split.rake <> trunc(v_split.rake) OR v_split.bounty <> trunc(v_split.bounty) THEN
      RAISE EXCEPTION 'diamond_tournament_requires_whole_amounts' USING ERRCODE = '23514';
    END IF;
    v_player_id := gen_random_uuid();
    BEGIN
      v_dia := public.fn_poker_diamond_tournament_charge(
        p_user_id, p_tournament_id, 'entry', v_split.charge, v_split.prize, v_split.bounty, v_split.rake,
        v_player_id, 'poker-tournament-entry:' || p_tournament_id::text || ':' || p_user_id::text || ':' || v_player_id::text);
    EXCEPTION WHEN OTHERS THEN
      -- An ordinary refusal is answered the way the chip core answers one,
      -- with a reason the caller can say; anything else is raised.
      IF SQLERRM LIKE '%insufficient_settled_diamonds%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_diamonds');
      ELSIF SQLERRM LIKE '%diamond_tournaments_not_open%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'diamond_tournaments_not_open');
      ELSIF SQLERRM LIKE '%diamond_debt_requires_settlement%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'diamond_debt_requires_settlement');
      ELSIF SQLERRM LIKE '%diamond_tournament_entry_already_held%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'already_registered');
      END IF;
      RAISE;
    END;
  ELSIF v_split.charge = 0 AND v_unit = 100 THEN
    -- 2026-10-06 (20261007000010): A DIAMOND FREEROLL ENTRY. Nothing is
    -- charged; the entry is an active custody row at zero, so the seat guards
    -- (P0810, P0812) admit the seat and a one-Diamond rebuy or add-on has an
    -- entry to land in. A horse enters through this same arm (CLAUDE.md 10.5).
    v_player_id := gen_random_uuid();
    BEGIN
      v_dia := public.fn_poker_diamond_tournament_free_entry(p_user_id, p_tournament_id, v_player_id);
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM LIKE '%diamond_tournaments_not_open%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'diamond_tournaments_not_open');
      ELSIF SQLERRM LIKE '%diamond_tournament_entry_already_held%' THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'already_registered');
      END IF;
      RAISE;
    END;
  ELSIF v_split.charge > 0 THEN
    -- CHIP STANDARD 1.2 (2026-09-02): THE HORSE DOOR DECLARES EXACTLY AS THE HUMAN
    -- DOOR (R11 - horses and humans are identical on every path). The wallet write
    -- below is journaled by trg_club_members_audit_chip_movement; undeclared it landed
    -- as adjustment player_wallet -> table_stack with no tournament. set_config, not
    -- fn_ca_declare_ledger, for the same reason as fn_register_for_tournament: a
    -- vocabulary miss must never refuse a buy-in. Restored right after the write.
    v_led_cat := current_setting('app.ledger_category', true);
    v_led_cp  := current_setting('app.ledger_counterparty', true);
    v_led_ent := current_setting('app.ledger_counterparty_entity', true);
    v_led_tid := current_setting('app.ledger_tournament', true);
    PERFORM set_config('app.ledger_category', 'tournament_buyin', true);
    PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_tournament_id::text, true);
    PERFORM set_config('app.ledger_tournament', p_tournament_id::text, true);
    PERFORM set_config('app.pnl_tournament_entitlement','',true);
    v_ok := public.atomic_deduct_wallet_and_log(
      p_user_id, v_split.charge, 'tournament_buyin',
      'Tournament buy-in: ' || COALESCE(v_t.name, 'tournament'),
      NULL, NULL, p_tournament_id);
    v_original_entitlement:=NULLIF(current_setting('app.pnl_tournament_entitlement',true),'')::uuid;
    PERFORM set_config('app.ledger_category', COALESCE(v_led_cat, ''), true);
    PERFORM set_config('app.ledger_counterparty', COALESCE(v_led_cp, ''), true);
    PERFORM set_config('app.ledger_counterparty_entity', COALESCE(v_led_ent, ''), true);
    PERFORM set_config('app.ledger_tournament', COALESCE(v_led_tid, ''), true);
    IF NOT COALESCE(v_ok, false) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_balance');
    END IF;
    PERFORM set_config('app.pnl_tournament_wallet_tx','',true);
    PERFORM public.log_wallet_transaction(
      p_user_id, 'PLAYER', v_split.charge, 'debit', 'tournament_buyin',
      'Tournament buy-in: ' || COALESCE(v_t.name, 'tournament'),
      NULL, NULL, p_tournament_id);
    v_original_wallet:=NULLIF(current_setting('app.pnl_tournament_wallet_tx',true),'')::uuid;
  END IF;

  BEGIN
    IF v_dia IS NOT NULL THEN
      -- 20261005224736: the roster row carries the id the custody row was
      -- named with, and the head rides on it as it does for a chip entry so
      -- the roster trigger does not seed it a second time. The human door's
      -- Diamond insert, with the horse's own id.
      INSERT INTO public.tournament_players
        (id, tournament_id, user_id, username, chips, status, current_bounty,
         mystery_bounty_value, bounties_collected, bounty_winnings)
      VALUES (v_player_id, p_tournament_id, p_user_id, COALESCE(v_username,'Player'),
              v_start_chips, 'registered', v_head, 0, 0, 0)
      RETURNING id INTO v_player_id;
    ELSIF v_is_bounty THEN
      INSERT INTO public.tournament_players
        (tournament_id, user_id, username, chips, status, current_bounty,
         mystery_bounty_value, bounties_collected, bounty_winnings)
      VALUES (p_tournament_id, p_user_id, COALESCE(v_username,'Player'), v_start_chips,
              'registered', v_head, 0, 0, 0)
      RETURNING id INTO v_player_id;
    ELSE
      INSERT INTO public.tournament_players (tournament_id, user_id, username, chips, status)
      VALUES (p_tournament_id, p_user_id, COALESCE(v_username,'Player'), v_start_chips, 'registered')
      RETURNING id INTO v_player_id;
    END IF;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION
      'Horse tournament registration identity changed after its atomic debit; retry the complete transaction'
      USING ERRCODE = '55000';
  END;

  IF v_split.rake > 0 AND v_t.club_id IS NOT NULL AND v_unit = 1 THEN
    INSERT INTO public.rake_records
      (hand_id, table_id, club_id, rake_amount, pot_size, num_players, bbj_contribution,
       is_tournament, tournament_id, source, metadata)
    VALUES (NULL, NULL, v_t.club_id, v_split.rake, v_split.charge, 1, 0, true, p_tournament_id,
            'fn_register_horse_for_tournament',
            jsonb_build_object('kind','tournament_entry_fee','user_id',p_user_id,
                               'registration_id',v_player_id));
  END IF;

  -- The roster trigger refreshes the cached count while ANNOUNCED/REGISTERING
  -- and leaves RUNNING to the transaction that seats the late entrant - the
  -- same expectation the human core holds.
  v_expected_cached_players := CASE
    WHEN v_t.status IN ('ANNOUNCED','REGISTERING') THEN v_players_before + 1
    ELSE v_players_before
  END;
  UPDATE public.tournaments
     SET current_players = v_players_before + 1,
         prize_pool  = COALESCE(prize_pool, 0)  + v_split.prize,
         bounty_pool = COALESCE(bounty_pool, 0) + v_split.bounty,
         total_rake  = COALESCE(total_rake, 0)  + v_split.rake
   WHERE id = p_tournament_id
     AND current_players IS NOT DISTINCT FROM v_expected_cached_players;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION
      'Tournament roster cache changed during horse registration'
      USING ERRCODE='55000';
  END IF;

  -- LATE SEAT, as the human core does it: an entrant who cannot be seated is
  -- not charged - the 55000 abort rolls the debit, the roster row, the rake
  -- record and the pool increments back together.
  IF v_late_open THEN
    v_seat := public.fn_seat_late_registrant(p_tournament_id, p_user_id);
    v_seat_reason := v_seat->>'reason';
    IF NOT COALESCE((v_seat->>'ok')::boolean, false)
       AND COALESCE(v_seat_reason, '') <> 'already_seated_or_missing' THEN
      RAISE EXCEPTION
        'Late registration could not seat the player (%) - no charge has been made',
        COALESCE(v_seat_reason, 'unknown')
        USING ERRCODE = '55000';
    END IF;
  END IF;

  -- 20261005224736: the asset follows the unit, exactly as the human door
  -- records it. A chip entry still binds this transaction's actual debit IDs;
  -- a Diamond entry binds its custody receipt instead, which is what every
  -- later Diamond door reads.
  PERFORM public.fn_ca_record_tournament_participant_funding(v_player_id,'entry',NULL,
    v_split.charge,CASE WHEN v_unit=100 THEN 'diamonds' ELSE 'chips' END,
    v_original_entitlement,v_original_wallet,v_dia);

  RETURN jsonb_build_object('ok', true, 'registration_id', v_player_id,
    'cost', v_split.charge, 'prize_contribution', v_split.prize,
    'bounty_contribution', v_split.bounty, 'rake', v_split.rake,
    'late_registration', v_late_open,
    'asset', CASE WHEN v_dia IS NOT NULL THEN 'diamonds' ELSE 'chips' END,
    'diamonds_after', CASE WHEN v_dia IS NOT NULL
                           THEN (SELECT p.diamonds FROM public.profiles p WHERE p.id = p_user_id) END,
    'seat', v_seat);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_register_horse_for_tournament_before_terminal_gate(p_tournament_id uuid, p_user_id uuid, p_allow_wallet_charge boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_is_horse boolean;
  v_ticket_lookup jsonb;
  v_ticket_id uuid;
  v_ticket_registration_count integer:=0;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_allow_wallet_charge IS NULL THEN
    RAISE EXCEPTION 'tournament, horse and wallet authority are required'
      USING ERRCODE='22004';
  END IF;

  -- Ticket return, ticket admission and terminal settlement use this order.
  -- Holding both locks through the no-ticket decision prevents a concurrent
  -- unregister from issuing a ticket between selection and a wallet debit.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;

  SELECT is_horse INTO v_is_horse
    FROM public.profiles WHERE id=p_user_id;
  IF NOT COALESCE(v_is_horse,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_a_horse');
  END IF;

  -- An ambiguous-response retry arrives after the issued ticket has become
  -- redeemed. Recover that exact ticket id from the active immutable entry
  -- entitlement and let the admission core prove and replay the receipt.
  SELECT count(*),min(e.source_ticket_id::text)::uuid
    INTO v_ticket_registration_count,v_ticket_id
    FROM public.tournament_refund_entitlements e
    JOIN public.tournament_players tp ON tp.id=e.registration_id
   WHERE e.tournament_id=p_tournament_id
     AND e.user_id=p_user_id
     AND e.entitlement_kind='tournament_ticket'
     AND e.source_ticket_id IS NOT NULL
     AND tp.tournament_id=e.tournament_id
     AND tp.user_id=e.user_id
     AND tp.status::text IN ('registered','playing');
  IF v_ticket_registration_count>1 THEN
    RAISE EXCEPTION
      'horse ticket admission has multiple active immutable entitlements'
      USING ERRCODE='P0404';
  END IF;
  IF v_ticket_registration_count=1 AND v_ticket_id IS NOT NULL THEN
    RETURN public.fn_ca_register_for_tournament_with_ticket_for(
      p_tournament_id,v_ticket_id,p_user_id);
  END IF;

  v_ticket_lookup:=public.fn_ca_find_tournament_entry_ticket_for(
    p_tournament_id,p_user_id);
  IF COALESCE((v_ticket_lookup->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_ticket_lookup;
  END IF;
  v_ticket_id:=NULLIF(v_ticket_lookup->>'ticket_id','')::uuid;
  IF v_ticket_id IS NOT NULL THEN
    RETURN public.fn_ca_register_for_tournament_with_ticket_for(
      p_tournament_id,v_ticket_id,p_user_id);
  END IF;

  -- 20261015132042: a cashier ticket bound to this tournament enters the
  -- horse through the same door it enters a person (CLAUDE.md 10.5).
  v_ticket_lookup:=public.fn_ca_find_cashier_entry_ticket_for(
    p_tournament_id,p_user_id);
  v_ticket_id:=NULLIF(v_ticket_lookup->>'ticket_id','')::uuid;
  IF v_ticket_id IS NOT NULL THEN
    RETURN public.fn_ca_use_cashier_entry_ticket(
      p_tournament_id,v_ticket_id,p_user_id);
  END IF;

  IF p_allow_wallet_charge IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','hinted_tournament_ticket_no_longer_available');
  END IF;
  RETURN public.fn_register_horse_for_tournament_before_atomic_lifecycle_gate(
    p_tournament_id,p_user_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_resolve_tournament_blinds(p_blind_structure text, p_current_level integer, p_variant text, p_tournament_type text, p_total_chips numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_levels jsonb;
  v_len integer;
  v_index integer;
  v_level jsonb;
  v_last_index integer;
  v_last jsonb;
  v_is_spin boolean;
  v_continuation jsonb;
  v_float_round double precision;
  v_float_units double precision;
  v_float_integral double precision;
  v_float_bb double precision;
  v_float_sb double precision;
  v_tail_count integer;
  v_tail_first numeric;
  v_tail_last numeric;
  v_ratio numeric := 1.4;
  v_factor numeric;
  v_sb numeric;
  v_bb numeric;
  v_ante numeric;
  v_max_bb numeric;
  v_scale numeric;
  v_capped boolean := false;
  v_anchor_bb numeric;
  v_anchor_ante numeric;
  v_ante_ceiling numeric;
  v_anchor_sb numeric;
  v_sb_ceiling numeric;
BEGIN
  v_levels := public.fn_safe_jsonb_array(p_blind_structure);
  v_len := jsonb_array_length(v_levels);
  IF v_len=0 THEN
    RAISE EXCEPTION 'Tournament blind structure is missing' USING ERRCODE='55000';
  END IF;
  v_index := GREATEST(COALESCE(p_current_level,0),0);

  -- A persisted level is authoritative and is never chip-capped in the engine.
  IF v_index<v_len THEN
    v_level := v_levels->v_index;
    v_sb := COALESCE(
      CASE WHEN COALESCE(v_level->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'smallBlind')::numeric END,
      CASE WHEN COALESCE(v_level->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'small_blind')::numeric END
    );
    v_bb := COALESCE(
      CASE WHEN COALESCE(v_level->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'bigBlind')::numeric END,
      CASE WHEN COALESCE(v_level->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'big_blind')::numeric END
    );
    v_ante := COALESCE(
      CASE WHEN COALESCE(v_level->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'ante')::numeric END,
      0
    );
    RETURN jsonb_build_object(
      'small_blind',v_sb,'big_blind',v_bb,'ante',v_ante,
      'level_index',v_index,'source','persisted','blind_capped',false
    );
  END IF;

  v_is_spin := lower(COALESCE(p_variant,''))='spin'
            OR upper(COALESCE(p_tournament_type,''))='SPIN';
  IF v_is_spin THEN
    -- A funded draw freezes its continuation rule. Presence with malformed
    -- values is an error, never permission to substitute a newer local rule.
    IF (v_levels->(v_len-1)) ? 'spinContinuation' THEN
      v_continuation := v_levels->(v_len-1)->'spinContinuation';
      IF jsonb_typeof(v_continuation) IS DISTINCT FROM 'object'
         OR jsonb_typeof(v_continuation->'version') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'anchorLevel') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'anchorBigBlind') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'growth') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'roundBigTo') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'Spin blind continuation is missing its frozen formula'
          USING ERRCODE='55000';
      END IF;
      -- The booked engine formula consumes JavaScript Number values. Keep
      -- IEEE-754 arithmetic through power, division, both rounds and the
      -- final multiplication. Decimal numeric changes 100 * 1.15 / 10.
      BEGIN
        PERFORM (e.value #>> '{}')::double precision
          FROM jsonb_each(v_continuation) e
         WHERE e.key IN ('version','anchorLevel','anchorBigBlind','growth','roundBigTo');
        IF (v_continuation->>'version')::double precision<>1
           OR (v_continuation->>'anchorLevel')::double precision<=0
           OR floor((v_continuation->>'anchorLevel')::double precision)<>(v_continuation->>'anchorLevel')::double precision
           OR (v_continuation->>'anchorBigBlind')::double precision<=0
           OR (v_continuation->>'growth')::double precision<=1
           OR (v_continuation->>'roundBigTo')::double precision<=0 THEN
          RAISE EXCEPTION 'Spin blind continuation is missing its frozen formula' USING ERRCODE='55000';
        END IF;
        v_float_round := (v_continuation->>'roundBigTo')::double precision;
        v_float_units := ((v_continuation->>'anchorBigBlind')::double precision
          * power((v_continuation->>'growth')::double precision,
                  v_index::double precision+1-(v_continuation->>'anchorLevel')::double precision))
          / v_float_round;
        -- PostgreSQL round(float8) rounds ties to even. JavaScript rounds
        -- positive ties upward. Adding 0.5 first also changes near-half
        -- values, so compare the fractional part without shifting it.
        v_float_integral := floor(v_float_units);
        IF v_float_units-v_float_integral >= 0.5::double precision THEN
          v_float_integral := v_float_integral+1::double precision;
        END IF;
        v_float_bb := v_float_integral*v_float_round;
        v_float_units := v_float_bb/2::double precision;
        v_float_sb := floor(v_float_units);
        IF v_float_units-v_float_sb >= 0.5::double precision THEN
          v_float_sb := v_float_sb+1::double precision;
        END IF;
      EXCEPTION WHEN numeric_value_out_of_range THEN
        RAISE EXCEPTION 'Spin blind continuation is missing its finite frozen formula'
          USING ERRCODE='55000';
      END;
      IF v_float_bb <= 0 OR v_float_bb IN ('Infinity'::double precision,'-Infinity'::double precision,'NaN'::double precision)
         OR v_float_sb IN ('Infinity'::double precision,'-Infinity'::double precision,'NaN'::double precision) THEN
        RAISE EXCEPTION 'Spin blind continuation overflowed its stored formula'
          USING ERRCODE='55000';
      END IF;
      RETURN jsonb_build_object(
        'small_blind',v_float_sb,'big_blind',v_float_bb,'ante',0,
        'level_index',v_index,'source','spin_receipt_overflow','blind_capped',false
      );
    END IF;
    -- spinBlindsForLevel(index+1), including canonical values when a legacy
    -- persisted array is shorter than today's ten-row Spin ladder.
    v_bb := CASE v_index
      WHEN 0 THEN 20 WHEN 1 THEN 30 WHEN 2 THEN 40 WHEN 3 THEN 60
      WHEN 4 THEN 80 WHEN 5 THEN 100 WHEN 6 THEN 120 WHEN 7 THEN 150
      WHEN 8 THEN 180 WHEN 9 THEN 210
      ELSE round((210::numeric*power(1.4::numeric,v_index-9))/10)*10
    END;
    v_sb := round(v_bb/2);
    RETURN jsonb_build_object(
      'small_blind',v_sb,'big_blind',v_bb,'ante',0,
      'level_index',v_index,'source','spin_overflow','blind_capped',false
    );
  END IF;

  -- Ignore trailing break rows when choosing the overflow anchor.
  v_last_index := v_len-1;
  WHILE v_last_index>0
    AND lower(COALESCE(v_levels->v_last_index->>'isBreak','false'))='true'
  LOOP
    v_last_index := v_last_index-1;
  END LOOP;
  v_last := v_levels->v_last_index;

  -- Geometric mean of the last five positive advertised big-blind steps.
  WITH clean AS (
    SELECT e.ordinality::integer AS ord,
           COALESCE(
             CASE WHEN COALESCE(e.value->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
                  THEN (e.value->>'bigBlind')::numeric END,
             CASE WHEN COALESCE(e.value->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
                  THEN (e.value->>'big_blind')::numeric END
           ) AS bb
      FROM jsonb_array_elements(v_levels) WITH ORDINALITY AS e(value,ordinality)
  ), tail AS (
    SELECT ord,bb FROM clean WHERE bb>0 ORDER BY ord DESC LIMIT 5
  )
  SELECT count(*)::integer,
         (array_agg(bb ORDER BY ord))[1],
         (array_agg(bb ORDER BY ord DESC))[1]
    INTO v_tail_count,v_tail_first,v_tail_last
    FROM tail;
  IF v_tail_count>=2 AND v_tail_first>0 AND v_tail_last>v_tail_first THEN
    v_ratio := power(v_tail_last/v_tail_first,1::numeric/(v_tail_count-1));
    IF v_ratio<=1 THEN v_ratio := 1.4; END IF;
  END IF;
  v_ratio := LEAST(1.6,GREATEST(1.15,v_ratio));
  v_factor := power(
    v_ratio,
    LEAST(GREATEST(1,v_index-v_len+1),40)
  );

  v_sb := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'smallBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'small_blind')::numeric END,
    0
  )*v_factor,10000000);
  v_bb := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'bigBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'big_blind')::numeric END,
    0
  )*v_factor,10000000);
  v_ante := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'ante')::numeric END,
    0
  )*v_factor,10000000);

  -- Match capLevelToTournamentChips for generic overflow. The database wrapper
  -- supplies the exact durable chip issuance total; NULL means cap nothing.
  IF p_total_chips>0 THEN
    v_max_bb := p_total_chips/20;
    IF v_bb>v_max_bb AND v_max_bb>=2 THEN
      v_scale := v_max_bb/v_bb;
      v_bb := GREATEST(2,floor(v_bb*v_scale));
      v_sb := GREATEST(1,floor(v_sb*v_scale));
      v_ante := CASE WHEN v_ante>0 THEN GREATEST(1,floor(v_ante*v_scale)) ELSE 0 END;
      v_capped := true;
    END IF;
  END IF;

  /* A CAPPED LEVEL IS STILL A BLIND LEVEL (2026-09-09). Both ceilings above
     are applied to smallBlind, bigBlind and ante independently, so a deep
     overflow clamps all three to the same number and the level leaves here
     with SB = BB = ante. That is not a blind level: it makes
     fn_ensure_late_registration_capacity refuse the event a table for ever
     (v_sb>=v_bb), and the engine deals from this same answer. Enforce the
     invariant after the clamps instead of trusting it to survive them. */
  IF v_bb IS NULL OR v_bb < 2 THEN
    v_bb := 2;
    v_capped := true;
  END IF;
  IF v_sb IS NULL OR v_sb >= v_bb THEN
    v_sb := GREATEST(1, floor(v_bb / 2));
    v_capped := true;
  END IF;

  /* THE SMALL BLIND KEEPS ITS AUTHORED SHARE OF THE BIG BLIND (2026-09-21).
     The repair immediately above fires only on SB >= BB, which is the END of
     the distortion and not the whole of it. Between the level where the big
     blind reaches the 10,000,000 ceiling and the level where the small blind
     reaches it too, the big blind is pinned and the small blind is still
     growing underneath it: SB < BB throughout, nothing fires, and an authored
     1:2 walks up through 0.63 and 0.84 towards 1:1 while reporting
     blind_capped false. 528 published levels were sitting in that band on
     2026-09-21, 48 of them at 0.9762 of their big blind.

     The small blind's authored relationship to the big blind lives on the same
     anchor row this branch already grew both of them from, so read it there
     and hold the small blind to it - the ante ceiling below does exactly this
     with ante:bigBlind. This is a CEILING and never a floor: it can only lower
     a small blind, so no level becomes more expensive than it is today. An
     anchor authoring sb >= bb is left alone, because the repair above has
     already put the small blind at half the big blind and raising it back is
     not this ceiling's job. */
  v_anchor_sb := COALESCE(
    CASE WHEN COALESCE(v_last->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'smallBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'small_blind')::numeric END,
    0
  );
  v_anchor_bb := COALESCE(
    CASE WHEN COALESCE(v_last->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'bigBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'big_blind')::numeric END,
    0
  );
  IF v_sb > 0 AND v_anchor_bb > 0 AND v_anchor_sb > 0
     AND v_anchor_sb < v_anchor_bb THEN
    -- Multiply before dividing: the proportion itself is never materialised,
    -- so an anchor like 1500000/4000000 stays exact instead of losing its last
    -- digit to a rounded quotient.
    v_sb_ceiling := v_bb * v_anchor_sb / v_anchor_bb;
    -- Compared unrounded, assigned rounded: a level already sitting at its
    -- authored proportion is left alone rather than shaved by the floor.
    IF v_sb > v_sb_ceiling THEN
      v_sb := GREATEST(1, floor(v_sb_ceiling));
      v_capped := true;
    END IF;
  END IF;
  IF v_ante IS NULL OR v_ante < 0 THEN
    v_ante := 0;
  END IF;

  /* THE ANTE KEEPS ITS AUTHORED SHARE OF THE BIG BLIND (2026-09-20). The
     2026-09-09 repair above restored SB < BB after the two ceilings, but the
     ante left here still carrying whatever the 10,000,000 ceiling had
     saturated it to - on a deep overflow, the big blind itself. Two RUNNING
     events were dealing ante = BB on 2026-09-20.

     The ante's authored relationship to the big blind lives on the same
     anchor row this branch already grew SB and BB from, so read it there and
     hold the ante to it. This is a CEILING and never a floor: it can only
     lower an ante, so no level becomes more expensive than it is today. A
     structure that authors ante = BB (a big blind ante; AnteMath.ts counts
     two of them) has a proportion of 1 and is unchanged. A structure with no
     ante never reaches here with one. */
  v_anchor_bb := COALESCE(
    CASE WHEN COALESCE(v_last->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'bigBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'big_blind')::numeric END,
    0
  );
  v_anchor_ante := COALESCE(
    CASE WHEN COALESCE(v_last->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'ante')::numeric END,
    0
  );
  IF v_ante > 0 THEN
    IF v_anchor_bb > 0 AND v_anchor_ante >= v_anchor_bb THEN
      -- A big blind ante authors ante = bigBlind. AnteMath.ts reads
      -- `ante >= bigBlind` as "this structure authored a TOTAL"; rounding the
      -- ante a fraction of a chip below a fractional big blind would flip that
      -- test and charge the table ante x seats instead. Hold it at the big
      -- blind exactly.
      v_ante_ceiling := v_bb;
    ELSIF v_anchor_bb > 0 AND v_anchor_ante > 0 THEN
      -- Multiply before dividing: the proportion itself is never materialised,
      -- so an anchor like 200000/1500000 stays exact instead of losing its
      -- last digit to a rounded quotient.
      v_ante_ceiling := v_bb * v_anchor_ante / v_anchor_bb;
    ELSE
      v_ante_ceiling := v_bb;
    END IF;
    -- Compared unrounded, assigned rounded: a level already sitting at its
    -- authored proportion is left alone rather than shaved by the floor.
    IF v_ante > v_ante_ceiling THEN
      v_ante := GREATEST(1, floor(v_ante_ceiling));
      v_capped := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'small_blind',v_sb,'big_blind',v_bb,'ante',v_ante,
    'level_index',v_index,'source','mtt_overflow',
    'overflow_ratio',v_ratio,'blind_capped',v_capped
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_seat_late_registrant(p_tournament_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_gate jsonb;
BEGIN
  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    p_tournament_id,NULL,p_user_id);
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;
  RETURN public.fn_seat_late_registrant_before_terminal_seat_gate(
    p_tournament_id,p_user_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_seat_late_registrant_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_start_chips integer;
  v_club uuid;
  v_bonus integer;
  v_chips integer;
  v_table uuid;
  v_cap int;
  v_seat int;
  v_taken int;
  v_opened boolean := false;
  v_capacity jsonb;
BEGIN
  PERFORM set_config('app.money_path', 'fn_seat_late_registrant', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)
  SELECT status, COALESCE(starting_chips, 0), club_id
    INTO v_status, v_start_chips, v_club
    FROM public.tournaments WHERE id = p_tournament_id;

  IF v_status IS DISTINCT FROM 'RUNNING' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_running');
  END IF;

  SELECT COALESCE(chips, 0) INTO v_bonus
    FROM public.tournament_players
   WHERE tournament_id = p_tournament_id
     AND user_id = p_user_id
     AND table_id IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.table_seats s
        JOIN public.tables tb ON tb.id = s.table_id
       WHERE tb.tournament_id = p_tournament_id
         AND s.user_id = p_user_id
         AND s.left_at IS NULL
     )
     FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_seated_or_missing');
  END IF;

  v_chips := v_start_chips + GREATEST(v_bonus, 0);

  SELECT tb.id, COALESCE(tb.max_players, 9)
    INTO v_table, v_cap
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) IN ('waiting', 'running', 'active')
     AND COALESCE(tb.is_deleted,false)=false
     AND (
       SELECT count(*) FROM public.table_seats s
        WHERE s.table_id = tb.id AND s.left_at IS NULL
     ) < COALESCE(tb.max_players, 9)
   ORDER BY (
       SELECT count(*) FROM public.table_seats s
        WHERE s.table_id = tb.id AND s.left_at IS NULL
     ) DESC, tb.created_at ASC
   LIMIT 1
     FOR UPDATE OF tb;

  -- Capacity owns the table format, current blinds, legal chairs and durable
  -- manager receipt. The entry already exists here, so reserve no second entry.
  IF v_table IS NULL THEN
    v_capacity := public.fn_ensure_late_registration_capacity(p_tournament_id,0);
    v_table := NULLIF(v_capacity->>'table_id','')::uuid;
    IF COALESCE((v_capacity->>'ok')::boolean,false) IS NOT TRUE
       OR v_table IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','no_open_seat');
    END IF;
    SELECT tb.max_players INTO STRICT v_cap FROM public.tables tb
     WHERE tb.id=v_table AND tb.tournament_id=p_tournament_id
       AND tb.status IN ('waiting','running','active')
       AND COALESCE(tb.is_deleted,false)=false FOR UPDATE;
    v_opened := COALESCE((v_capacity->>'created')::boolean,false);
  END IF;

  SELECT g.n INTO v_seat
    FROM generate_series(1, v_cap) AS g(n)
   WHERE NOT EXISTS (
     SELECT 1 FROM public.table_seats s
      WHERE s.table_id = v_table AND s.seat_number = g.n AND s.left_at IS NULL
   )
   ORDER BY g.n LIMIT 1;

  IF v_seat IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_open_seat');
  END IF;

  UPDATE public.table_seats
     SET user_id        = p_user_id,
         stack          = v_chips,
         left_at        = NULL,
         joined_at      = now(),
         is_sitting_out = false,
         is_away        = false,
         club_id        = COALESCE(club_id, v_club)
   WHERE table_id = v_table AND seat_number = v_seat AND left_at IS NOT NULL;

  IF NOT FOUND THEN
    BEGIN
      INSERT INTO public.table_seats (table_id, user_id, seat_number, stack, club_id)
      VALUES (v_table, p_user_id, v_seat, v_chips, v_club);
    EXCEPTION WHEN unique_violation THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'seat_race');
    END;
  END IF;

  UPDATE public.tournament_players
     SET status      = 'playing',
         chips       = v_chips,
         table_id    = v_table,
         seat_number = v_seat
   WHERE tournament_id = p_tournament_id AND user_id = p_user_id;

  SELECT count(*) INTO v_taken
    FROM public.table_seats WHERE table_id = v_table AND left_at IS NULL;
  UPDATE public.tables SET current_players = v_taken WHERE id = v_table;

  RETURN jsonb_build_object('ok', true, 'table_id', v_table,
    'seat_number', v_seat, 'chips', v_chips, 'opened_table', v_opened);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_seat_late_registrant_before_terminal_seat_gate(p_tournament_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;
  RETURN public.fn_seat_late_registrant_before_maintenance_gate(
    p_tournament_id, p_user_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_short_formats_never_break()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF (TG_OP='INSERT' OR OLD.format_contract IN ('mtt-v1','mtt-v2'))
     AND public.fn_ca_new_tournament_is_unlimited(to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF upper(COALESCE(NEW.tournament_type, '')) IN ('SPIN', 'SNG')
     OR lower(COALESCE(NEW.variant, '')) IN ('spin', 'sng')
  THEN
    NEW.synchronized_breaks := false;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_stage_a_bridge_legacy_capacity_receipt(p_table_id uuid, p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_headers jsonb;
  v_claims jsonb;
  v_request_role text;
  v_actor_marker text;
  v_method text;
  v_path text;
  v_wake_id bigint;
  v_stale_seconds constant integer := 30;
BEGIN
  IF p_table_id IS NULL OR p_tournament_id IS NULL THEN
    RETURN false;
  END IF;

  BEGIN
    v_headers := COALESCE(
      NULLIF(current_setting('request.headers', true), '')::jsonb,
      '{}'::jsonb
    );
    v_claims := COALESCE(
      NULLIF(current_setting('request.jwt.claims', true), '')::jsonb,
      '{}'::jsonb
    );
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION
      'DATA_ACTOR_INVALID: malformed legacy capacity request context'
      USING ERRCODE = '22023';
  END;

  v_request_role := btrim(COALESCE(auth.role(), ''));
  v_actor_marker := btrim(
    COALESCE(current_setting('app.smarter_data_actor', true), '')
  );
  v_method := upper(
    btrim(COALESCE(current_setting('request.method', true), ''))
  );
  v_path := lower(
    btrim(COALESCE(current_setting('request.path', true), ''), '/')
  );
  IF left(v_path, 8) = 'rest/v1/' THEN
    v_path := substr(v_path, 9);
  END IF;

  IF v_request_role <> 'service_role'
     OR btrim(COALESCE(v_claims ->> 'role', '')) <> 'service_role'
     OR btrim(COALESCE(v_headers ->> 'x-smarter-data-actor', '')) <> ''
     OR btrim(COALESCE(v_headers ->> 'x-smarter-data-protocol', '')) <> ''
     OR btrim(COALESCE(v_headers ->> 'x-smarter-tournament-id', '')) <> ''
     OR btrim(
          COALESCE(
            v_headers ->> 'x-smarter-tournament-lease-generation',
            ''
          )
        ) <> ''
     OR v_actor_marker NOT IN ('', 'legacy-unmarked')
     OR COALESCE(
          current_setting('app.smarter_manager_request_fenced', true),
          ''
        ) <> ''
     OR v_method <> 'POST'
     OR v_path <> 'tables' THEN
    RETURN false;
  END IF;

  /* This row lock is the rolling cutover handoff. Lease replacement and the
     Stage-B relation lock cannot cross the raw table INSERT transaction. */
  PERFORM 1
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
     AND l.protocol_version = 1
     AND l.heartbeat_at >=
         clock_timestamp() - make_interval(secs => v_stale_seconds)
   FOR SHARE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  v_wake_id := public.fn_emit_tournament_manager_wake(
    p_tournament_id,
    'late_registration'
  );
  IF v_wake_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.tournament_capacity_table_receipts (
    table_id,
    tournament_id,
    manager_wake_id
  ) VALUES (
    p_table_id,
    p_tournament_id,
    v_wake_id
  );

  /* Match the canonical capacity function's level-triggered receipt rule:
     every still-unadmitted table points at the newest pending wake. */
  UPDATE public.tournament_capacity_table_receipts
     SET manager_wake_id = v_wake_id,
         updated_at = clock_timestamp()
   WHERE tournament_id = p_tournament_id
     AND manager_admitted_at IS NULL;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_current_blinds(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_entrants bigint;
  v_rebuys bigint;
  v_addons bigint;
  v_total_chips numeric := NULL;
BEGIN
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
  END IF;

  SELECT count(*) INTO v_entrants
    FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id;
  SELECT count(*) INTO v_rebuys
    FROM public.wallet_transactions wt
   WHERE wt.related_entity_id=p_tournament_id AND wt.category='rebuy';
  SELECT count(*) INTO v_addons
    FROM public.wallet_transactions wt
   WHERE wt.related_entity_id=p_tournament_id AND wt.category='addon';
  IF COALESCE(v_t.starting_chips,0)>0 AND v_entrants>0 THEN
    v_total_chips := v_t.starting_chips*v_entrants
      +COALESCE(NULLIF(v_t.rebuy_chips,0),v_t.starting_chips)*v_rebuys
      +COALESCE(NULLIF(v_t.addon_chips,0),v_t.starting_chips)*v_addons;
  END IF;

  RETURN public.fn_resolve_tournament_blinds(
    v_t.blind_structure::text,
    COALESCE(v_t.current_level,0),
    v_t.variant,
    v_t.tournament_type,
    v_total_chips
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_entry_cap_reached(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cap      integer;
  v_counter  integer;
  v_entries  integer;
BEGIN
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  SELECT t.max_players, COALESCE(t.current_players, 0)
    INTO v_cap, v_counter
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;

  IF NOT FOUND OR public.fn_ca_tournament_is_unlimited(p_tournament_id)
     OR v_cap IS NULL OR v_cap <= 0 THEN
    RETURN false;                      -- uncapped: this function never refuses
  END IF;

  SELECT count(*) INTO v_entries
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  /* GREATEST, never the entry count alone: this can only ever be stricter than
     the counter test it replaces, never looser. */
  RETURN GREATEST(v_counter, COALESCE(v_entries, 0)) >= v_cap;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_entry_split(p_buy_in numeric, p_fee numeric, p_bounty numeric, p_is_bounty boolean)
 RETURNS TABLE(charge numeric, rake numeric, bounty numeric, prize numeric)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_charge numeric; v_rake numeric; v_bounty numeric; v_prize numeric;
BEGIN
  IF NOT COALESCE(p_is_bounty, false) THEN
    -- Non-bounty: unchanged - fee charged on top of the buy-in portion.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := 0;
    v_prize  := round(COALESCE(p_buy_in,0),2);
  ELSE
    -- Bounty event: the rake is exactly the fee. A zero fee is a legitimate
    -- outcome of the whole-number floor rule (totals under 10 take no rake)
    -- and must NEVER be replaced with a percentage default.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := round(COALESCE(p_bounty,0), 2);
    v_prize  := round(v_charge - v_rake - v_bounty, 2);  -- = buy_in - bounty
  END IF;
  RETURN QUERY SELECT v_charge, v_rake, v_bounty, v_prize;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_management_readiness_for_row(p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid := NULLIF(p_row ->> 'id', '')::uuid;
  v_club uuid := NULLIF(p_row ->> 'club_id', '')::uuid;
  v_row_union uuid := NULLIF(p_row ->> 'union_id', '')::uuid;
  v_union uuid;
  v_private boolean := COALESCE((p_row ->> 'is_private')::boolean, false);
  v_enforce boolean;
  v_floor numeric;
  v_bank numeric;
  v_bank_type text;
  v_exposure numeric;
  v_guaranteed numeric := COALESCE(NULLIF(p_row ->> 'guaranteed_prize', '')::numeric, 0);
  v_pool numeric := COALESCE(NULLIF(p_row ->> 'prize_pool', '')::numeric, 0);
  v_effective_guarantee numeric;
  v_seat_guarantee numeric := 0;
  v_required numeric;
  v_short numeric;
  v_portfolio_short numeric;
  v_locked boolean;
  v_complete boolean;
  v_status text := upper(COALESCE(p_row ->> 'status', ''));
  v_variant text := lower(COALESCE(p_row ->> 'variant', ''));
  v_tournament_type text := upper(COALESCE(p_row ->> 'tournament_type', ''));
  v_target uuid := COALESCE(
    NULLIF(p_row ->> 'satellite_target_id', ''),
    NULLIF(p_row ->> 'satellite_target', '')
  )::uuid;
  v_satellite_seats integer := COALESCE(
    NULLIF(p_row ->> 'satellite_seats', '')::integer,
    0
  );
  v_is_satellite boolean := v_variant = 'satellite'
    OR v_tournament_type = 'SATELLITE'
    OR v_target IS NOT NULL;
  v_target_found boolean := false;
  v_blinds jsonb;
  v_payouts jsonb;
BEGIN
  IF v_id IS NULL OR v_club IS NULL THEN
    RETURN jsonb_build_object('state', 'missing', 'can_start', false);
  END IF;

  SELECT COALESCE(c.guarantee_enforcement_enabled, true),
         COALESCE(c.guarantee_treasury_floor, 0)
    INTO v_enforce, v_floor
    FROM public.clubs c
   WHERE c.id = v_club;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('state', 'missing', 'can_start', false);
  END IF;

  v_union := CASE WHEN v_private THEN NULL ELSE v_row_union END;

  IF v_is_satellite AND v_satellite_seats > 0 AND v_target IS NOT NULL THEN
    SELECT round(
             (COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0))
             * v_satellite_seats,
             2
           )
      INTO v_seat_guarantee
      FROM public.tournaments t
     WHERE t.id = v_target;
    v_target_found := FOUND;
    v_seat_guarantee := COALESCE(v_seat_guarantee, 0);
  END IF;

  v_effective_guarantee := greatest(v_guaranteed, v_seat_guarantee);

  IF v_union IS NOT NULL THEN
    v_bank_type := 'union';
    v_floor := 0;
    SELECT COALESCE(uw.chip_balance, 0)
      INTO v_bank
      FROM public.union_wallets uw
     WHERE uw.union_id = v_union;
    v_bank := COALESCE(v_bank, 0);

    SELECT COALESCE(sum(greatest(
             greatest(
               COALESCE(t.guaranteed_prize, 0),
               CASE
                 WHEN COALESCE(t.satellite_seats, 0) > 0
                      AND (
                        lower(COALESCE(t.variant, '')) = 'satellite'
                        OR upper(COALESCE(t.tournament_type, '')) = 'SATELLITE'
                        OR COALESCE(t.satellite_target_id, t.satellite_target) IS NOT NULL
                      )
                 THEN COALESCE(
                   (COALESCE(target.buy_in_amount, 0) + COALESCE(target.buy_in_fee, 0))
                   * t.satellite_seats,
                   0
                 )
                 ELSE 0
               END
             ) - COALESCE(t.prize_pool, 0),
             0
           )), 0)
      INTO v_exposure
      FROM public.tournaments t
      LEFT JOIN public.tournaments target
        ON target.id = COALESCE(t.satellite_target_id, t.satellite_target)
     WHERE t.union_id = v_union
       AND NOT COALESCE(t.is_private, false)
       AND t.id <> v_id
       AND NOT COALESCE(t.prize_pool_finalized, false)
       AND upper(t.status::text) IN ('ANNOUNCED', 'REGISTERING', 'RUNNING');
  ELSE
    v_bank_type := 'club';
    SELECT COALESCE(c.chip_treasury, 0)
      INTO v_bank
      FROM public.clubs c
     WHERE c.id = v_club;
    v_bank := COALESCE(v_bank, 0);

    SELECT COALESCE(sum(greatest(
             greatest(
               COALESCE(t.guaranteed_prize, 0),
               CASE
                 WHEN COALESCE(t.satellite_seats, 0) > 0
                      AND (
                        lower(COALESCE(t.variant, '')) = 'satellite'
                        OR upper(COALESCE(t.tournament_type, '')) = 'SATELLITE'
                        OR COALESCE(t.satellite_target_id, t.satellite_target) IS NOT NULL
                      )
                 THEN COALESCE(
                   (COALESCE(target.buy_in_amount, 0) + COALESCE(target.buy_in_fee, 0))
                   * t.satellite_seats,
                   0
                 )
                 ELSE 0
               END
             ) - COALESCE(t.prize_pool, 0),
             0
           )), 0)
      INTO v_exposure
      FROM public.tournaments t
      LEFT JOIN public.tournaments target
        ON target.id = COALESCE(t.satellite_target_id, t.satellite_target)
     WHERE t.club_id = v_club
       AND (COALESCE(t.is_private, false) OR t.union_id IS NULL)
       AND t.id <> v_id
       AND NOT COALESCE(t.prize_pool_finalized, false)
       AND upper(t.status::text) IN ('ANNOUNCED', 'REGISTERING', 'RUNNING');
  END IF;

  v_required := greatest(v_effective_guarantee - v_pool, 0);
  -- AN EVENT IS REFUSED ONLY FOR ITS OWN UNCOVERED OVERLAY (2026-10-02).
  -- The bank's coverage of OTHER events' guarantees is not this event's
  -- promise: a Spin, a Sit & Go, a heads-up satellite or a freezeout with no
  -- guarantee needs no overlay and is never refused for the bank, and an
  -- event with a guarantee is refused only when the bank (above the club's
  -- floor) cannot pay its own overlay. The bank-wide position is still
  -- reported, as portfolio_short_by, for the owners' bank warnings.
  v_portfolio_short := greatest(
    COALESCE(v_floor, 0) + COALESCE(v_exposure, 0) + v_required - v_bank,
    0
  );
  v_short := CASE
    WHEN v_required > 0 THEN greatest(COALESCE(v_floor, 0) + v_required - v_bank, 0)
    ELSE 0
  END;
  -- 2026-10-06 (20261007000010): A DIAMOND EVENT'S BANK IS ITS EARMARK. The
  -- Diamond Arena holds no chips; its guarantee is set aside on the house at
  -- creation under 'guarantee:<id>', so that earmark, and nothing else, is
  -- what covers this event's own overlay.
  IF v_row_union IS NULL AND EXISTS (SELECT 1 FROM public.clubs c
                                      WHERE c.id = v_club AND c.asset = 'diamonds'
                                        AND c.is_platform IS TRUE AND c.union_id IS NULL) THEN
    v_bank_type := 'diamond_house_earmark';
    v_bank := public.fn_ca_diamond_earmark_open('guarantee:' || v_id::text);
    v_floor := 0;
    v_exposure := 0;
    v_portfolio_short := greatest(v_required - v_bank, 0);
    v_short := CASE WHEN v_required > 0 THEN greatest(v_required - v_bank, 0) ELSE 0 END;
  END IF;
  v_locked := EXISTS (
    SELECT 1
      FROM public.tournament_players tp
     WHERE tp.tournament_id = v_id
  );

  v_blinds := CASE
    WHEN jsonb_typeof(p_row -> 'blind_structure') = 'array'
      THEN p_row -> 'blind_structure'
    ELSE public.fn_safe_jsonb_array(p_row ->> 'blind_structure')
  END;
  v_payouts := CASE
    WHEN jsonb_typeof(p_row -> 'payout_structure') = 'array'
      THEN p_row -> 'payout_structure'
    ELSE public.fn_safe_jsonb_array(p_row ->> 'payout_structure')
  END;

  v_complete := NULLIF(trim(COALESCE(p_row ->> 'name', '')), '') IS NOT NULL
    AND (
      NULLIF(p_row ->> 'start_time', '') IS NOT NULL
      OR v_tournament_type IN ('SNG', 'SPIN')
      OR v_variant IN ('sng', 'spin')
    )
    AND COALESCE(NULLIF(p_row ->> 'starting_chips', '')::numeric, 0) > 0
    AND ((p_row->>'format_contract' IS NOT DISTINCT FROM 'mtt-v2' AND p_row->>'max_players' IS NULL
          AND COALESCE(NULLIF(p_row->>'min_players','')::integer,0)>=3)
      OR COALESCE(NULLIF(p_row ->> 'max_players', '')::integer, 0) >= 2)
    AND COALESCE(NULLIF(p_row ->> 'buy_in_amount', '')::numeric, 0) >= 0
    AND jsonb_array_length(v_blinds) > 0
    AND (
      jsonb_array_length(v_payouts) > 0
      OR v_tournament_type = 'SPIN'
      OR v_variant = 'spin'
    )
    AND (
      NOT v_is_satellite
      OR (v_satellite_seats > 0 AND v_target IS NOT NULL AND v_target_found)
      -- DIAMOND PHASE 9: a Diamond satellite promises no seat. A seat count
      -- promised in advance is a guarantee; a Diamond guarantee is funded only
      -- from an authorised Diamond house budget, which is not built and whose
      -- size is the owner's, and the creation door refuses one by name. The
      -- satellite's own prize bank buys whole seats in its Diamond target at
      -- settlement, so its contract is complete with none promised. The test
      -- is fn_poker_diamond_tournament's, read from the row.
      OR (v_satellite_seats = 0 AND v_target IS NOT NULL AND v_row_union IS NULL
          AND EXISTS (SELECT 1 FROM public.clubs c
                       WHERE c.id = v_club AND c.asset = 'diamonds'
                         AND c.is_platform IS TRUE AND c.union_id IS NULL)
          AND public.fn_poker_diamond_tournament(v_target))
    );

  RETURN jsonb_build_object(
    'state', CASE
      WHEN v_status IN ('COMPLETED', 'CANCELLED', 'CANCELED') THEN 'closed'
      WHEN NOT v_complete THEN 'incomplete'
      WHEN v_enforce AND v_short > 0 THEN 'funding_blocked'
      ELSE 'ready'
    END,
    'can_start', v_status NOT IN ('COMPLETED', 'CANCELLED', 'CANCELED')
      AND v_complete
      AND (NOT v_enforce OR v_short = 0),
    'contract_locked', v_locked,
    'guarantee_enforced', v_enforce,
    'guaranteed_prize', v_guaranteed,
    'satellite_seat_guarantee', v_seat_guarantee,
    'effective_guarantee', v_effective_guarantee,
    'current_prize_pool', v_pool,
    'overlay_required', v_required,
    'bank_type', v_bank_type,
    'bank_balance', v_bank,
    'bank_floor', COALESCE(v_floor, 0),
    'other_live_exposure', COALESCE(v_exposure, 0),
    'short_by', v_short,
    'portfolio_short_by', v_portfolio_short
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournaments_bagged_status_door()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'BAGGED' THEN
      RAISE EXCEPTION 'TOURNAMENT_BAGGED_REQUIRES_STAGE_BAG: a tournament is never created bagged'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'BAGGED' THEN
    IF OLD.status IS DISTINCT FROM 'RUNNING'
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_stage_transitions x
          WHERE x.tournament_id = NEW.id
            AND x.kind = 'bag'
            AND x.transaction_id = pg_current_xact_id()
            AND current_setting('app.atomic_stage_bag', true) = NEW.id::text || ':' || x.id::text) THEN
      RAISE EXCEPTION 'TOURNAMENT_BAGGED_REQUIRES_STAGE_BAG: % to BAGGED belongs to the stage bag RPC', OLD.status
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'BAGGED' THEN
    IF NEW.status IS DISTINCT FROM 'RUNNING'
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_stage_resume_receipts r
          WHERE r.tournament_id = NEW.id
            AND r.completed_at IS NULL
            AND current_setting('app.atomic_stage_resume', true) = NEW.id::text || ':' || r.resume_id::text) THEN
      RAISE EXCEPTION 'TOURNAMENT_BAGGED_LEAVES_ONLY_BY_STAGE_RESUME: BAGGED to % refused', NEW.status
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_tournaments_creation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_paid int;
BEGIN
  IF public.fn_ca_new_tournament_is_unlimited(to_jsonb(NEW)) THEN
    RETURN NEW; -- The earlier normalizer and final recorded-format constraint own NULL.
  END IF;
  IF COALESCE(NEW.max_players, 0) <= 0 THEN
    RAISE EXCEPTION
      'tournament guard: max_players must be positive (got %) - a tournament with no seats can never start',
      NEW.max_players
      USING ERRCODE = '23514';
  END IF;

  IF NEW.payout_structure IS NOT NULL
     AND jsonb_typeof(NEW.payout_structure::jsonb) = 'array' THEN
    v_paid := jsonb_array_length(NEW.payout_structure::jsonb);
    IF v_paid > NEW.max_players THEN
      RAISE EXCEPTION
        'tournament guard: % paid places for % seats - more places than players who can enter',
        v_paid, NEW.max_players
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_observe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prior jsonb; following jsonb; frame public.union_pnl_transaction_frames;
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'pnl_inventory_source_truncate_refused' USING ERRCODE='55000'; END IF;
 IF TG_OP<>'INSERT' THEN prior:=public.fn_union_pnl_inventory_project(TG_TABLE_NAME,to_jsonb(OLD)); END IF;
 IF TG_OP<>'DELETE' THEN following:=public.fn_union_pnl_inventory_project(TG_TABLE_NAME,to_jsonb(NEW)); END IF;
 IF prior IS NOT DISTINCT FROM following THEN RETURN NULL; END IF;
 frame:=public.fn_union_pnl_original_frame();
 INSERT INTO public.union_pnl_inventory_events(source_name,row_id,observed_at,transaction_id,operation,before_row,after_row)
 VALUES(TG_TABLE_NAME,(COALESCE(following,prior)->>'id')::uuid,frame.observed_at,frame.transaction_id,TG_OP,prior,following);
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_project(p_source text, p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE keys text[]; result jsonb;
BEGIN
 IF p_row IS NULL THEN RETURN NULL; END IF;
 keys:=CASE p_source
  WHEN 'union_clubs' THEN ARRAY['id','union_id','club_id','joined_at']
  WHEN 'tables' THEN ARRAY['id','club_id','union_id','tournament_id','is_private']
  WHEN 'table_seats' THEN ARRAY['id','table_id','user_id','club_id','occupancy_id','joined_at','left_at','stack']
  WHEN 'tournaments' THEN ARRAY['id','club_id','union_id','is_private','status','started_at','ended_at','prize_pool','bounty_pool','bounty_pool_paid']
  WHEN 'tournament_players' THEN ARRAY['id','tournament_id','user_id','club_id','status','registered_at','eliminated_at','prize','bounty_winnings','source_satellite_id']
  ELSE NULL END;
 IF keys IS NULL OR NOT p_row ?& keys THEN RAISE EXCEPTION 'pnl_inventory_source_contract_changed:%',p_source USING ERRCODE='55000'; END IF;
 SELECT jsonb_object_agg(k,p_row->k) INTO result FROM unnest(keys) k;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_original_frame()
 RETURNS union_pnl_transaction_frames
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE frame public.union_pnl_transaction_frames; observed timestamptz; book timestamptz;
BEGIN
 SELECT * INTO frame FROM public.union_pnl_transaction_frames WHERE transaction_id=pg_current_xact_id();
 IF FOUND THEN RETURN frame; END IF;
 observed:=clock_timestamp(); book:=public.fn_union_week_start(observed);
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
 observed:=clock_timestamp();
 IF public.fn_union_week_start(observed)<>book THEN
  book:=public.fn_union_week_start(observed);
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  observed:=clock_timestamp();
  IF public.fn_union_week_start(observed)<>book THEN RAISE EXCEPTION 'pnl_frame_clock_crossed_twice' USING ERRCODE='40001'; END IF;
 END IF;
 INSERT INTO public.union_pnl_transaction_frames VALUES(pg_current_xact_id(),observed,book) RETURNING * INTO frame;
 RETURN frame;
END $function$

CREATE OR REPLACE FUNCTION public.fn_unregister_from_tournament(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid:=auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_unregister_from_tournament requires an authenticated caller'
      USING ERRCODE='28000';
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'fn_unregister_from_tournament requires a live session'
      USING ERRCODE='28000';
  END IF;
  RETURN public.fn_ca_unregister_tournament_player_exact(
    p_tournament_id,v_uid,NULL,'Tournament unregistration refund');
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_unregister_from_tournament(p_tournament_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid:=auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_unregister_from_tournament requires an authenticated caller'
      USING ERRCODE='28000';
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'fn_unregister_from_tournament requires a live session'
      USING ERRCODE='28000';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'fn_unregister_from_tournament requires a request id'
      USING ERRCODE='22004';
  END IF;
  -- DIAMOND PHASE 8: a Diamond entry goes home through its own authority.
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RETURN public.fn_poker_diamond_tournament_unregister(p_tournament_id,v_uid,p_request_id);
  END IF;
  RETURN public.fn_ca_unregister_tournament_player_exact(
    p_tournament_id,v_uid,NULL,'Tournament unregistration refund',p_request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_auto_cashout_on_table_close()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tournament_id IS NOT NULL THEN RETURN NEW; END IF;
  -- An occupied table cannot close. The engine owns its departures.
  -- Do not convert this refusal into a warning and commit a closed table.
  PERFORM public.fn_cashout_seats_for_closing_table(NEW.id,'table '||NEW.status);
  RETURN NEW;
END;
$function$
